// claude:2026-10-24T21:16:00+02:00 — Textpass 1.4 Paket P4b (Chef 24.10.: alle Items ohne Beschreibung bekommen eine).
// 974 neue Beschreibungen EN/DE, je Item gegen Rezept, Drop-Quelle, Werte und Effekt geprüft (Quellen und Fakten:
// design/lore/textpass-1.4/p4b/*.json, Feld `fakten`). Eingehängt in index.ts VOR dem Sprach-Overlay; setzt nur, wo
// ein Item noch keine Beschreibung hat. Reine Anzeigetexte, save-neutral.
export const ITEM_DESCRIPTIONS_14: Record<string, { en: string; de: string }> = {
  "abyssal_devourer_fang": { en: "A fang of the Abyssal Devourer, broken off at the bottom of the Tower. What it leaves in a wound keeps eating after the fang is gone.", de: "Ein Reißzahn des Abyssalen Verschlingers, tief im Turm gebrochen. Was er in der Wunde lässt, frisst weiter, wenn der Zahn längst draußen ist." },
  "abyssal_feast": { en: "Abyssal crawler and wyvern under starcap truffle and nightbloom. A hunter's feast: quick hands, light feet and a little luck on the side.", de: "Abgrund-Kriecher und Wyvern unter Sternkappen-Trüffel und Nachtblüte. Ein Jägerfestmahl: flinke Hände, leichte Füße und etwas Glück dazu." },
  "abyssal_signet": { en: "A ring cut from a scale of the Abyssal Tide Serpent, still wet on the inside. Every wound it deals pours a little back into the ward.", de: "Ein Ring aus einer Schuppe der Abyssalen Gezeitenschlange, innen noch nass. Jede Wunde, die er schlägt, gießt etwas in den Ward zurück." },
  "abyssal_tide_bow": { en: "A rib of the Abyssal Tide Serpent, strung with kelp cord. It shoots the cold of the deep, and the cold slows what it holds.", de: "Eine Rippe der Abyssalen Gezeitenschlange, mit Tangschnur bespannt. Sie schießt die Kälte der Tiefe, und was die Kälte hält, wird langsam." },
  "adamantite_ore": { en: "Green-black ore so dense the pick rings off it. It gives up adamantium only to a hot furnace and plenty of coal.", de: "Grünschwarzes Erz, so dicht, dass die Hacke davon abprallt. Adamantium gibt es nur einem heißen Ofen und reichlich Kohle her." },
  "adamantium_arrow": { en: "An adamantium head on a straight shaft. Heavy, and it lands like it.", de: "Eine Adamantiumspitze auf geradem Schaft. Schwer, und so schlägt er auch ein." },
  "adamantium_arrowheads": { en: "Green-black heads so hard the file barely marks them, forty-five from one bar. They do not bend. They break what they hit.", de: "Grünschwarze Spitzen, so hart, dass die Feile kaum greift, fünfundvierzig je Barren. Sie verbiegen sich nicht. Sie brechen, was sie treffen." },
  "adamantium_axe": { en: "Green-black adamantium, stubborn to grind and slow to blunt. The head outlasts three handles.", de: "Grünschwarzes Adamantium, widerspenstig beim Schleifen und langsam im Stumpfwerden. Der Kopf überlebt drei Stiele." },
  "adamantium_battleaxe": { en: "Adamantium does not chip, however often it lands. Whatever it meets does the chipping for both.", de: "Adamantium splittert nicht, egal wie oft es anschlägt. Was es trifft, erledigt das für beide." },
  "adamantium_chainbody": { en: "Adamantium rings, green-black, each one a small stubborn fact. Together they are a hauberk nothing argues with.", de: "Adamantiumringe, grünschwarz, jeder eine kleine sture Tatsache. Zusammen sind sie ein Kettenhemd, mit dem nichts streitet." },
  "adamantium_dagger": { en: "Adamantium ground to a needle. It takes a week to put the point on and years to take it off.", de: "Adamantium, zur Nadel geschliffen. Die Spitze braucht eine Woche, bis sie sitzt, und Jahre, bis sie geht." },
  "adamantium_focus": { en: "Heavy adamantium over an aether core. It drags on the arm and steadies the mind in equal measure.", de: "Schweres Adamantium über einem Aetherkern. Es zieht am Arm und beruhigt den Kopf im gleichen Maß." },
  "adamantium_fullhelm": { en: "Adamantium over the whole head, green-black and heavy enough that the neck notices. The neck gets used to it. The blows never get through.", de: "Adamantium um den ganzen Kopf, grünschwarz und so schwer, dass der Nacken es merkt. Der Nacken gewöhnt sich. Die Schläge kommen nie durch." },
  "adamantium_gauntlets": { en: "Adamantium over the knuckles, green-black and heavy. The hand gets tired. Whatever the hand hits gets tired faster.", de: "Adamantium über den Knöcheln, grünschwarz und schwer. Die Hand wird müde. Was die Hand trifft, wird schneller müde." },
  "adamantium_greataxe": { en: "Adamantium, green-black and dense. The swing takes a while to arrive. When it does, it has arrived.", de: "Adamantium, grünschwarz und dicht. Der Schwung braucht eine Weile, bis er ankommt. Dann ist er angekommen." },
  "adamantium_greatsword": { en: "Adamantium, green-black down the whole blade. The balance is forward, and so is everything else about it.", de: "Adamantium, grünschwarz über die ganze Klinge. Die Balance liegt vorn, und alles andere an ihm auch." },
  "adamantium_kiteshield": { en: "Adamantium, green-black, in a teardrop. It does not dent and it does not ring. It only stops things.", de: "Adamantium, grünschwarz, in Tropfenform. Es beult nicht und klingt nicht. Es hält nur auf." },
  "adamantium_longbow": { en: "Ironbark rings when the string comes home. The stave is nearly metal, and it throws an arrow like it has a grudge.", de: "Eisenrinde klingt, wenn die Sehne anschlägt. Der Stab ist beinahe Metall, und er wirft einen Pfeil, als hätte er etwas abzurechnen." },
  "adamantium_mace": { en: "Adamantium flanges that do not deform. Everything they hit does.", de: "Adamantiumflansche, die sich nicht verformen. Alles, was sie treffen, schon." },
  "adamantium_maul": { en: "Adamantium, green-black, denser than lead. The haft is the only part of it that ever breaks.", de: "Adamantium, grünschwarz, dichter als Blei. Der Stiel ist das Einzige daran, was je bricht." },
  "adamantium_medhelm": { en: "An adamantium cap, open-faced. The weight of a full helm's worth of metal, pressed into less of it.", de: "Eine Adamantiumkappe, offen. Das Gewicht eines Vollhelms, in weniger Metall gepresst." },
  "adamantium_platebody": { en: "Adamantium beaten into a breastplate, five bars and a smith who hated it by the end. It does not dent. It has never dented.", de: "Adamantium zu einem Brustpanzer geschlagen, fünf Barren und ein Schmied, der ihn am Ende hasste. Er beult nicht. Er hat nie gebeult." },
  "adamantium_platelegs": { en: "Adamantium greaves, green-black and heavy. They do not bend at the knee so much as permit it.", de: "Adamantium-Beinschienen, grünschwarz und schwer. Sie beugen sich am Knie nicht, sie erlauben es." },
  "adamantium_sabatons": { en: "Adamantium over the feet, green-black and heavy. Each step lands like a judgement. Nothing underfoot argues.", de: "Adamantium über den Füßen, grünschwarz und schwer. Jeder Schritt landet wie ein Urteil. Nichts darunter widerspricht." },
  "adamantium_scimitar": { en: "Adamantium holds the curve without flexing. Every cut lands where the last one pointed.", de: "Adamantium hält die Kurve, ohne zu federn. Jeder Schnitt landet dort, wohin der letzte gezeigt hat." },
  "adamantium_shortbow": { en: "Ironbark cut short, which took a saw and most of a day. It rings on every shot.", de: "Eisenrinde, kurz geschnitten, was eine Säge und fast einen Tag brauchte. Sie klingt bei jedem Schuss." },
  "adamantium_spear": { en: "An adamantium head, heavy for a spear, which only means the thrust needs less help.", de: "Ein Adamantiumkopf, schwer für einen Speer, was nur heißt, dass der Stoß weniger Hilfe braucht." },
  "adamantium_staff": { en: "Green-black adamantium around a storm shard. Too heavy to swing quickly, so the lightning does the hurrying.", de: "Grünschwarzes Adamantium um einen Sturmsplitter. Zu schwer, um ihn schnell zu führen, also übernimmt der Blitz die Eile." },
  "adamantium_sword": { en: "Adamantium, green-black, balanced a finger forward of the guard. It does not flex, and it forgives nothing.", de: "Adamantium, grünschwarz, einen Finger vor der Parierstange ausbalanciert. Es federt nicht, und es verzeiht nichts." },
  "adamantium_towershield": { en: "A door of adamantium with a grip bolted to the back. Slow to raise, and once raised, it stays raised.", de: "Eine Tür aus Adamantium mit einem Griff auf der Rückseite. Langsam zu heben, und einmal oben, bleibt sie oben." },
  "adamantium_wand": { en: "Fifteen force shards packed into adamantium. Heavier than a wand should be, and each strike leans on the one before.", de: "Fünfzehn Kraftsplitter in Adamantium gepackt. Schwerer, als ein Zauberstab sein sollte, und jeder Schlag stützt sich auf den vorigen." },
  "aether_orb": { en: "Aether sealed in a mithril shell before it could thin out. It hums against the palm and makes the body a little harder to tire.", de: "Aether, in einer Mithrilschale versiegelt, bevor er sich verflüchtigen konnte. Summt gegen die Handfläche und macht den Körper etwas zäher." },
  "aether_rune": { en: "Aether essence bound before it thins out, two shards to the measure. The Idol Hall's priests carry them, and most of the aether craft is built on them.", de: "Aetheressenz, gebunden, bevor sie verfliegt, zwei Splitter je Maß. Die Priester der Götzenhalle tragen sie, und das Aether-Handwerk baut darauf." },
  "aetherband_ring": { en: "A band of aether from the Void Roc's wing, where it was half here and half not. Each kill leaves a little ward behind.", de: "Ein Reif aus Aether vom Flügel des Leerenrocs, wo er halb hier war und halb nicht. Jeder Kill lässt etwas Ward zurück." },
  "aetherite_ore": { en: "Ore shot through with a shimmer that moves when nobody is looking. Smelted with enough coal, it becomes aetherium.", de: "Erz, durchzogen von einem Schimmer, der sich bewegt, wenn keiner hinsieht. Mit genug Kohle geschmolzen wird Aetherium daraus." },
  "aetherium_arrow": { en: "An aetherium-headed arrow that hums faintly in the quiver. Fletchers near the top of the craft barb, poison or fire it.", de: "Ein Pfeil mit Aetheriumspitze, der im Köcher leise summt. Bogner nahe der Spitze des Handwerks versehen ihn mit Widerhaken, Gift oder Feuer." },
  "aetherium_arrowheads": { en: "Aetherium heads, forty-five from a bar that was never quite still. They hum on the string and go quiet when they land.", de: "Aetheriumspitzen, fünfundvierzig aus einem Barren, der nie ganz still war. Sie summen auf der Sehne und werden still, wenn sie treffen." },
  "aetherium_axe": { en: "Aetherium hums faintly on the backswing. The edge is thin as the veil it came from, and it parts things the same way.", de: "Aetherium summt leise beim Ausholen. Die Schneide ist dünn wie der Schleier, aus dem es stammt, und sie teilt die Dinge genauso." },
  "aetherium_bar": { en: "Aetherite smelted over five coal into a bar that is never quite still in the hand. The wyverns of the Highlands carry a little of it.", de: "Aetherit, über fünf Kohle zu einem Barren geschmolzen, der in der Hand nie ganz still ist. Die Wyvern des Hochlands tragen ein wenig davon." },
  "aetherium_battleaxe": { en: "Aetherium rings on every swing, a thin note that stops when it lands. Listen for the silence.", de: "Aetherium klingt bei jedem Schwung, ein dünner Ton, der aufhört, wenn es trifft. Achte auf die Stille." },
  "aetherium_chainbody": { en: "Aetherium rings, each one a thin note. Move, and the hauberk hums. Get hit, and it hums louder.", de: "Aetheriumringe, jeder ein dünner Ton. Beweg dich, und das Hemd summt. Werde getroffen, und es summt lauter." },
  "aetherium_dagger": { en: "Aetherium ground thin enough to see light through. It parts flesh the way the veil parts, without a sound.", de: "Aetherium, so dünn geschliffen, dass Licht hindurchfällt. Es teilt Fleisch, wie der Schleier sich teilt, ohne Laut." },
  "aetherium_focus": { en: "Aetherium around three measures of void. The metal rings softly at every spell, like a bell struck from the inside.", de: "Aetherium um drei Maß Leere. Das Metall klingt bei jedem Zauber leise nach, wie eine Glocke, von innen angeschlagen." },
  "aetherium_fullhelm": { en: "Aetherium closed over the head, humming softly at the temples. Behind the visor, the world sounds farther away than it is.", de: "Aetherium um den Kopf geschlossen, leise summend an den Schläfen. Hinter dem Visier klingt die Welt weiter weg, als sie ist." },
  "aetherium_gauntlets": { en: "Aetherium over the hands, humming at the fingertips. A fist in these rings when it lands.", de: "Aetherium über den Händen, summend in den Fingerspitzen. Eine Faust darin klingt, wenn sie trifft." },
  "aetherium_greataxe": { en: "Aetherium at this width hums like a struck bell. The note hangs in the air after the enemy does not.", de: "Aetherium in dieser Breite summt wie eine angeschlagene Glocke. Der Ton hängt noch in der Luft, wenn der Gegner es nicht mehr tut." },
  "aetherium_greatsword": { en: "Aetherium, the whole blade humming at a pitch just below hearing. The enemy hears it. Briefly.", de: "Aetherium, die ganze Klinge summend, knapp unter dem Hörbaren. Der Gegner hört es. Kurz." },
  "aetherium_kiteshield": { en: "Aetherium in a teardrop that hums when struck, a low note the arm feels before the blow does.", de: "Aetherium in Tropfenform, das beim Treffer summt, ein tiefer Ton, den der Arm spürt, bevor es der Schlag tut." },
  "aetherium_longbow": { en: "Bonewood, white and dense, from trees that grew over something that should have stayed buried. It does not creak. It clicks.", de: "Knochenholz, weiß und dicht, von Bäumen, die über etwas wuchsen, das begraben bleiben sollte. Es knarrt nicht. Es klickt." },
  "aetherium_mace": { en: "Aetherium flanges, thin and humming. They do not crush plate so much as persuade it to open.", de: "Aetheriumflansche, dünn und summend. Sie zertrümmern Platte nicht, sie überreden sie, sich zu öffnen." },
  "aetherium_maul": { en: "An aetherium head that hums as it comes down. The note is low. The result is final.", de: "Ein Aetheriumkopf, der summt, während er fällt. Der Ton ist tief. Das Ergebnis endgültig." },
  "aetherium_medhelm": { en: "An aetherium cap, open-faced, thin as a veil and harder than the wall of the Hall. It hums when struck.", de: "Eine Aetheriumkappe, offen, dünn wie ein Schleier und härter als die Mauer der Halle. Summt beim Treffer." },
  "aetherium_platebody": { en: "An aetherium breastplate, thin as a veil over the chest and harder than the wall of the Hall. It hums when struck. It is struck rarely.", de: "Ein Aetherium-Brustpanzer, dünn wie ein Schleier über der Brust und härter als die Mauer der Halle. Summt beim Treffer. Getroffen wird er selten." },
  "aetherium_platelegs": { en: "Aetherium greaves that hum when you walk, a low note at every step. The step is lighter than it should be.", de: "Aetherium-Beinschienen, die beim Gehen summen, ein tiefer Ton bei jedem Schritt. Der Schritt ist leichter, als er sein dürfte." },
  "aetherium_sabatons": { en: "Aetherium over the boots, humming at every step. The hum is low. The step is lighter than it has any right to be.", de: "Aetherium über den Stiefeln, summend bei jedem Schritt. Das Summen ist tief. Der Schritt leichter, als er sein dürfte." },
  "aetherium_scimitar": { en: "Aetherium in a long curve that hums as it turns. The hum rises with every cut. So does the cut.", de: "Aetherium in einer langen Kurve, die beim Drehen summt. Das Summen steigt mit jedem Schnitt. Der Schnitt auch." },
  "aetherium_shortbow": { en: "Bonewood bent short, white and dense. It clicks on the release, and the clicks come closer together.", de: "Knochenholz, kurz gebogen, weiß und dicht. Es klickt beim Lösen, und die Klicks rücken enger zusammen." },
  "aetherium_spear": { en: "Aetherium at the end of a pole, humming at every thrust. The point goes where the hum goes.", de: "Aetherium am Ende einer Stange, summend bei jedem Stoß. Die Spitze geht, wohin das Summen geht." },
  "aetherium_staff": { en: "Aetherium so thin it rings when the wind turns. It carries the light of the thinning veil, and the light carries its bearer.", de: "Aetherium, so dünn, dass es klingt, wenn der Wind dreht. Es trägt das Licht des dünnen Schleiers, und das Licht trägt seinen Träger." },
  "aetherium_sword": { en: "Aetherium, humming so low it is felt in the teeth. A straight blade from the thin place between the world and nothing.", de: "Aetherium, so tief summend, dass man es in den Zähnen spürt. Eine gerade Klinge aus der dünnen Stelle zwischen Welt und Nichts." },
  "aetherium_towershield": { en: "A tower of aetherium, thin as a veil and harder than the wall it replaces. The enemy hears it before they see it.", de: "Ein Turm aus Aetherium, dünn wie ein Schleier und härter als die Mauer, die er ersetzt. Der Gegner hört ihn, bevor er ihn sieht." },
  "aetherium_wand": { en: "Thirty force shards fused into aetherium. There is no element in it, only pressure, and the pressure builds with every hit.", de: "Dreißig Kraftsplitter, in Aetherium verschmolzen. Kein Element darin, nur Druck, und der Druck wächst mit jedem Treffer." },
  "aetherscale_cuirass": { en: "Scales of the Void Roc, fused into a breastplate. Half of it is not quite here. Whatever hits the other half is hit back.", de: "Schuppen des Leerenrocs, zu einem Brustpanzer verschmolzen. Die Hälfte davon ist nicht ganz hier. Was die andere trifft, wird zurückgetroffen." },
  "aetherweave_leggings": { en: "Aetherweave from the Idol Hall's skarns, cloth so dense it counts as plate. The wounds under it close on their own, which the skarns never needed.", de: "Aethergewebe von den Skarnen der Götzenhalle, Stoff so dicht, dass er als Platte gilt. Die Wunden darunter schließen sich von selbst, was die Skarne nie brauchten." },
  "alpha_fang": { en: "The fang of the pack leader, broken off at the end of the Wildwood Hunt. Strung in iron, it makes an amulet the wolves recognise.", de: "Der Reißzahn des Leitwolfs, am Ende der Wildwald-Jagd abgebrochen. In Eisen gefädelt wird daraus ein Amulett, das die Wölfe wiedererkennen." },
  "alpha_fang_amulet": { en: "The Alpha Fang in iron, the old hunter's proof from the Wildwood. Whoever wears it has stood where the pack leader stood.", de: "Der Leitwolf-Reißzahn in Eisen, die alte Jägerprobe aus dem Wildwald. Wer ihn trägt, hat gestanden, wo der Leitwolf stand." },
  "alphas_heart_ring": { en: "A ring carved from the Old One's heart bone, if a bear has such a thing. Whatever hunts beside you hunts harder for it.", de: "Ein Ring, aus dem Herzknochen des Alten vom Wildwald geschnitzt, falls ein Bär so etwas hat. Was neben dir jagt, jagt dadurch härter." },
  "ambergrain": { en: "Grain the colour of amber, heavy in the sack. Risotto, the banquets and the great feasts are all built on it.", de: "Korn in der Farbe von Bernstein, schwer im Sack. Risotto, die Bankette und die großen Festmähler bauen darauf." },
  "ambergrain_feast": { en: "Soulfish and wyvern on a bed of ambergrain, finished with godsbreath. Cooked for casters: mind, wisdom and a ward that holds.", de: "Seelenfisch und Wyvern auf Bernsteingetreide, mit Götteratem vollendet. Gekocht für Zauberer: Verstand, Weisheit und ein Ward, der hält." },
  "ambergrain_seed": { en: "Golden grain seed found among the god fungus. Slow in the plot, but the crop is the best grain the Reach has.", de: "Goldenes Getreidesaatgut, zwischen den Götterpilzen gefunden. Langsam im Beet, aber die Ernte ist das beste Korn, das das Reach hat." },
  "antivenom_tonic": { en: "Deathmoss ground with ashen dust, no water, taken dry. The Deepwood's answer to its own bites.", de: "Totenmoos, mit Aschestaub zerrieben, ohne Wasser, trocken genommen. Die Antwort des Tiefwalds auf seine eigenen Bisse." },
  "antler_warbow": { en: "Two tines of a wild stag's antler joined at the grip and strung tight. Built by a hunter who did not come back for it.", de: "Zwei Geweihsprossen eines Wildhirschs am Griff verbunden und straff bespannt. Gebaut von einem Jäger, der nicht zurückkam, ihn zu holen." },
  "arcane_cape": { en: "Nettlecloth soaked in dim essence until the weave holds a little of it. The first cape a tailor makes that does anything.", de: "Nesselstoff, in Trübessenz getränkt, bis das Gewebe etwas davon behält. Der erste Umhang eines Schneiders, der etwas tut." },
  "ash_fishing_rod": { en: "Birchwood and a sinew line, carved on the first bench any crafter owns. Lighter than the crude rod, and quicker to the bite.", de: "Birkenholz und eine Sehnenschnur, geschnitzt auf der ersten Werkbank. Leichter als die grobe Angel und schneller am Biss." },
  "ash_tyrant_crown": { en: "The Ash Tyrant's crown, a ring of jackal skulls and charred iron. It ruled the carrion of the fields and still takes its share of every kill.", de: "Die Krone des Aschtyrannen, Schakalschädel und verkohltes Eisen. Sie herrschte über das Aas der Felder und nimmt noch ihren Teil von jedem Kill." },
  "ashbark_log": { en: "Wood from the trees that grew back after the burning, grey-barked and straight. Fletchers cut their first real bows from it.", de: "Holz der Bäume, die nach dem Brand nachwuchsen, graurindig und gerade. Bogner schnitzen ihre ersten ernsthaften Bögen daraus." },
  "ashen_dust": { en: "Fine grey dust that settles on everything in the Ashfields and on a few things that walk out of them. Herbalists need a pinch for the first draughts.", de: "Feiner grauer Staub, der in den Aschfeldern auf allem liegt, auch auf dem, was von dort kommt. Kräuterkundige brauchen eine Prise für die ersten Sude." },
  "ashen_gauntlets": { en: "Gauntlets scoured grey by the Ashfields and dug up by the ash rats. Whoever wore them did not give up early. Neither do they.", de: "Stulpen, von den Aschfeldern grau gescheuert und von Aschratten ausgegraben. Wer sie trug, gab nicht früh auf. Sie auch nicht." },
  "ashfall_recurve": { en: "A recurve from the Ash Tyrant's hoard, the limbs charred to a hard shine. The arrows catch fire on the way out.", de: "Ein Recurve aus dem Hort des Aschtyrannen, die Wurfarme zu hartem Glanz verkohlt. Die Pfeile fangen im Abschuss Feuer." },
  "ashfen_buckler": { en: "Ashfen wood, streaked with soot that never washed out, cut round and strapped. Light, quick, and it smells of the fen's burned edge.", de: "Aschenfilz-Holz, von Ruß durchzogen, der nie auswusch, rund geschnitten und geriemt. Leicht, schnell, und riecht nach dem verbrannten Moorrand." },
  "ashplate_cuirass": { en: "Plate from the Ash Tyrant's hoard, scoured grey and hammered back into shape by nobody. It gives back what it takes.", de: "Platte aus dem Hort des Aschtyrannen, grau gescheuert und von niemandem wieder in Form gebracht. Sie gibt zurück, was sie einsteckt." },
  "ashroot": { en: "A grey, knobbly root that tastes of smoke no matter how it is cooked. Two of them in water make the broth that keeps new settlers alive.", de: "Eine graue, knorrige Wurzel, die nach Rauch schmeckt, egal wie man sie kocht. Zwei davon in Wasser geben die Brühe, die Siedler am Leben hält." },
  "ashroot_broth": { en: "Two ashroots boiled in a vial of water. Thin, grey and warm, and the first thing most settlers learn to cook.", de: "Zwei Aschwurzeln, in einem Fläschchen Wasser gekocht. Dünn, grau und warm, und das Erste, was die meisten Siedler kochen lernen." },
  "ashroot_seed": { en: "Seed for the ashroot, the first thing New Haven's plots are sown with. Ten minutes in the ground and there is broth for the evening.", de: "Saat für die Aschwurz, das Erste, womit die Beete von New Haven bestellt werden. Zehn Minuten in der Erde, und es gibt Brühe für den Abend." },
  "ashtongue_fetish": { en: "Vhazrak the Ashtongue's own fetish, goblin-knotted from hair and tooth. The curses it keeps linger longer than they should.", de: "Vhazraks eigener Fetisch, Goblin-Knotenwerk aus Haar und Zahn. Die Flüche, die er hält, halten länger, als sie sollten." },
  "ashwood_longbow": { en: "Scorched ashwood the dust vultures drag back to their roosts. Grey and stubborn like the field it came from, and the first shot lands.", de: "Versengtes Aschholz, das die Staubgeier in ihre Horste schleppen. Grau und stur wie das Feld, von dem es stammt, und der erste Schuss sitzt." },
  "bark_bulwark": { en: "A slab of moss golem's bark, still faintly alive. Whatever bleeds against it does not seem to stop bleeding.", de: "Eine Platte Moosgolem-Rinde, noch schwach lebendig. Was daran blutet, hört offenbar nicht auf zu bluten." },
  "barnacle_gauntlets": { en: "Gauntlets from a reef drowned, the iron crusted with barnacles that never let go. They grip hardest when the hand is nearly spent.", de: "Stulpen eines Riff-Ertrunkenen, das Eisen mit Seepocken verkrustet, die nie loslassen. Sie greifen am härtesten, wenn die Hand fast am Ende ist." },
  "basilisk_scale_shield": { en: "Basilisk scales from the Mirror Halls, laid like roof tiles on a frame. The scales have always kept the stare out.", de: "Basiliskenschuppen aus den Spiegelhallen, wie Dachziegel auf einen Rahmen gelegt. Die Schuppen haben den Blick schon immer abgehalten." },
  "bear_haunch": { en: "Braised until the elder bear's sinew finally gives. It carries a hunter through a long day, and the Old Hunt pays in it.", de: "Geschmort, bis die Sehnen des Altbären endlich nachgeben. Trägt einen Jäger durch einen langen Tag, und die alte Jagd zahlt damit." },
  "bearhide_cuirass": { en: "The hide of the Old One of the Wildwood, cured with the fur on. Heavy, warm, and the first cut you make wearing it goes deepest.", de: "Die Haut des Alten vom Wildwald, mit dem Fell gegerbt. Schwer, warm, und der erste Schnitt, den du darin setzt, geht am tiefsten." },
  "beastcaller_totem": { en: "A gray wolf's skull on a stick, hung with teeth that click in the wind. Whatever hunts beside you hears it and hunts harder.", de: "Ein Grauwolfschädel an einem Stock, mit Zähnen behängt, die im Wind klicken. Was neben dir jagt, hört es und jagt härter." },
  "birchwood_log": { en: "Light, pale wood that splits straight. The first bows are carved from it, and the first rod worth the name.", de: "Leichtes, helles Holz, das gerade spaltet. Die ersten Bögen werden daraus geschnitzt, und die erste Angel, die den Namen verdient." },
  "birds_nest": { en: "It came down with the tree. Twigs, moss, a feather or two, and sometimes a shell. Nothing to craft from it, but someone will buy it.", de: "Kam mit dem Baum herunter. Zweige, Moos, ein, zwei Federn und manchmal eine Schale. Nichts daraus zu machen, aber irgendwer kauft es." },
  "blackantler_warbow": { en: "Cut from the antlers of Blackantler the Wrathful, who never let a hunter rest. Neither does the bow. Each kill brings the next sooner.", de: "Aus dem Geweih von Schwarzgeweih dem Zornigen, der keinem Jäger Ruhe ließ. Der Bogen auch nicht. Jeder Kill bringt den nächsten schneller." },
  "blackhoof_charm": { en: "A ring of Blackhoof the Baleful's horn on a cord, the bull that charged everything that moved. Strike its wearer, and the charge comes back.", de: "Ein Ring aus dem Horn von Schwarzhuf dem Unheilvollen, der alles angriff, was sich rührte. Wer seinen Träger schlägt, bekommt den Angriff zurück." },
  "blacksteel_arrow": { en: "Black-headed arrows that vanish against a night sky before they land. Favoured by archers who would rather not be seen loosing.", de: "Schwarze Spitzen, die vor dem Nachthimmel verschwinden, bevor sie treffen. Beliebt bei Schützen, die beim Schuss ungesehen bleiben wollen." },
  "blacksteel_arrowheads": { en: "Blacksteel heads, dark and mean, forty-five from a bar. The point stays sharp for longer than the shaft stays whole.", de: "Schwarzstahlspitzen, dunkel und böse, fünfundvierzig aus einem Barren. Die Spitze bleibt länger scharf, als der Schaft ganz bleibt." },
  "blacksteel_axe": { en: "Oil-quenched blacksteel, dull as soot. It never shines, so nothing sees it coming.", de: "Ölgehärteter Schwarzstahl, matt wie Ruß. Er glänzt nie, darum sieht ihn nichts kommen." },
  "blacksteel_bar": { en: "Steel folded again over twice the coal, until the surface goes black and the edge goes mean. The Reach's working metal for a long stretch.", de: "Stahl, über doppelter Kohle noch einmal gefaltet, bis die Oberfläche schwarz und die Schneide böse wird. Das Arbeitsmetall des Reachs für lange Zeit." },
  "blacksteel_battleaxe": { en: "Blacksteel takes a crueller edge than steel and hides it in the dark. The haft is wrapped so it does not slip when wet.", de: "Schwarzstahl nimmt eine grausamere Schneide als Stahl und versteckt sie im Dunkeln. Der Stiel ist umwickelt, damit er nass nicht rutscht." },
  "blacksteel_chainbody": { en: "Blacksteel rings, matte and close. It makes no sound and shows no light. You are a shape in the dark, and the shape is hard.", de: "Schwarzstahlringe, matt und eng. Es macht keinen Laut und zeigt kein Licht. Du bist eine Gestalt im Dunkeln, und die Gestalt ist hart." },
  "blacksteel_dagger": { en: "Blacksteel, matte and narrow, made to be drawn where there is no light to draw it in.", de: "Schwarzstahl, matt und schmal, gemacht, um dort gezogen zu werden, wo kein Licht ist." },
  "blacksteel_focus": { en: "Blacksteel darkens further in the essence bath until it looks like a hole in the hand. It is not. It only helps you think.", de: "Schwarzstahl wird im Essenzbad noch dunkler, bis er aussieht wie ein Loch in der Hand. Ist er nicht. Er hilft nur beim Denken." },
  "blacksteel_fullhelm": { en: "Blacksteel closed over the face, matte as a hole. Nothing reflects in the visor, not even the enemy.", de: "Schwarzstahl, über dem Gesicht geschlossen, matt wie ein Loch. Im Visier spiegelt sich nichts, nicht einmal der Gegner." },
  "blacksteel_gauntlets": { en: "Blacksteel over the hands, matte to the fingertips. In the dark the hands are gone, and whatever they hold with them.", de: "Schwarzstahl über den Händen, matt bis in die Fingerspitzen. Im Dunkeln sind die Hände weg, und was sie halten, mit ihnen." },
  "blacksteel_greataxe": { en: "Blacksteel, broad and matte. Nothing reflects off it, not light, not a parry.", de: "Schwarzstahl, breit und matt. Nichts prallt daran ab, kein Licht und keine Parade." },
  "blacksteel_greatsword": { en: "Blacksteel, long and matte, the fuller cut deep to keep it quick. Quick for its length, which is saying something.", de: "Schwarzstahl, lang und matt, die Hohlkehle tief gezogen, damit es schnell bleibt. Schnell für seine Länge, und die ist beachtlich." },
  "blacksteel_kiteshield": { en: "Blacksteel in a teardrop, matte so it throws no light. The enemy aims at where the shield is not. It is there.", de: "Schwarzstahl in Tropfenform, matt, damit er kein Licht wirft. Der Gegner zielt dorthin, wo der Schild nicht ist. Er ist da." },
  "blacksteel_longbow": { en: "Blackwood, heavier than oak, from the Reach's older stands. A slow bow to bend and a hard one to stop.", de: "Schwarzholz, schwerer als Eiche, aus den älteren Wäldern des Reachs. Ein Bogen, der sich langsam biegt und schwer aufhalten lässt." },
  "blacksteel_mace": { en: "Blacksteel, heavy for its size, matte as a shadow. Plate does not stop it. Plate barely slows it.", de: "Schwarzstahl, schwer für seine Größe, matt wie ein Schatten. Platte hält ihn nicht auf. Platte bremst ihn kaum." },
  "blacksteel_maul": { en: "Blacksteel, matte, the head squared off like an anvil. Plate folds under it the way tin folds under a boot.", de: "Schwarzstahl, matt, der Kopf kantig wie ein Amboss. Platte faltet sich darunter wie Blech unter einem Stiefel." },
  "blacksteel_medhelm": { en: "A blacksteel cap, open-faced and dark. It catches no torchlight, which is the whole idea.", de: "Eine Schwarzstahlkappe, offen und dunkel. Sie fängt kein Fackellicht, und das ist der ganze Sinn." },
  "blacksteel_platebody": { en: "A blacksteel breastplate, dark as the inside of a forge. It takes a blow and gives nothing back, not even a reflection.", de: "Ein Schwarzstahl-Brustpanzer, dunkel wie das Innere einer Esse. Er nimmt einen Schlag und gibt nichts zurück, nicht einmal ein Spiegelbild." },
  "blacksteel_platelegs": { en: "Blacksteel greaves, matte to the buckles. In the dark your legs are not there. The blows aimed at them agree.", de: "Schwarzstahl-Beinschienen, matt bis zu den Schnallen. Im Dunkeln sind deine Beine nicht da. Die Schläge, die auf sie zielen, sehen das auch so." },
  "blacksteel_sabatons": { en: "Blacksteel over the boots, matte to the sole. Your feet make no light, and the step they take is harder than it looks.", de: "Schwarzstahl über den Stiefeln, matt bis zur Sohle. Deine Füße werfen kein Licht, und der Schritt ist härter, als er aussieht." },
  "blacksteel_scimitar": { en: "Blacksteel, curved and matte, with no glint on the edge to warn of the next cut. There is always a next cut.", de: "Schwarzstahl, gebogen und matt, kein Glanz an der Schneide, der den nächsten Schnitt verrät. Es gibt immer einen nächsten." },
  "blacksteel_shortbow": { en: "Blackwood bent short, heavier than it looks and faster than it should be.", de: "Schwarzholz, kurz gebogen, schwerer, als es aussieht, und schneller, als es sein dürfte." },
  "blacksteel_spear": { en: "Blacksteel on a dark shaft. At the reach of a spear, the enemy sees the point last of all.", de: "Schwarzstahl an dunklem Schaft. Auf Speerlänge sieht der Gegner die Spitze als Letztes." },
  "blacksteel_staff": { en: "Blacksteel quenched around a void shard. It does not burn or freeze. It only takes away, and finishes what is already failing.", de: "Schwarzstahl, um einen Leerensplitter gehärtet. Er brennt nicht und friert nicht. Er nimmt nur weg, und beendet, was schon wankt." },
  "blacksteel_sword": { en: "Blacksteel, matte from guard to point. It was never meant to be seen drawn, only to have been drawn.", de: "Schwarzstahl, matt von der Parierstange bis zur Spitze. Es sollte nie gezogen gesehen werden, nur gezogen gewesen sein." },
  "blacksteel_towershield": { en: "A tower shield of blacksteel, dark enough to vanish against a wall. Behind it, so do you.", de: "Ein Turmschild aus Schwarzstahl, dunkel genug, um vor einer Mauer zu verschwinden. Dahinter verschwindest du auch." },
  "blacksteel_wand": { en: "Blacksteel over a core of pale fungus and mire essence. It smells faintly of the ditches it came from.", de: "Schwarzstahl über einem Kern aus Bleich-Pilz und Sumpfessenz. Riecht leise nach den Gräben, aus denen er stammt." },
  "blightwood_log": { en: "Timber from the sick trees of the Blackthorn, mottled and surprisingly strong. The Forest Warden drops a few trunks when he falls.", de: "Holz der kranken Bäume des Schwarzdorns, fleckig und überraschend fest. Der Waldvogt lässt ein paar Stämme fallen, wenn er fällt." },
  "bloodbeet": { en: "A red root that stains the hands before it stains the pot. Crushed with witchgrass it makes the salve of mending.", de: "Eine rote Rübe, die die Hände färbt, bevor sie den Topf färbt. Mit Hexengras zerdrückt gibt sie die Salbe der Heilung." },
  "bloodgrain": { en: "Red grain that stains the water it is boiled in. Stewed with pike and beef, or whisked into the spellwarden bisque.", de: "Rotes Korn, das das Kochwasser färbt. Mit Hecht und Rind geschmort oder in die Zauberwächter-Bisque gerührt." },
  "bloodgrain_seed": { en: "Red-husked grain seed, found among the bloodthistle. It grows a cereal that cooks like oats and looks like a wound.", de: "Rotschaliges Getreidesaatgut, zwischen der Blutdistel gefunden. Daraus wächst ein Korn, das wie Hafer kocht und wie eine Wunde aussieht." },
  "bloodgrain_stew": { en: "Pike and beef stewed with bloodgrain and a thistle for bite, four bowls to the pot. Hardens the arm and the skin for a short while.", de: "Hecht und Rind, mit Blutgetreide und einer Distel geschmort, vier Schalen aus dem Topf. Härtet Arm und Haut für eine kurze Weile." },
  "bloodiron_arrow": { en: "A bloodiron arrow, plain. Fletchers barb it with a fang, dip it in gloomspore or pack it with emberleaf, and it stops being plain.", de: "Ein schlichter Bluteisen-Pfeil. Mit einem Reißzahn, in Düstersporen getaucht oder mit Glutblatt gestopft ist er nicht mehr schlicht." },
  "bloodiron_arrowheads": { en: "Red-cast heads forged from bloodiron, forty-five to the bar. The first heads that take a barb, a poison or a fire.", de: "Rotstichige Spitzen aus Bluteisen, fünfundvierzig je Barren. Die ersten, die einen Widerhaken, ein Gift oder ein Feuer annehmen." },
  "bloodiron_axe": { en: "Bloodiron keeps a rust-red cast no polish removes. The axe looks used before its first swing.", de: "Bluteisen behält einen rostroten Schimmer, den kein Polieren entfernt. Die Axt sieht gebraucht aus, bevor sie je geschlagen hat." },
  "bloodiron_battleaxe": { en: "Bloodiron, red before it has drawn any. The old smiths shunned the ore. Emberhold cannot afford to.", de: "Bluteisen, rot, bevor es je welches gezogen hat. Die alten Schmiede mieden das Erz. Die Glutfeste kann sich das nicht leisten." },
  "bloodiron_chainbody": { en: "Bloodiron rings, rust-red from the first day. It looks like it has been through a battle already. Soon it will have.", de: "Bluteisenringe, rostrot vom ersten Tag an. Es sieht aus, als wäre es schon durch eine Schlacht gegangen. Bald stimmt das." },
  "bloodiron_dagger": { en: "Bloodiron, rust-red along the fuller. It was red before, it will be redder after.", de: "Bluteisen, rostrot entlang der Hohlkehle. Es war vorher rot, es wird nachher röter sein." },
  "bloodiron_focus": { en: "Bloodiron keeps its rust-red cast even under the aether. Old smiths say the metal remembers blood. That is why it steadies the hand.", de: "Bluteisen behält seinen Rostschimmer auch unter dem Aether. Alte Schmiede sagen, das Metall erinnere sich an Blut. Darum hält es die Hand ruhig." },
  "bloodiron_fullhelm": { en: "Bloodiron closed over the face, rust-red where the breath comes out. It looks like a wound before it has taken one.", de: "Bluteisen, über dem Gesicht geschlossen, rostrot, wo der Atem herauskommt. Sieht aus wie eine Wunde, bevor es eine abbekommen hat." },
  "bloodiron_gauntlets": { en: "Bloodiron over the hands, red before they have touched anything. They will touch plenty.", de: "Bluteisen über den Händen, rot, bevor sie etwas berührt haben. Berühren werden sie genug." },
  "bloodiron_greataxe": { en: "Bloodiron, two-handed, rust-red to the haft. Veins like this were better left closed. The axe disagrees.", de: "Bluteisen, zweihändig, rostrot bis zum Stiel. Solche Adern hätte man besser geschlossen gelassen. Die Axt sieht das anders." },
  "bloodiron_greatsword": { en: "Bloodiron, rust-red, with a crossguard wide enough to catch a battleaxe. It was made for a war the Reach lost.", de: "Bluteisen, rostrot, mit einer Parierstange, breit genug, eine Kampfaxt zu fangen. Gemacht für einen Krieg, den das Reach verlor." },
  "bloodiron_kiteshield": { en: "Bloodiron in a teardrop, rust-red to the rim. It has already been through a war. It is not particular about the next one.", de: "Bluteisen in Tropfenform, rostrot bis zum Rand. Es war schon in einem Krieg. Beim nächsten ist es nicht wählerisch." },
  "bloodiron_longbow": { en: "Shadowpine, pale and cold even fresh-cut, from stands the sun barely reaches. A quiet bow for a quiet wood.", de: "Schattenkiefer, blass und kalt selbst frisch geschlagen, aus Beständen, die die Sonne kaum erreicht. Ein leiser Bogen für einen leisen Wald." },
  "bloodiron_mace": { en: "Bloodiron, rust-red into the flanges. It hits armor as if it held a grudge.", de: "Bluteisen, rostrot bis in die Flansche. Es trifft Rüstung, als hätte es etwas gegen sie." },
  "bloodiron_maul": { en: "Bloodiron, rust-red, the striking face worn smooth. It has done this before. It will do it again.", de: "Bluteisen, rostrot, die Schlagfläche glatt geschlagen. Er hat das schon getan. Er wird es wieder tun." },
  "bloodiron_medhelm": { en: "A bloodiron cap with a nasal bar, red to the rim. The old smiths would not have worn it. They are not here.", de: "Eine Bluteisenkappe mit Nasenschutz, rot bis zum Rand. Die alten Schmiede hätten sie nicht getragen. Sie sind nicht mehr da." },
  "bloodiron_ore": { en: "Iron ore with a red cast that no washing takes out. It smelts hot and hungry and asks for four coal to the bar.", de: "Eisenerz mit einem roten Stich, den kein Waschen herausbekommt. Es schmilzt heiß und hungrig und verlangt vier Kohle je Barren." },
  "bloodiron_platebody": { en: "A bloodiron breastplate, red as a wound, made from ore the old smiths refused. It stops what they could not.", de: "Ein Bluteisen-Brustpanzer, rot wie eine Wunde, aus Erz, das die alten Schmiede verweigerten. Er hält auf, was sie nicht konnten." },
  "bloodiron_platelegs": { en: "Bloodiron greaves, red to the straps. They have waded through worse than mud, or they look as if they have.", de: "Bluteisen-Beinschienen, rot bis zu den Riemen. Sie sind durch Schlimmeres gewatet als Schlamm, oder sie sehen so aus." },
  "bloodiron_sabatons": { en: "Bloodiron over the boots, red to the sole. They have walked through worse than this, or they look like it.", de: "Bluteisen über den Stiefeln, rot bis zur Sohle. Sie sind durch Schlimmeres gegangen als das hier, oder sie sehen so aus." },
  "bloodiron_scimitar": { en: "Bloodiron, red and curved. The old smiths called the ore a bad vein. The curve agrees with the ore.", de: "Bluteisen, rot und gebogen. Die alten Schmiede nannten das Erz eine schlechte Ader. Die Kurve ist derselben Meinung." },
  "bloodiron_shortbow": { en: "Shadowpine, pale and cold, bent short. Quiet shots that come faster the longer they go on.", de: "Schattenkiefer, blass und kalt, kurz gebogen. Leise Schüsse, die schneller werden, je länger sie andauern." },
  "bloodiron_spear": { en: "Bloodiron, rust-red from socket to point. It was red when it left the forge. Nobody pretends otherwise.", de: "Bluteisen, rostrot von der Tülle bis zur Spitze. Es war rot, als es die Esse verließ. Niemand tut, als wäre es anders." },
  "bloodiron_staff": { en: "Bloodiron with ember essence worked into the shoeing. The head stays warm long after the last fire has gone out.", de: "Bluteisen, Glutessenz in den Beschlag gearbeitet. Der Kopf bleibt warm, lange nachdem das letzte Feuer erloschen ist." },
  "bloodiron_sword": { en: "Bloodiron, red to the tang. The veins it came from should have stayed shut. The sword does not care.", de: "Bluteisen, rot bis zur Angel. Die Adern, aus denen es kam, hätten zubleiben sollen. Dem Schwert ist das gleich." },
  "bloodiron_towershield": { en: "A bloodiron tower, red as a door someone bled against. It was made for a shield wall. The wall is gone. The shield stayed.", de: "Ein Turm aus Bluteisen, rot wie eine Tür, an der jemand verblutete. Gemacht für einen Schildwall. Der Wall ist fort. Der Schild blieb." },
  "bloodiron_wand": { en: "Bloodiron packed with frost shards. The rust-red metal and the white rime never agree on a temperature.", de: "Bluteisen, mit Frostsplittern gefüllt. Das rostrote Metall und der weiße Reif einigen sich nie auf eine Temperatur." },
  "bloodmend_draught": { en: "Rimecap and ironvine, brewed to knit rather than flood. The wound closes over a few seconds instead of all at once.", de: "Raureifpilz und Eisenranke, gebraut, damit es knüpft statt flutet. Die Wunde schließt sich über ein paar Sekunden, nicht auf einen Schlag." },
  "bloodstone": { en: "Cut so the red veins run to the surface. Set in gravesteel or leather, it makes rings, chains and the gravecall amulet.", de: "So geschliffen, dass die roten Adern an die Oberfläche laufen. In Grabstahl oder Leder gefasst gibt er Ringe, Ketten und das Grabruf-Amulett." },
  "bloodstone_amulet": { en: "A bloodstone in gravesteel, the Grave Wardens' metal. The stone is dark red, the setting is grey, and together they do not forgive armor.", de: "Ein Blutstein in Grabstahl, dem Metall der Grabwächter. Der Stein dunkelrot, die Fassung grau, und zusammen verzeihen sie keine Rüstung." },
  "bloodstone_ring": { en: "A bloodstone in gravesteel. The Grave Wardens' metal and a stone the color of what they buried. It does not forgive armor.", de: "Ein Blutstein in Grabstahl. Das Metall der Grabwächter und ein Stein in der Farbe dessen, was sie begruben. Er verzeiht keine Rüstung." },
  "bloodthistle_seed": { en: "A prickly seed head from the bloodthistle. Sow it, and the plot gives a thistle crop without the walk to the Ashfields.", de: "Ein stacheliger Samenkopf der Blutdistel. Gesät gibt das Beet eine Distelernte ohne den Weg in die Aschfelder." },
  "boartusk_ring": { en: "A boar tusk bent into a ring in the bull's byre, by someone who meant to fight something far too big for them. They did.", de: "Ein Eberhauer, im Stall des Bullen zu einem Ring gebogen, von jemandem, der sich mit etwas viel zu Großem anlegen wollte. Das tat er." },
  "boneblade": { en: "A skeleton warrior's blade, bone and iron fused by whatever brought it back. It finishes what is already failing.", de: "Die Klinge eines Skelettkriegers, Knochen und Eisen verschmolzen durch das, was ihn zurückholte. Sie beendet, was schon fällt." },
  "bonecharm_amulet": { en: "Finger bones from the Crypt's butcher, strung on gut. Every kill knits the wearer back together a little, which is more than the butcher ever managed.", de: "Fingerknochen vom Schlächter der Krypta, auf Darm gezogen. Jeder Kill flickt den Träger ein wenig, was der Schlächter selbst nie schaffte." },
  "boneknuckle_gauntlets": { en: "A skeleton warrior's own hands, the finger bones strapped over leather. They close hardest when there is little left to close them with.", de: "Die Hände eines Skelettkriegers, die Fingerknochen über Leder geschnallt. Sie schließen sich am härtesten, wenn wenig Kraft übrig ist." },
  "bonepatch_helm": { en: "A goblin's helmet, dented and patched with bone where the iron gave out. Every kill under it closes a cut or two.", de: "Ein Goblinhelm, verbeult und mit Knochen geflickt, wo das Eisen nachgab. Jeder Kill darunter schließt die eine oder andere Wunde." },
  "bonesteel_rod": { en: "Blackwood shaft, sinew line, and a name earned in the deep cold water it was built for. It hauls faster than wood alone should.", de: "Schwarzholzschaft, Sehnenschnur und ein Name aus dem kalten Wasser, für das sie gebaut wurde. Sie zieht schneller, als Holz allein dürfte." },
  "bonewood_log": { en: "Wood white as old bone and nearly as hard. Six logs go into a single bow, and the bow outlives the archer.", de: "Holz, weiß wie alter Knochen und beinahe so hart. Sechs Stämme gehen in einen einzigen Bogen, und der Bogen überlebt den Schützen." },
  "bonewrought_spear": { en: "A skeleton spearman's spear from the Crypt, bone fused to the iron where the hand held it. The first thrust is the one it stands for.", de: "Speer eines Skelett-Speerträgers der Krypta, Knochen mit Eisen verwachsen, wo die Hand ihn hielt. Der erste Stoß ist der, für den er steht." },
  "bowstring": { en: "A line twisted from sinew, rawhide or nettle cord. Every bow, rod and wooden shield in the Reach is strung or bound with one.", de: "Gedreht aus Sehne, Rohleder oder Nesselfaser. Jeder Bogen, jede Angel und jeder Holzschild im Reach ist damit bespannt oder gebunden." },
  "briarfang_blade": { en: "Briarfang the Sleepless never stopped moving, and this is the thorn it left in everything it passed. The cut keeps bleeding.", de: "Dornfang der Schlaflose blieb nie stehen, und das ist der Dorn, den er in allem ließ, woran er vorbeikam. Der Schnitt blutet weiter." },
  "bronze_arrow": { en: "Fletched with a bronze head over a plain shaft. Heavier than copper in the quiver and heavier in the wound.", de: "Befiedert mit einer Bronzespitze auf schlichtem Schaft. Schwerer als Kupfer im Köcher und schwerer in der Wunde." },
  "bronze_arrowheads": { en: "Bronze heads cast and filed, forty-five to the bar. Harder than copper, and they keep a point through a second target.", de: "Bronzespitzen, gegossen und gefeilt, fünfundvierzig je Barren. Härter als Kupfer, und sie behalten die Spitze auch im zweiten Ziel." },
  "bronze_axe": { en: "The first alloy on a proper haft. It keeps an edge through a day of felling, which copper never managed.", de: "Die erste Legierung an einem ordentlichen Stiel. Hält die Schneide einen Fälltag lang, was Kupfer nie schaffte." },
  "bronze_battleaxe": { en: "Bronze with a crescent bit. The weight is in the head, and the head knows what it is for.", de: "Bronze mit einem Halbmondblatt. Das Gewicht sitzt im Kopf, und der Kopf weiß, wofür er da ist." },
  "bronze_chainbody": { en: "Bronze rings, each one closed with a tap of the hammer. Heavier than copper, and it does not open up when it matters.", de: "Bronzeringe, jeder mit einem Hammerschlag geschlossen. Schwerer als Kupfer, und es geht nicht auf, wenn es darauf ankommt." },
  "bronze_dagger": { en: "Bronze takes a finer point than copper and keeps it through the night. The first knife worth sharpening.", de: "Bronze nimmt eine feinere Spitze als Kupfer und hält sie die Nacht über. Das erste Messer, das sich zu schleifen lohnt." },
  "bronze_focus": { en: "Bronze takes the essence better than copper. The blank comes out of the bath with a dull warmth that lasts for years.", de: "Bronze nimmt die Essenz besser an als Kupfer. Der Rohling kommt mit einer matten Wärme aus dem Bad, die Jahre hält." },
  "bronze_fullhelm": { en: "Bronze closed over the face, the visor cast in one piece. It muffles the world, which in the Borderlands is a mercy.", de: "Bronze, über dem Gesicht geschlossen, das Visier aus einem Guss. Dämpft die Welt, was in den Grenzlanden eine Gnade ist." },
  "bronze_gauntlets": { en: "Bronze plates over the back of the hand, jointed at the fingers. You can still make a fist. That was the hard part.", de: "Bronzeplatten über dem Handrücken, an den Fingern gelenkig. Man kann noch eine Faust machen. Das war das Schwierige." },
  "bronze_greataxe": { en: "Bronze, two-handed, with a bit the width of a shovel. Lift it, and let the weight do the thinking.", de: "Bronze, zweihändig, das Blatt breit wie eine Schaufel. Heben, und das Gewicht denken lassen." },
  "bronze_greatsword": { en: "Bronze, two-handed, with a ridge down the blade to stop it bending. It mostly stops it.", de: "Bronze, zweihändig, ein Grat die Klinge entlang, damit sie sich nicht biegt. Meistens hilft das." },
  "bronze_kiteshield": { en: "Bronze over oak, with a boss that turns a blade instead of taking it. The first shield that does not dent on the first day.", de: "Bronze über Eiche, mit einem Buckel, der eine Klinge ablenkt, statt sie zu nehmen. Der erste Schild, der am ersten Tag keine Beule hat." },
  "bronze_longbow": { en: "Birch, pale and springy, the first wood a fletcher trusts with a real draw. It forgives a bad release better than a wet night.", de: "Birke, blass und federnd, das erste Holz, dem ein Bogner einen echten Zug zutraut. Verzeiht einen schlechten Abschuss eher als eine nasse Nacht." },
  "bronze_mace": { en: "Bronze flanges on a short haft. Where a blade skids off a helmet, this does not.", de: "Bronzeflansche an kurzem Stiel. Wo eine Klinge vom Helm abrutscht, tut er es nicht." },
  "bronze_maul": { en: "A bronze head the size of a bucket. The enemy's armor is a suggestion it declines to take.", de: "Ein Bronzekopf so groß wie ein Eimer. Die Rüstung des Gegners ist ein Vorschlag, den er ablehnt." },
  "bronze_medhelm": { en: "Bronze over the crown, the ears and face left open. You hear the blow coming. Whether that helps is another matter.", de: "Bronze über dem Scheitel, Ohren und Gesicht frei. Man hört den Schlag kommen. Ob das hilft, ist eine andere Frage." },
  "bronze_pickaxe": { en: "Bought, not forged. The bronze head dulls fast, but it bites a little quicker than bare hands and stubbornness.", de: "Gekauft, nicht geschmiedet. Der Bronzekopf wird schnell stumpf, beißt aber etwas flotter als bloße Hände und Sturheit." },
  "bronze_platebody": { en: "A bronze breastplate, cast thick at the chest and thin at the sides. The smiths put the metal where the blows land.", de: "Ein Bronze-Brustpanzer, dick an der Brust und dünn an den Seiten gegossen. Die Schmiede setzen das Metall dorthin, wo die Schläge landen." },
  "bronze_platelegs": { en: "Bronze over the legs, cast in long strips and riveted. Heavier than copper, and they hold their shape when you kneel.", de: "Bronze über den Beinen, in langen Streifen gegossen und vernietet. Schwerer als Kupfer, und sie halten die Form, wenn du kniest." },
  "bronze_sabatons": { en: "Bronze plates over the boot, jointed at the toe. They ring on stone and keep the foot whole.", de: "Bronzeplatten über dem Stiefel, an der Zehe gelenkig. Sie klingen auf Stein und halten den Fuß heil." },
  "bronze_scimitar": { en: "Bronze with a deep curve. The swing comes round on its own if you let it.", de: "Bronze mit tiefer Krümmung. Der Schwung kommt von allein herum, wenn man ihn lässt." },
  "bronze_shortbow": { en: "Birch bent short. Light, fast, and it forgives a cold hand.", de: "Birke, kurz gebogen. Leicht, schnell, und verzeiht eine kalte Hand." },
  "bronze_spear": { en: "Bronze with a leaf-shaped head and a socket that does not work loose. The fastest thing a smith can hand you.", de: "Bronze mit blattförmigem Kopf und einer Tülle, die sich nicht lockert. Das Schnellste, was ein Schmied dir reichen kann." },
  "bronze_staff": { en: "Bronze ferrules and a force shard that crackles when the air is dry. Holds a charge better than copper ever did.", de: "Bronzezwingen und ein Kraftsplitter, der bei trockener Luft knistert. Hält eine Ladung besser, als Kupfer es je tat." },
  "bronze_sword": { en: "Bronze, straight and plain. Nothing about it is special. That is the point of a sword.", de: "Bronze, gerade und schlicht. Nichts daran ist besonders. Das ist der Sinn eines Schwerts." },
  "bronze_towershield": { en: "Bronze, tall and flat, the shield the Mark's wall-guards stood behind. It has not changed since.", de: "Bronze, hoch und flach, der Schild, hinter dem die Wallwachen der Mark standen. Er hat sich seither nicht verändert." },
  "bronze_wand": { en: "Bronze with a shard that sweats a sour film. Keep your gloves on.", de: "Bronze mit einem Splitter, der einen sauren Film ausschwitzt. Handschuhe anbehalten." },
  "broodtalon_bow": { en: "A skarn whelp's claw, still growing when it was taken, strung for a short draw. The edge on the arrows is the whelp's.", de: "Die Klaue einer Skarnbrut, noch im Wachsen, als sie genommen wurde, für kurzen Zug bespannt. Die Schärfe an den Pfeilen gehört der Brut." },
  "buckhide_body": { en: "Buckhide over a panel of scarred hide at the chest. The scars make that one patch tougher than all the rest.", de: "Wildleder über einem Stück Narbenleder an der Brust. Die Narben machen gerade dieses Stück zäher als den ganzen Rest." },
  "buckhide_boots": { en: "Buckhide boots, soft and close, laced to the calf. A hunter forgets he is wearing them, which is the point.", de: "Wildlederstiefel, weich und eng, bis zur Wade geschnürt. Ein Jäger vergisst, dass er sie trägt, und das ist der Sinn." },
  "buckhide_helm": { en: "Buckhide, soft and close-fitting, stitched so the seams sit away from the ears. A hunter's coif, made for listening.", de: "Wildleder, weich und eng anliegend, so genäht, dass die Nähte nicht auf den Ohren sitzen. Eine Jägerhaube, zum Hören gemacht." },
  "buckhide_legs": { en: "Buckhide leggings, soft enough to crouch in and quiet enough to crouch in for an hour.", de: "Wildleder-Beinlinge, weich genug zum Kauern und leise genug, eine Stunde lang zu kauern." },
  "buckhide_vambraces": { en: "Buckhide wrapped twice around the forearm and stitched. Soft, quiet, and the string never finds skin.", de: "Wildleder zweimal um den Unterarm gewickelt und vernäht. Weich, leise, und die Sehne findet nie Haut." },
  "bulls_heart_pendant": { en: "The Maddened Bull's heart, dried and bound in wire. It beat harder than any heart in the Pastures, and each kill still gives a little of that back.", de: "Das Herz des Rasenden Bullen, getrocknet, in Draht gebunden. Es schlug härter als jedes Herz der Weiden, und jeder Kill gibt davon etwas zurück." },
  "cake_honey": { en: "Wildhive honey baked into grimwheat. Sweet enough to make the Pastures taste like somewhere kinder.", de: "Wildwaben-Honig, in Grimmkorn gebacken. Süß genug, dass die Weiden nach einem freundlicheren Ort schmecken." },
  "carrion_talisman": { en: "A lung of Carrionwind the Patient, dried to leather and hung on a cord. It waited out everything. What it lays on an enemy stays a little longer too.", de: "Eine Lunge von Aaswind dem Geduldigen, zu Leder getrocknet. Er wartete alles aus. Was es einem Gegner anhängt, bleibt auch länger." },
  "censerwood_log": { en: "Resin-rich wood that smells of old temples when the axe bites. It makes the finest bows and the finest rod the craft knows.", de: "Harzreiches Holz, das nach alten Tempeln riecht, wenn die Axt beißt. Daraus entstehen die feinsten Bögen und die feinste Angel des Handwerks." },
  "censerwood_longbow": { en: "Censerwood, cut near the Idol Hall. The resin still smells of incense burned for nothing, and the smell stays on the arrows.", de: "Weihrauchholz, nahe der Götzenhalle geschlagen. Das Harz riecht nach Weihrauch, der umsonst verbrannte, und der Geruch bleibt an den Pfeilen." },
  "censerwood_rod": { en: "Censerwood keeps its resin scent even wet, and the fish of the deep pools come to it. The finest rod the craft knows.", de: "Weihrauchholz riecht auch nass noch nach Harz, und die Fische der tiefen Becken kommen darauf zu. Die feinste Angel, die das Handwerk kennt." },
  "censerwood_shortbow": { en: "Censerwood bent short, the resin still fragrant. The shots come quicker as they go, like a prayer rushed to be done with it.", de: "Weihrauchholz, kurz gebogen, das Harz noch duftend. Die Schüsse kommen schneller, je länger es geht, wie ein Gebet, das man herunterrattert." },
  "chainbound_longbow": { en: "A forsaken servant's bow, the stave still wound in its chain. The fire on the arrows is borrowed, like everything the servants carry.", de: "Bogen eines Verlassenen Dieners, der Stab noch in seine Kette gewickelt. Das Feuer auf den Pfeilen ist geliehen, wie alles an den Dienern." },
  "chiselled_recurve": { en: "Chiselled from the lintel of the Expunged Chapel, where a name is missing from the stone. Each kill brings the next shot sooner.", de: "Aus dem Türsturz der Getilgten Kapelle gemeißelt, wo ein Name aus dem Stein fehlt. Jeder Kill bringt den nächsten Schuss schneller." },
  "chitin_helm": { en: "A pitch beetle's head shell, cleaned and lined with felt. Tar-black, light, and the kills under it close wounds.", de: "Die Kopfschale eines Pechkäfers, gereinigt und mit Filz gefüttert. Pechschwarz, leicht, und Kills darunter schließen Wunden." },
  "chitin_plate": { en: "A shell plate from a pitch beetle, black and glossy. Four of them, stitched over raw hide, make a coif that turns a glancing blade.", de: "Eine Panzerplatte vom Pechkäfer, schwarz und glänzend. Vier davon, über Rohleder genäht, geben eine Haube, die eine streifende Klinge ablenkt." },
  "cinder_spike": { en: "A pitch beetle's horn, still hot enough to tar the hand. It leaves a burn in whatever it pierces.", de: "Das Horn eines Pechkäfers, noch heiß genug, die Hand zu teeren. Es hinterlässt einen Brand in allem, was es durchbohrt." },
  "cinderfang_dagger": { en: "A shard of ember elemental, cooled just enough to hold. It never gets cold, and neither does what it cuts.", de: "Ein Splitter aus einem Glutelementar, gerade weit genug abgekühlt, um ihn zu halten. Er wird nie kalt, und was er schneidet, auch nicht." },
  "cinderhusk_bulwark": { en: "The shell of Cinderhusk the Unbowed, who never once turned its back. It holds hardest when its bearer is nearly spent.", de: "Der Panzer von Glutpanzer dem Ungebeugten, der nie den Rücken kehrte. Er hält am härtesten, wenn sein Träger fast am Ende ist." },
  "cinderloop_ring": { en: "A loop of charred wire from the Ash Tyrant's hoard. It is warm toward one thing at a time, and that thing is whatever Brenna has named.", de: "Eine Schlaufe aus verkohltem Draht aus dem Hort des Aschtyrannen. Sie wird warm für eines, und das ist, was Brenna genannt hat." },
  "cinderwretch_maul": { en: "The Forge Demon's hammer, a spark of the Stranger beaten into iron. Every fifth blow remembers who forged it.", de: "Der Hammer des Schmiededämons, ein Funke des Fremden in Eisen geschlagen. Jeder fünfte Schlag weiß noch, wer ihn schmiedete." },
  "clawguard_gloves": { en: "Dire wolf claws over the knuckles, strapped on with the wolf's own sinew. The hand hits hardest when it has the least left.", de: "Schreckenswolfskrallen über den Knöcheln, mit der Sehne des Wolfs festgeschnallt. Die Hand schlägt am härtesten, wenn ihr am wenigsten bleibt." },
  "clear_oil": { en: "Thin oil, filtered until it holds no colour. Herbalists draw their tonics in it when water would not take the essence.", de: "Dünnes Öl, gefiltert, bis es keine Farbe mehr hält. Kräuterkundige ziehen ihre Tonika darin, wenn Wasser die Essenz nicht aufnimmt." },
  "cloudwalker_boots": { en: "Boots from the ledges of the Gravecliff and the Idol Hall. The sole never quite touches the ground, and after a kill the next step comes sooner.", de: "Stiefel von den Simsen der Grabklippen und der Götzenhalle. Die Sohle berührt den Boden nie ganz, und nach einem Kill geht es schneller weiter." },
  "cooked_abyssal_crawler": { en: "Braised slow, legs and all. What comes out of the abyss tastes of iron and salt, and it keeps you standing.", de: "Langsam geschmort, mitsamt den Beinen. Was aus dem Abgrund kommt, schmeckt nach Eisen und Salz und hält auf den Beinen." },
  "cooked_anglerfish": { en: "Fried hard so you do not have to look at the face. The meat beneath is sweeter than the lure ever promised.", de: "Scharf gebraten, damit man das Gesicht nicht ansehen muss. Das Fleisch darunter ist süßer, als die Lockangel je versprach." },
  "cooked_ashen_sturgeon": { en: "Smoked until the flesh goes dark and firm. A cut that keeps for weeks and heals as if it was worth the wait.", de: "Geräuchert, bis das Fleisch dunkel und fest wird. Hält wochenlang und heilt, als hätte sich das Warten gelohnt." },
  "cooked_ashpike": { en: "Grilled on the bone. The pike's grey flesh takes the fire well and fills a fighter between two hard rounds.", de: "Auf der Gräte gegrillt. Das graue Fleisch des Hechts nimmt das Feuer gut an und sättigt zwischen zwei harten Gängen." },
  "cooked_beef": { en: "Pasture beef seared on a flat stone. Plain food, honestly cooked, and better than most of what the Reach offers.", de: "Weidenrind, auf flachem Stein gebraten. Schlichtes Essen, ehrlich gekocht, und besser als das meiste, was das Reach hergibt." },
  "cooked_bloodfang_eel": { en: "Seared quick so the skin crisps and the blood stays in. Fishers of the deep water eat it standing up.", de: "Kurz angebraten, damit die Haut knuspert und das Blut drin bleibt. Die Fischer des tiefen Wassers essen ihn im Stehen." },
  "cooked_chicken": { en: "A Pastures hen roasted over the first fire of the evening. Nobody in Emberhold turns one down.", de: "Ein Weidenhuhn, über dem ersten Feuer des Abends gebraten. Keiner in der Glutfeste lehnt das ab." },
  "cooked_cod": { en: "Cod roasted whole, flaking white off the bone. Coastal fare that travels well inland.", de: "Kabeljau im Ganzen gebraten, weiß und blättrig von der Gräte. Küstenkost, die sich gut ins Inland tragen lässt." },
  "cooked_crypteel": { en: "Roasted until the taste of crypt water burns off. Whatever runs in this eel's blood clears a poison from yours.", de: "Geröstet, bis der Geschmack des Kryptawassers verbrannt ist. Was im Blut dieses Aals fließt, treibt das Gift aus deinem." },
  "cooked_dirgefin": { en: "Steamed gently, which is the only way the dirgefin keeps its flesh. It still complains a little when the lid comes off.", de: "Sanft gedünstet, denn nur so behält der Klageflosser sein Fleisch. Beim Abheben des Deckels klagt er noch ein wenig." },
  "cooked_duskfin_carp": { en: "Steamed with the fins on. Mild, fatty and filling, the way a carp should be.", de: "Mit den Flossen gedämpft. Mild, fett und sättigend, wie ein Karpfen sein soll." },
  "cooked_ghostfin_pike": { en: "Roasted over an open flame, and the pale fins curl and vanish. The meat is firmer than it looks.", de: "Über offener Flamme geröstet, und die bleichen Flossen kräuseln sich und verschwinden. Das Fleisch ist fester, als es aussieht." },
  "cooked_idolscale": { en: "Consecrated rather than cooked: the scales come off only to a blessing. The last dish the craft teaches.", de: "Geweiht statt gekocht: Die Schuppen lösen sich nur auf einen Segen hin. Das letzte Gericht, das die Kochkunst lehrt." },
  "cooked_ironscale_bass": { en: "Grilled once the scales have been fought off. The flesh is dense and dark and sits in the stomach the way a good meal should.", de: "Gegrillt, sobald die Schuppen abgekämpft sind. Das Fleisch ist dicht und dunkel und liegt im Magen, wie ein gutes Mahl soll." },
  "cooked_lobster": { en: "Boiled red in salt water. The claws give the most meat and the least argument once they stop moving.", de: "Rot gekocht in Salzwasser. Die Scheren geben das meiste Fleisch und den wenigsten Widerstand, sobald sie sich nicht mehr rühren." },
  "cooked_murk_perch": { en: "Fried in its own fat, bog taste and all. The first fish most fighters eat before their first real wound.", de: "Im eigenen Fett gebraten, Moorgeschmack inklusive. Der erste Fisch, den die meisten Kämpfer vor ihrer ersten echten Wunde essen." },
  "cooked_salmon": { en: "Grilled skin-side down until it crackles. Salmon is the first fish worth walking to the river for.", de: "Mit der Haut nach unten gegrillt, bis sie knistert. Der Lachs ist der erste Fisch, für den sich der Weg zum Fluss lohnt." },
  "cooked_shadowcarp": { en: "Pan-fried in a little oil. The dark flesh stays dark and tastes of the slow water it came from.", de: "In wenig Öl gebraten. Das dunkle Fleisch bleibt dunkel und schmeckt nach dem trägen Wasser, aus dem es kam." },
  "cooked_shrimp": { en: "A handful of shrimp tossed on hot stone. Hardly a meal, but it closes a scratch.", de: "Eine Handvoll Shrimps auf heißem Stein. Kaum eine Mahlzeit, aber sie schließt einen Kratzer." },
  "cooked_soulfish": { en: "Not cooked so much as absolved. The soulfish gives up what it carries, and what is left heals deep.", de: "Weniger gekocht als losgesprochen. Der Seelenfisch gibt ab, was er trägt, und was bleibt, heilt tief." },
  "cooked_trout": { en: "Trout roasted on a green stick. Simple river food, and it heals better than the hen.", de: "Forelle am grünen Stock geröstet. Einfache Flusskost, und sie heilt besser als das Huhn." },
  "cooked_voidray": { en: "Seared fast, before the flesh remembers where it came from. Dark, dense and strangely filling.", de: "Schnell angebraten, bevor das Fleisch sich erinnert, woher es kam. Dunkel, dicht und seltsam sättigend." },
  "cooked_wraithscale": { en: "Smoked until the pale scales turn to ash. The meat beneath is as solid as the fish was ghostly.", de: "Geräuchert, bis die bleichen Schuppen zu Asche werden. Das Fleisch darunter ist so fest, wie der Fisch geisterhaft war." },
  "copper_arrow": { en: "A shaft, a copper head and a feather, fifteen to the batch. The first arrow a fletcher makes, and it still flies straight.", de: "Ein Schaft, eine Kupferspitze und eine Feder, fünfzehn je Satz. Der erste Pfeil, den ein Bogner fertigt, und er fliegt trotzdem gerade." },
  "copper_arrowheads": { en: "Forty-five soft copper heads hammered from a single bar. They bend on bone, but they are the first heads any fletcher gets.", de: "Fünfundvierzig weiche Kupferspitzen aus einem Barren. Sie verbiegen sich an Knochen, aber es sind die ersten Spitzen, die ein Bogner bekommt." },
  "copper_axe": { en: "Soft copper on an ash handle. It fells a sapling or a goblin, and it dulls on both.", de: "Weiches Kupfer an einem Eschenstiel. Fällt einen Schössling oder einen Goblin, und wird an beidem stumpf." },
  "copper_bar": { en: "The first bar a smith pours, soft enough to work cold. Scrap metal melts down to it as well, four pieces to the bar.", de: "Der erste Barren, den ein Schmied gießt, weich genug für kalte Arbeit. Auch Metallschrott schmilzt dazu, vier Stück je Barren." },
  "copper_battleaxe": { en: "A wider head than the woodsman's axe wants, hung on copper that bends if the swing goes wrong. Make the swing count.", de: "Ein breiterer Kopf, als die Holzfälleraxt braucht, auf Kupfer, das sich verbiegt, wenn der Schwung falsch sitzt. Also soll er sitzen." },
  "copper_chainbody": { en: "Four bars of copper drawn into rings and linked by hand. The rings open under a hard blow, but they take the edge off it first.", de: "Vier Barren Kupfer zu Ringen gezogen und von Hand verkettet. Die Ringe öffnen sich unter einem harten Schlag, nehmen ihm aber erst die Schärfe." },
  "copper_dagger": { en: "A copper blade on a wooden grip. Too soft to hold a point for long, quick enough that it does not need to.", de: "Eine Kupferklinge auf Holzgriff. Zu weich, um die Spitze lange zu halten, schnell genug, dass sie das nicht muss." },
  "copper_focus": { en: "A copper blank steeped in dim essence until it holds a little of it. Sits in the off hand and keeps the caster's head steady.", de: "Ein Kupferrohling, in Trübessenz gelegt, bis er etwas davon behält. Liegt in der Nebenhand und hält den Kopf ruhig." },
  "copper_fullhelm": { en: "Two bars of copper around the whole head, with a slit to see through. Soft enough that a hard blow leaves the shape of the blow.", de: "Zwei Barren Kupfer um den ganzen Kopf, ein Schlitz zum Sehen. Weich genug, dass ein harter Schlag die Form des Schlags hinterlässt." },
  "copper_gauntlets": { en: "One bar of copper beaten over leather gloves. They stop a knuckle from breaking. They do not stop much else.", de: "Ein Barren Kupfer über Lederhandschuhe geschlagen. Sie bewahren einen Knöchel vor dem Bruch. Viel mehr bewahren sie nicht." },
  "copper_greataxe": { en: "Three bars of copper on a haft as tall as a man. It is slow, and it is heavy, and the first swing usually settles it.", de: "Drei Barren Kupfer an einem mannshohen Stiel. Sie ist langsam und schwer, und meist entscheidet der erste Schwung." },
  "copper_greatsword": { en: "A long copper blade that flexes on the backswing. Faster than the greataxe, softer than everything else.", de: "Eine lange Kupferklinge, die beim Ausholen federt. Schneller als die Großaxt, weicher als alles andere." },
  "copper_kiteshield": { en: "A teardrop of hammered copper over a wooden core. Light enough to carry all day and soft enough to show every blow it took.", de: "Ein Tropfen aus gehämmertem Kupfer über Holzkern. Leicht genug für den ganzen Tag und weich genug, jeden Schlag zu zeigen, den er nahm." },
  "copper_longbow": { en: "Green timber, cut and bent before it had the sense to dry. It will take a set within the month. The first arrow still flies true.", de: "Grünes Holz, geschlagen und gebogen, bevor es trocknen konnte. In einem Monat hat es sich verzogen. Der erste Pfeil fliegt trotzdem gerade." },
  "copper_mace": { en: "A copper head on an oak shaft. It does not cut, so it needs no edge, and copper has none to offer.", de: "Ein Kupferkopf auf Eichenschaft. Er schneidet nicht, braucht also keine Schneide, und Kupfer hätte keine zu bieten." },
  "copper_maul": { en: "Three bars of copper hammered into one lump on a pole. Nothing about it is clever. Nothing about it needs to be.", de: "Drei Barren Kupfer zu einem Klumpen an einer Stange geschlagen. Nichts daran ist klug. Nichts daran muss es sein." },
  "copper_medhelm": { en: "A copper skullcap, open at the face. The first thing an apprentice is allowed to put on someone else's head.", de: "Eine Kupferkalotte, am Gesicht offen. Das Erste, was ein Lehrling auf einen fremden Kopf setzen darf." },
  "copper_ore": { en: "Green-streaked rock from the first vein any miner is shown. One lump smelts to one bar, and with tin it makes bronze.", de: "Grün gestreiftes Gestein aus der ersten Ader, die man einem Bergmann zeigt. Ein Brocken gibt einen Barren, mit Zinn wird Bronze daraus." },
  "copper_platebody": { en: "Five bars of copper beaten into a breastplate that dents at the first serious argument. It can be beaten flat again. Most things cannot.", de: "Fünf Barren Kupfer zu einem Brustpanzer geschlagen, der beim ersten Ernst Beulen bekommt. Man schlägt ihn wieder glatt. Das Meiste geht so nicht." },
  "copper_platelegs": { en: "Copper plates over the thighs and shins, hinged at the knee. They clank, and they bend if you kneel too hard.", de: "Kupferplatten über Schenkel und Schienbein, am Knie gelenkig. Sie klappern, und sie biegen sich, wenn du zu hart kniest." },
  "copper_sabatons": { en: "Copper over the toes and instep, strapped to a boot. They scrape on stone, and they bend if you kick something that kicks back.", de: "Kupfer über Zehen und Spann, an einen Stiefel geschnallt. Sie kratzen auf Stein, und sie biegen sich, wenn du etwas trittst, das zurücktritt." },
  "copper_scimitar": { en: "A curved copper blade for cutting, not stabbing. Each stroke sets up the next, and copper is soft enough to follow.", de: "Eine gebogene Kupferklinge zum Schneiden, nicht zum Stechen. Jeder Hieb bereitet den nächsten vor, und Kupfer ist weich genug, mitzugehen." },
  "copper_shortbow": { en: "Green timber bent short and strung tight. It will not reach far, but it reaches often.", de: "Grünes Holz, kurz gebogen und straff bespannt. Reicht nicht weit, aber oft." },
  "copper_spear": { en: "A copper head on a long ash pole. It reaches before anything reaches back, which is all copper can promise.", de: "Ein Kupferkopf an einer langen Eschenstange. Er reicht hin, bevor etwas zurückreicht, und mehr kann Kupfer nicht versprechen." },
  "copper_staff": { en: "A copper-shod staff with a force shard at the tip. Every runecrafter's first piece of work, and it already sets fires.", de: "Ein kupferbeschlagener Stab, ein Kraftsplitter an der Spitze. Das erste Werkstück jedes Runenkundigen, und es legt schon Brände." },
  "copper_sword": { en: "A copper blade, the first thing an apprentice forges that is allowed to leave the smithy. It bends. It still cuts.", de: "Eine Kupferklinge, das erste Stück, das ein Lehrling schmiedet und das die Schmiede verlassen darf. Sie biegt sich. Sie schneidet trotzdem." },
  "copper_towershield": { en: "Three bars of copper beaten into a door. It covers from chin to shin, and the arm knows it by noon.", de: "Drei Barren Kupfer zu einer Tür geschlagen. Deckt vom Kinn bis zum Schienbein, und der Arm weiß es bis Mittag." },
  "copper_wand": { en: "A copper rod no longer than a forearm, tipped with a force shard. Quick to raise, and the frost on it is thin but real.", de: "Ein Kupferstab, nicht länger als ein Unterarm, ein Kraftsplitter an der Spitze. Schnell erhoben, der Frost darauf dünn, aber echt." },
  "coral_shiv": { en: "Reef coral snapped off and ground sharp, pulled from the mud of the Shoals. The first stab is the one it was made for.", de: "Riffkoralle, abgebrochen und scharf geschliffen, aus dem Schlick der Untiefen gezogen. Der erste Stich ist der, für den sie gemacht wurde." },
  "corpse_lily_bulb": { en: "The bulb of the corpse lily, heavy and smelling of exactly what you think. Crushed into oil, it makes the salve that heals the deepest.", de: "Die Zwiebel der Leichenlilie, schwer und riechend nach genau dem, was du denkst. In Öl zerdrückt gibt sie die Salbe, die am tiefsten heilt." },
  "corpse_lily_salve": { en: "Corpse lily bulbs crushed into oil. It smells of what the lily grows on and heals like nothing the Pastures ever gave.", de: "Leichenlilien-Zwiebeln, in Öl zerdrückt. Riecht nach dem, worauf die Lilie wächst, und heilt wie nichts, was die Weiden je hergaben." },
  "corpse_lily_seed": { en: "A seed found among the void fungus, grey and faintly sweet-smelling. The lily it grows feeds on what lies beneath it.", de: "Ein Same zwischen den Leerenpilzen, grau und schwach süßlich riechend. Die Lilie, die daraus wächst, zehrt von dem, was unter ihr liegt." },
  "cowhide_cap": { en: "A cowhide cap the goats and chickens drag around the empty farmyards. The brim shades the eyes, and the first shot from under it lands.", de: "Eine Rinderlederkappe, die Ziegen und Hühner über die leeren Höfe schleifen. Der Rand beschattet die Augen, und der erste Schuss darunter sitzt." },
  "cowhide_jerkin": { en: "A farmhand's jerkin, cowhide gone hard as board, dragged off by the boars. Hit the one wearing it, and the hit comes back.", de: "Das Wams eines Knechts, Rinderleder hart wie Brett, von den Wildschweinen verschleppt. Wer den Träger trifft, bekommt den Treffer zurück." },
  "crabshell_bulwark": { en: "A mud crab's shell, cleaned out and strapped. Whatever cracks against it tends to stay cracked.", de: "Der Panzer einer Schlickkrabbe, ausgeräumt und geriemt. Was daran zerbricht, bleibt meist zerbrochen." },
  "crude_fishing_rod": { en: "A stick, a line and a bent hook. Not much, but more than bare hands in cold water.", de: "Ein Stock, eine Schnur, ein krummer Haken. Nicht viel, aber mehr als bloße Hände im kalten Wasser." },
  "crude_sickle": { en: "A rough blade on a short handle, sold to anyone heading out to the Ashfields. It cuts stems faster than fingers tear them.", de: "Eine grobe Klinge am kurzen Griff, verkauft an jeden, der in die Aschfelder will. Sie schneidet Stängel schneller, als Finger sie reißen." },
  "crude_waraxe": { en: "A goblin spearman's second weapon, ground from a stolen plough blade. It swings hardest when its wielder is already bleeding.", de: "Die Zweitwaffe eines Goblin-Speerträgers, aus einer gestohlenen Pflugschar geschliffen. Schlägt am härtesten, wenn ihr Träger schon blutet." },
  "crypt_key": { en: "A heavy key with the Order's mark, from the days when the Crypt was still sealed. The seal is broken now and the key opens nothing.", de: "Ein schwerer Schlüssel mit dem Zeichen des Ordens, aus der Zeit, als die Krypta versiegelt war. Das Siegel ist gebrochen, er öffnet nichts mehr." },
  "cryptguard_helm": { en: "A skeleton warrior's helm from the Crypt, the Order's shape still under the rust. Each kill under it knits a wound shut.", de: "Der Helm eines Skelettkriegers aus der Krypta, die Form des Ordens noch unter dem Rost. Jeder Kill darunter näht eine Wunde zu." },
  "cured_leather": { en: "Raw hide scraped, salted and worked until it bends without cracking. Caps, jerkins and the first quivers are cut from it.", de: "Rohleder, geschabt, gesalzen und bearbeitet, bis es sich biegt, ohne zu reißen. Kappen, Wämser und die ersten Köcher werden daraus geschnitten." },
  "cured_leather_body": { en: "Four cured hides stitched into a jerkin, the seams doubled where the arrows go. Light enough to draw a bow in.", de: "Vier gegerbte Häute zu einem Wams genäht, die Nähte dort doppelt, wo Pfeile hingehen. Leicht genug, um darin einen Bogen zu spannen." },
  "cured_leather_boots": { en: "Cured leather boots with a doubled sole. Quiet on grass, quiet on stone, which is the whole trick of hunting.", de: "Gegerbte Lederstiefel mit doppelter Sohle. Leise auf Gras, leise auf Stein, und das ist der ganze Trick beim Jagen." },
  "cured_leather_cap": { en: "Cured leather shaped over a block and left to dry hard. Light, quiet, and it does not get in the way of the bowstring.", de: "Gegerbtes Leder, über einen Klotz geformt und hart getrocknet. Leicht, leise, und es kommt der Sehne nicht in den Weg." },
  "cured_leather_legs": { en: "Cured leather chaps, laced tight, the seams on the outside so they do not rub. A hunter walks a long way in these.", de: "Gegerbte Lederbeinlinge, eng geschnürt, die Nähte außen, damit sie nicht scheuern. Ein Jäger geht darin weit." },
  "cured_leather_vambraces": { en: "A single cured hide wrapped from wrist to elbow. It keeps the bowstring off the forearm, which is all it was asked to do.", de: "Eine einzelne gegerbte Haut vom Handgelenk bis zum Ellbogen gewickelt. Hält die Sehne vom Unterarm fern, und mehr wurde nicht verlangt." },
  "cutpurse_ring": { en: "A goblin rogue's ring, which has been on more fingers than the rogue could count. Whatever it is pointed at tends to leave something behind.", de: "Der Ring eines Goblin-Schurken, der an mehr Fingern war, als der Schurke zählen konnte. Wen er trifft, der lässt meist etwas liegen." },
  "deathmoss": { en: "Grey moss that grows on things that have stopped moving. Ground with ashen dust, it is the Deepwood's own cure for its own bites.", de: "Graues Moos, das auf Dingen wächst, die sich nicht mehr rühren. Mit Aschestaub zerrieben das Mittel des Tiefwalds gegen seine eigenen Bisse." },
  "diamond": { en: "Cut until the cloud is gone and the light has nowhere to hide. Set in mithril, and once in a titanium focus, it is the jeweller's proudest stone.", de: "Geschliffen, bis die Trübung weg ist und das Licht sich nirgends verstecken kann. In Mithril gefasst der stolzeste Stein des Juweliers." },
  "diamond_amulet": { en: "A diamond in mithril, the hardest stone in the lightest metal. It finds the seam in anything, including plate.", de: "Ein Diamant in Mithril, der härteste Stein im leichtesten Metall. Er findet die Naht in allem, auch in Platte." },
  "diamond_ring": { en: "A diamond in mithril, the hardest stone in the lightest metal. It finds the seam in anything, and the hand behind it finds its mark.", de: "Ein Diamant in Mithril, der härteste Stein im leichtesten Metall. Er findet die Naht in allem, und die Hand dahinter ihr Ziel." },
  "dim_focus": { en: "A copper blank soaked until the essence crystallized on it. Clouded like old glass, but it sharpens the mind rather than the eye.", de: "Ein Kupferrohling, getränkt, bis die Essenz darauf kristallisierte. Trüb wie altes Glas, schärft aber den Verstand statt das Auge." },
  "direfang_maul": { en: "A dire wolf's skull on a Wildwood haft, the fangs left in. It bleeds what it bites, and every fifth blow bites deeper.", de: "Der Schädel eines Schreckenswolfs auf einem Wildwaldstiel, die Reißzähne noch drin. Was er beißt, blutet, und jeder fünfte Schlag beißt tiefer." },
  "direhide_jerkin": { en: "Wolf hide from the Wildwood and the Frost Caverns, the fur left on the inside. The first cut you make in it lands deepest.", de: "Wolfshaut aus Wildwald und Frostkavernen, das Fell nach innen. Der erste Schnitt, den du darin setzt, sitzt am tiefsten." },
  "doomforged_band": { en: "A band of the Charred Doomknight's own plate, hammered round in the slag. He did not come out of the fire. The ring did, and the wounds under it close on their own.", de: "Ein Reif aus der Platte des Verkohlten Schicksalsritters. Er kam nicht aus dem Feuer heraus. Der Ring schon, und die Wunden darunter schließen sich von selbst." },
  "doomknight_cinderblade": { en: "The Charred Doomknight's sword, carried into the slag and out again. It burns, it drinks, and it ends what is already failing. He never put it down.", de: "Das Schwert des Verkohlten Schicksalsritters, in die Schlacke getragen und wieder heraus. Es brennt, es trinkt, es beendet, was schon fällt. Er hat es nie abgelegt." },
  "dragonhide_body": { en: "Four dragonhides into one cuirass, thick and iridescent. It shifts color as you move, and arrows have trouble deciding where you are.", de: "Vier Drachenleder zu einem Kürass, dick und schillernd. Es wechselt die Farbe, wenn du dich bewegst, und Pfeile wissen nicht, wo du bist." },
  "dragonhide_boots": { en: "Dragonhide boots, thick and iridescent. They change color with the ground, and nothing aimed at the ankle quite lands.", de: "Drachenlederstiefel, dick und schillernd. Sie wechseln die Farbe mit dem Boden, und nichts, was auf den Knöchel zielt, sitzt ganz." },
  "dragonhide_helm": { en: "Dragonhide, thick and iridescent, shaped into a coif. It shifts color when you turn your head, and arrows shift with it.", de: "Drachenleder, dick und schillernd, zu einer Haube geformt. Es wechselt die Farbe, wenn du den Kopf drehst, und Pfeile wechseln mit." },
  "dragonhide_legs": { en: "Dragonhide greaves, thick and shimmering. They change color when you move, and so does whatever is aiming at your knees.", de: "Drachenleder-Beinschienen, dick und schillernd. Sie wechseln die Farbe, wenn du dich bewegst, und das verwirrt, was auf deine Knie zielt." },
  "dragonhide_vambraces": { en: "Dragonhide around the forearm, thick and iridescent. The bowstring slides off it, and so does most of what is aimed at the arm.", de: "Drachenleder um den Unterarm, dick und schillernd. Die Sehne gleitet daran ab, und das meiste, was auf den Arm zielt, auch." },
  "dreadfang_glaive": { en: "Dreadfang's own tooth on a pole, from the Whispering Void. It opens wounds that keep on opening.", de: "Schreckenzahns eigener Zahn an einer Stange, aus der Flüsternden Leere. Er reißt Wunden, die nicht aufhören, sich zu öffnen." },
  "driftwood_bow": { en: "Driftwood from the Shoals, salt-bleached and still strung with somebody's rigging. The arrows leave a ragged wound.", de: "Treibholz von den Untiefen, salzgebleicht und noch mit jemandes Takelage bespannt. Die Pfeile hinterlassen eine ausgefranste Wunde." },
  "drovers_charm": { en: "A boar's tooth on a leather thong that was once meant to keep a herd safe. The herd is gone. Now it mends the wearer instead, a little, with every kill.", de: "Ein Eberzahn am Lederriemen, der einmal eine Herde schützen sollte. Die Herde ist fort. Jetzt flickt er den Träger, ein wenig, mit jedem Kill." },
  "drowned_cutlass": { en: "A sailor's cutlass, brought back by the tide with the sailor still holding it. The rust has an edge of its own.", de: "Das Entermesser eines Seemanns, von der Flut zurückgebracht, der Seemann noch daran. Der Rost hat eine eigene Schneide." },
  "duskcap": { en: "A mushroom the colour of the hour it opens in. Two of them in water make a tonic that heals a good deal.", de: "Ein Pilz in der Farbe der Stunde, in der er aufgeht. Zwei davon in Wasser geben ein Tonikum, das ordentlich heilt." },
  "duskcap_seed": { en: "A dark spore cap found among the verdant blooms. Sown in a plot, it grows duskcaps in the time it takes to eat dinner.", de: "Eine dunkle Sporenkappe, zwischen den Grünblüten gefunden. Ins Beet gesät wachsen Dämmerkappen daraus, während man zu Abend isst." },
  "duskcap_tonic": { en: "Two duskcaps simmered in water. Dark as the hour they are named for, and it mends a good share of what the day broke.", de: "Zwei Dämmerkappen in Wasser geköchelt, dunkel wie die Stunde, nach der sie heißen. Heilt ein gutes Stück von dem, was der Tag zerschlug." },
  "duskfin_rangers_stew": { en: "Carp and venison with soulgourd and a pinch of gravemoss. A ranger's pot: it lightens the step and steadies the hand.", de: "Karpfen und Hirsch mit Seelenkürbis und einer Prise Grabmoos. Ein Jägertopf: macht den Schritt leichter und die Hand sicherer." },
  "duskhide_body": { en: "Scaled leather dyed dusk-dark and bound at the seams with mithril. Made for the hour when the light goes, and it goes with it.", de: "Schuppenleder dämmerdunkel gefärbt und an den Nähten mit Mithril gebunden. Gemacht für die Stunde, in der das Licht geht, und es geht mit." },
  "duskhide_boots": { en: "Scaled leather dyed dusk-dark, a thread of mithril in the sole to keep the shape. Boots for the hour when the hunting starts.", de: "Schuppenleder dämmerdunkel gefärbt, ein Faden Mithril in der Sohle hält die Form. Stiefel für die Stunde, in der die Jagd beginnt." },
  "duskhide_helm": { en: "Scaled leather dyed in dusk colors and stiffened with a mithril band. Made for the hour when the light fails and the hunting starts.", de: "Schuppenleder in Dämmerfarben gefärbt und mit einem Mithrilband versteift. Gemacht für die Stunde, in der das Licht geht und die Jagd beginnt." },
  "duskhide_legs": { en: "Scaled leather dyed dusk-dark, the seams bound with a thread of mithril. Chaps for the hour when the hunt starts.", de: "Schuppenleder dämmerdunkel gefärbt, die Nähte mit einem Faden Mithril gebunden. Beinlinge für die Stunde, in der die Jagd beginnt." },
  "duskhide_vambraces": { en: "Scaled leather dyed dusk-dark, a mithril band at the wrist to keep the shape. Vambraces for the hour the light goes.", de: "Schuppenleder dämmerdunkel gefärbt, ein Mithrilband am Handgelenk hält die Form. Armschützer für die Stunde, in der das Licht geht." },
  "dustblade": { en: "A blade scoured grey by the Ashfields and dug up again by the ash rats. The first cut is the deep one.", de: "Eine Klinge, von den Aschfeldern grau gescheuert und von den Aschratten ausgegraben. Der erste Schnitt ist der tiefe." },
  "dustwalker_boots": { en: "Boots the dust vultures pick clean on the Ashfields and leave in their roosts. They know the grey. After a kill, they walk on sooner.", de: "Stiefel, die die Staubgeier leerpicken und im Horst liegen lassen. Sie kennen das Grau der Aschfelder. Nach einem Kill gehen sie schneller weiter." },
  "elixir_grave_lily": { en: "Grave lily and divine essence, nothing else. It quickens the hand and sharpens the eye, and lasts longer than the apex brew.", de: "Grableimkraut und Göttliche Essenz, sonst nichts. Macht die Hand schnell und das Auge scharf, und hält länger vor als das Apex-Tonikum." },
  "elixir_renewal": { en: "Godsbreath and a drop of divine essence, taken in water. The body remembers how it was made and goes back to it.", de: "Götteratem und ein Tropfen Göttliche Essenz, in Wasser genommen. Der Leib erinnert sich, wie er gemacht wurde, und kehrt dahin zurück." },
  "elixir_warding": { en: "Nightbloom and void fungus in water, a caster's draught. It purges poison and lays a wider ward over whatever the robe already holds.", de: "Nachtblüte und Leeren-Pilz in Wasser, ein Trank für Zauberer. Treibt Gift aus und legt einen weiteren Ward über das, was die Robe schon hält." },
  "ember_essence": { en: "What is left of a fire after the thing that carried it dies. Warlocks and ash beasts drop it. Runecrafters bind it into fire shards.", de: "Was von einem Feuer bleibt, wenn stirbt, was es trug. Hexenmeister und Aschegetier lassen sie fallen. Runenkundige binden sie zu Feuersplittern." },
  "emberforge_hammer": { en: "A hammer from the Slag Pit's forges, heated by ember elementals so long it never went grey again. Every fifth blow lands like the first.", de: "Ein Hammer aus den Essen der Schlackengrube, von Glutelementaren erhitzt, bis er nie wieder grau wurde. Jeder fünfte Schlag sitzt wie der erste." },
  "emberforge_helm": { en: "Forged in the Slag Pit and worn by something that was the heat itself. It still runs warm, and kills under it close wounds.", de: "Geschmiedet in der Schlackengrube, getragen von etwas, das selbst die Hitze war. Er läuft noch warm, und Kills darunter schließen Wunden." },
  "emberheart_amulet": { en: "An ember from the heart of a voidhusk crusher, set in slag that never cooled. It burns toward one thing at a time, and that thing is whatever Brenna has named.", de: "Glut aus dem Herzen eines Leeren-Zerschmetterers, in Schlacke gefasst, die nie erkaltete. Sie brennt auf eines zu: das, was Brenna genannt hat." },
  "emberleaf": { en: "A leaf from the Cinderwood that stays warm after it is picked. Brewed, it makes a tonic. Packed into an arrowhead, it makes the arrow burn.", de: "Ein Blatt aus dem Glutwald, das nach dem Pflücken warm bleibt. Gebraut ein Tonikum, in eine Pfeilspitze gestopft ein brennender Pfeil." },
  "emberroot": { en: "A red root that is warm long after it is pulled. In clear oil it makes a tonic that keeps a slow heat in the blood.", de: "Eine rote Wurzel, die noch lange nach dem Ziehen warm ist. In klarem Öl gibt sie ein Tonikum, das eine leise Hitze im Blut hält." },
  "emberroot_seed": { en: "A seed that is warm in the pouch, found in the Frostmire and the Gloomfen of all places. The root it grows keeps the heat.", de: "Ein Same, der im Beutel warm ist, gefunden ausgerechnet im Frostmoor und in der Düstermarsch. Die Wurzel daraus behält die Hitze." },
  "emberroot_tonic": { en: "Emberroot in oil, warm long after the fire is out. It keeps a slow heat in the blood, and wounds close while you fight.", de: "Glutwurz in Öl, warm noch lange nach dem Feuer. Hält eine leise Hitze im Blut, und Wunden schließen sich, während du kämpfst." },
  "emptied_shrine_focus": { en: "Taken from the Expunged Chapel, where a god's name was cut out of the stone. Strike its bearer, and the empty place answers.", de: "Aus der Getilgten Kapelle, wo der Name eines Gottes aus dem Stein geschnitten wurde. Wer seinen Träger schlägt, bekommt Antwort aus der Lücke." },
  "enchanted_adamantium_focus": { en: "An adamantium blank that took half a day at the forge to bind. Two measures of aether essence turn it into a focus that does not crack.", de: "Adamantium und Binder, einen halben Tag am Ofen, bis es saß. Zwei Maß Aetheressenz machen daraus einen Fokus, der nicht springt." },
  "enchanted_aetherium_focus": { en: "An aetherium blank that hums faintly even before the essence goes in. Three measures of void essence make it a focus.", de: "Ein Aetherium-Rohling, der leise summt, noch bevor die Essenz hineingeht. Drei Maß Leerenessenz machen einen Fokus daraus." },
  "enchanted_blacksteel_focus": { en: "A blacksteel blank, dark and heavy, bound at the forge. Three measures of frost essence wake it.", de: "Ein Schwarzstahl-Rohling, dunkel und schwer, am Ofen gebunden. Drei Maß Frostessenz wecken ihn." },
  "enchanted_bloodiron_focus": { en: "A bloodiron blank with the binder worked deep into the red grain. Three measures of aether essence finish it.", de: "Ein Bluteisen-Rohling, der Binder tief in die rote Maserung gearbeitet. Drei Maß Aetheressenz vollenden ihn." },
  "enchanted_bronze_focus": { en: "Bronze and binder, shaped to take a charge. Three measures of dim essence finish it into a bronze focus.", de: "Bronze und Binder, geformt, um eine Ladung aufzunehmen. Drei Maß Trübessenz vollenden ihn zum Bronze-Fokus." },
  "enchanted_copper_focus": { en: "A copper bar forged over magic binder until it will hold a spell. Dim essence turns it into the first focus a caster carries.", de: "Ein Kupferbarren, über Magiebinder geschmiedet, bis er einen Zauber hält. Trübessenz macht daraus den ersten Fokus, den ein Zauberer trägt." },
  "enchanted_godiron_focus": { en: "Godiron bound with binder at the very top of the craft. Four measures of void essence and an onyx finish it into the last focus there is.", de: "Götzeneisen mit Binder, am obersten Ende des Handwerks. Vier Maß Leerenessenz und ein Onyx vollenden ihn zum letzten Fokus, den es gibt." },
  "enchanted_iron_focus": { en: "An iron blank that has had the binder worked into it at the forge. It wants four measures of dim essence before it answers to anyone.", de: "Ein Eisenrohling, in den am Ofen der Binder eingearbeitet wurde. Er will vier Maß Trübessenz, bevor er irgendwem gehorcht." },
  "enchanted_mithril_focus": { en: "Mithril and binder, light enough to hold at arm's length through a long fight. Aether essence finishes it, or an aether orb if you have the shards.", de: "Mithril und Binder, leicht genug für einen langen Kampf. Aetheressenz vollendet ihn, oder eine Aether-Kugel, wenn die Splitter reichen." },
  "enchanted_runite_focus": { en: "Runite bound with binder, and the blue sheen of the bar stays in the blank. Aether essence makes a runite focus of it, void shards and a sapphire a void focus.", de: "Runit mit Binder, der blaue Schimmer bleibt im Rohling. Aetheressenz macht ihn zum Runit-Fokus, Leerensplitter und ein Saphir zum Leeren-Fokus." },
  "enchanted_steel_focus": { en: "Steel forged with binder into a blank that holds cold well. Frost essence finishes it, and with enough frost shards it becomes a frost focus.", de: "Stahl, mit Binder zu einem Rohling geschmiedet, der Kälte gut hält. Frostessenz vollendet ihn, mit genug Frostsplittern wird ein Frost-Fokus daraus." },
  "enchanted_titanium_focus": { en: "Titanium and binder, almost weightless and cold to hold. Void essence finishes it, or void shards and a diamond for the godspark focus.", de: "Titan und Binder, fast schwerelos und kalt in der Hand. Leerenessenz vollendet ihn, oder Leerensplitter und ein Diamant zum Götzenfunken-Fokus." },
  "essence_divine": { en: "Gathered where the god fungus grows, a residue that is warm without ever having burned. The strongest runes and the last elixirs need it.", de: "Gesammelt, wo die Götterpilze wachsen: ein Rückstand, warm, ohne je gebrannt zu haben. Die stärksten Runen und die letzten Elixiere brauchen sie." },
  "fang_necklace": { en: "Three jagged fangs on a strip of cured leather. Nothing about it is subtle, which is why it works.", de: "Drei Reißzähne auf einem Streifen gegerbtem Leder. Nichts daran ist dezent, und genau darum wirkt es." },
  "fang_pendant": { en: "A dire wolf's fang on a cord, still faintly warm at the root. Every kill feeds it, and it feeds the wearer back.", de: "Der Reißzahn eines Schreckenswolfs an einer Schnur, an der Wurzel noch warm. Jeder Kill nährt ihn, und er nährt den Träger zurück." },
  "farmhand_sling": { en: "A leather sling from an empty farmyard, the kind the hands used on crows. The chickens have it now, and whatever it hits tends to drop something.", de: "Eine Lederschleuder vom leeren Hof, wie die Knechte sie gegen Krähen nahmen. Was sie trifft, lässt eher etwas fallen." },
  "feather": { en: "Shed by hens, vultures and rocs alike. Five fletch a batch of arrows, and a quiver takes a good many more.", de: "Von Hühnern, Geiern und Rocs gleichermaßen verloren. Fünf befiedern einen Satz Pfeile, ein Köcher verlangt deutlich mehr." },
  "felmagician_eye": { en: "A fel magician's eye, dried and set in goblin copper. It saw the Lent Flame once. Now it sees every kill, and pays a little ward for each.", de: "Das Auge eines Felmagiers in Goblinkupfer gefasst. Es sah einmal das Leihfeuer. Jetzt sieht es jeden Kill und zahlt dafür etwas Ward." },
  "field_cape": { en: "A field hand's cape, torn to ribbons on the pasture thorns and dragged off by the boars. Whoever wears it tends to find a little more on the ground.", de: "Umhang eines Feldknechts, von Dornen zerrissen und von Wildschweinen verschleppt. Wer ihn trägt, findet meist etwas mehr am Boden." },
  "fire_rune": { en: "Ember essence pressed into a shard that stays hot in the pouch. Ember robes, fire wands and the emberglass ring all start here.", de: "Glutessenz, zu einem Splitter gepresst, der im Beutel heiß bleibt. Glut-Roben, Feuer-Zauberstäbe und der Glutglas-Ring beginnen hier." },
  "flayers_hook": { en: "The hook of Gorehook the Flayer, a butcher's tool bent into a blade. It does not cut so much as open.", de: "Der Haken von Bluthaken dem Schinder, ein Fleischerwerkzeug zur Klinge gebogen. Er schneidet nicht so sehr, wie er öffnet." },
  "force_rune": { en: "Dim essence bound into a hard little shard, three from two measures. The first thing a runecrafter makes, and the core of every early staff.", de: "Trübessenz, zu einem harten kleinen Splitter gebunden, drei aus zwei Maß. Das Erste, was ein Runenkundiger macht, der Kern jedes frühen Stabs." },
  "forgeplate_greaves": { en: "Greaves from the Forge Abyss, still on the Forge Demon's anvil when it fell. Made to stand against things that loom.", de: "Beinschienen aus den Schmiedeabgründen, noch auf dem Amboss des Schmiededämons, als er fiel. Gemacht, um gegen Größeres zu stehen." },
  "frost_focus": { en: "Eight frost shards fused to a steel blank. The frost never spreads to the caster, which is more than the first pieces managed.", de: "Acht Frostsplitter, auf einen Stahlrohling geschmolzen. Der Frost greift nie auf den Zaubernden über, was die ersten Stücke nicht schafften." },
  "frost_rune": { en: "Frost essence bound until it stops melting. Iron revenants of the Slag Pit carry a few in their joints. Frost robes and the mithril staff are built around it.", de: "Frostessenz, gebunden, bis sie nicht mehr schmilzt. Die Eisenrevenants der Schlackengrube tragen ein paar in den Gelenken. Frost-Roben bauen darauf." },
  "frost_scepter": { en: "A short scepter with a frost shard bound to its head. The cold in it never settles, and neither does whatever it touches.", de: "Ein kurzes Zepter, am Kopf ein Frostsplitter gebunden. Die Kälte darin kommt nie zur Ruhe, und was es trifft, auch nicht." },
  "frost_shroud": { en: "Linen stiffened with frost essence, cold to the touch in any weather. It keeps the head clear, which is what a caster needs most.", de: "Leinen, mit Frostessenz versteift, bei jedem Wetter kalt. Es hält den Kopf klar, und das braucht ein Zaubernder am meisten." },
  "frostbone_scepter": { en: "A spine bone from the Crypt's ice mages, still rimed white. Whatever it slows, it bites harder.", de: "Ein Wirbelknochen der Eismagier aus der Krypta, noch weiß bereift. Was es verlangsamt, beißt es umso härter." },
  "frostcaverns_bow": { en: "Strung with frost hound sinew that never warmed through. Every arrow leaves the cold in the wound, and the cold slows what it holds.", de: "Mit Sehne vom Frosthund bespannt, die nie durchwärmte. Jeder Pfeil lässt die Kälte in der Wunde, und was die Kälte hält, wird langsam." },
  "frosthex_wand": { en: "A frost hexer's rod from the Frost Caverns. The cold it lays on does not lift when it should.", de: "Die Rute eines Eishexers aus den Frostkavernen. Die Kälte, die sie legt, weicht nicht, wenn sie sollte." },
  "frostplate_greaves": { en: "Greaves from the Frost Caverns, plate the hexers froze onto their own shins. The cold stayed. So did the nerve to face bigger things.", de: "Beinschienen aus den Frostkavernen, Platte, die die Eishexer an die eigenen Schienbeine froren. Die Kälte blieb. Der Mut gegen Größeres auch." },
  "frostvine": { en: "A vine that stays cold in the hand whatever the season. Boiled down with graywort, it thickens the draught and makes it hold.", de: "Eine Ranke, die in der Hand kalt bleibt, egal in welcher Jahreszeit. Mit Grauwurz eingekocht macht sie den Sud dick und haltbar." },
  "frostward_treads": { en: "Frost hound hide, cured with the cold left in. They never warm through, and after a kill the next one comes sooner.", de: "Frosthundhaut, gegerbt, die Kälte dringelassen. Sie werden nie warm, und nach einem Kill kommt der nächste schneller." },
  "fungus_god": { en: "A mushroom that gives off sparks when it is torn, found where the godsbreath grows. The god-harvest tonic and the two great elixirs need it.", de: "Ein Pilz, der Funken wirft, wenn man ihn zerreißt, gewachsen beim Götteratem. Das Götterernte-Tonikum und die großen Elixiere brauchen ihn." },
  "fungus_grave": { en: "A brown mushroom from the gravemoss patches, dry and leathery. Brewed with gravemoss, it clears poison or quickens the hands.", de: "Ein brauner Pilz aus den Grabmoosflecken, trocken und ledrig. Mit Grabmoos gebraut räumt er Gift aus oder macht die Hände schneller." },
  "fungus_pale": { en: "A white mushroom that grows where the bloodthistle does, pale as if it had given its colour to the thistle. Brewers and runecrafters both use it.", de: "Ein weißer Pilz, der wächst, wo die Blutdistel wächst, bleich, als hätte er ihr seine Farbe abgegeben. Brauer und Runenkundige brauchen ihn." },
  "fungus_soot": { en: "A squat black mushroom that leaves soot on the fingers. The first tonic a forager brews needs one, and so does the antidote.", de: "Ein gedrungener schwarzer Pilz, der Ruß an den Fingern lässt. Das erste Tonikum eines Sammlers braucht einen, und der Antigift-Trank auch." },
  "fungus_void": { en: "A mushroom that grows in the thin places, dark and cold to the touch. Brewed with nightbloom, it goes into the warding elixir.", de: "Ein Pilz, der an den dünnen Stellen wächst, dunkel und kalt im Griff. Mit Nachtblüte gebraut wandert er ins Schutz-Elixier." },
  "furnaceheart_core": { en: "The heart of Furnaceheart the Undying, still glowing after everything. It gives the most while the ward around it holds.", de: "Das Herz von Ofenherz dem Unsterblichen, nach allem noch glühend. Es gibt am meisten, solange der Ward darum hält." },
  "gallows_apple": { en: "A small sour apple from trees that grew where the gallows stood. Boiled down with water, two of them make two jars of preserve.", de: "Ein kleiner saurer Apfel von Bäumen, die wuchsen, wo der Galgen stand. Mit Wasser eingekocht geben zwei davon zwei Gläser Konfitüre." },
  "gallows_preserve": { en: "Gallows apples boiled down with water until the sourness turns. Two jars from a single pot, and it keeps through any winter.", de: "Galgenäpfel, mit Wasser eingekocht, bis die Säure umschlägt. Zwei Gläser aus einem Topf, und sie hält jeden Winter durch." },
  "garnet": { en: "Cut from the rough and set in copper or bronze. It is not much of a stone, but the first ring and the first amulet are made with it.", de: "Aus dem Rohstein geschliffen und in Kupfer oder Bronze gefasst. Kein großer Stein, aber der erste Ring und das erste Amulett entstehen damit." },
  "garnet_amulet": { en: "A garnet in a bronze setting, the first stone a jeweler is trusted with. It is red, it is small, and it is a start.", de: "Ein Granat in Bronze gefasst, der erste Stein, den man einem Juwelier anvertraut. Er ist rot, er ist klein, und er ist ein Anfang." },
  "garnet_ring": { en: "A garnet in copper, the first ring any jeweler makes. The setting goes green by autumn. The stone does not care.", de: "Ein Granat in Kupfer, der erste Ring, den ein Juwelier macht. Die Fassung läuft bis zum Herbst grün an. Dem Stein ist das gleich." },
  "gemstone_amulet": { en: "A cut gemstone in iron, faceted to catch the light. Nobody asks where it came from. The amulet does not say.", de: "Ein geschliffener Edelstein in Eisen, facettiert, um das Licht zu fangen. Niemand fragt, woher er stammt. Das Amulett sagt es nicht." },
  "gemstone_ring": { en: "A cut gemstone in iron. Worth a fair sum to anyone who does not ask, and it finds the gaps in armor for anyone who does.", de: "Ein geschliffener Edelstein in Eisen. Einiges wert für jeden, der nicht fragt, und er findet die Lücken in der Rüstung für jeden, der es tut." },
  "gnarled_staff": { en: "A knotted branch Mux sells to anyone who asks. He swears the tree was struck by lightning. The staff only ever makes fire.", de: "Ein knorriger Ast, den Mux jedem verkauft, der fragt. Er schwört, der Baum sei vom Blitz getroffen worden. Der Stab macht trotzdem nur Feuer." },
  "goblin_buckler": { en: "A goblin spearman's buckler, a cooking pot hammered flat and strapped to the arm. It works. It is a goblin's idea of working.", de: "Der Buckler eines Goblin-Speerträgers, ein plattgehämmerter Kochtopf am Arm. Er funktioniert. Auf Goblin-Art." },
  "goblin_cleaver": { en: "A Warband butcher's cleaver, notched and never cleaned. Whatever it cuts keeps bleeding, which the butcher called efficiency.", de: "Das Hackbeil eines Schlächters der Kriegsbande, schartig und nie gereinigt. Was es trifft, blutet weiter, was der Schlächter für sparsam hielt." },
  "goblin_ear": { en: "Cut from a goblin of the Borderlands as proof of the kill. Nobody in Emberhold pays for them any more, but the habit stuck.", de: "Einem Goblin der Grenzlande als Beweis abgeschnitten. In der Glutfeste zahlt keiner mehr dafür, aber die Gewohnheit blieb." },
  "goblin_shank": { en: "A nail, a rag and a goblin's patience. The first stab is the one they plan. The rest is improvising.", de: "Ein Nagel, ein Lumpen und Goblin-Geduld. Der erste Stich ist der geplante. Der Rest ist Improvisation." },
  "goblin_warkilt": { en: "A Warband butcher's kilt, iron scales sewn to a stolen apron. Built by something small to fight things bigger than it.", de: "Der Kilt eines Schlächters der Kriegsbande, Eisenschuppen auf eine gestohlene Schürze genäht. Gebaut von etwas Kleinem, um Größeres zu bekämpfen." },
  "god_focus": { en: "A titanium blank crowded with void shards around one diamond. A spark of the Idol sits in the stone and has not gone out.", de: "Ein Titanrohling, dicht mit Leerensplittern um einen Diamanten besetzt. Ein Funke des Götzen sitzt im Stein und ist nicht erloschen." },
  "godbloom": { en: "It grows on burned ground where the idols' cult once stood. Brewed, it heals more than any draught. Bound, it makes the runes of the Chronicle and the Gleaning.", de: "Wächst auf verbranntem Boden, wo der Götzenkult stand. Gebraut heilt sie mehr als jeder Trank, gebunden wird sie zur Rune der Chronik und der Nachlese." },
  "godbloom_infusion": { en: "Godbloom drawn in water with divine essence. It heals more than any draught the craft taught before it, and tastes faintly of burned ground.", de: "Götzenblüte mit Göttlicher Essenz in Wasser. Heilt mehr als jeder Trank, den die Kräuterkunde zuvor lehrte, und schmeckt leise nach verbranntem Boden." },
  "godbloom_seed": { en: "A seed found in the Gravewood on burned ground. The flower it grows is the last crop the plots will take, and the Chronicle's rune needs it.", de: "Ein Same vom verbrannten Boden des Gräberwalds. Die Blume daraus ist die letzte Ernte, die die Beete annehmen, und die Rune der Chronik braucht sie." },
  "godgem": { en: "Cut at the top of the craft and set in aetherium or godiron. Every reliquary and the greatest rings are built around one.", de: "Am oberen Ende des Handwerks geschliffen und in Aetherium oder Götzeneisen gefasst. Jedes Reliquiar und die größten Ringe sind darum gebaut." },
  "godgem_amulet": { en: "A godgem in aetherium, the last stone and the last metal on the ladder, set as if they had always belonged together. Armor is a suggestion to it.", de: "Ein Göttenstein in Aetherium, letzter Stein und letztes Metall der Leiter, als hätten sie immer zusammengehört. Rüstung ist ihm ein Vorschlag." },
  "godgem_ring": { en: "A godgem in aetherium, the last stone in the last metal. It sits on the hand as if it had been waiting there. Armor is a suggestion to it.", de: "Ein Göttenstein in Aetherium, der letzte Stein im letzten Metall. Er sitzt an der Hand, als hätte er gewartet. Rüstung ist ihm ein Vorschlag." },
  "godiron_arrow": { en: "A godiron arrow, the end of the ladder. Barbed, poisoned or lit, there is nothing above it, and nothing it will not go through.", de: "Ein Götzeneisen-Pfeil, das Ende der Leiter. Mit Widerhaken, Gift oder Feuer gibt es nichts darüber, und nichts, durch das er nicht geht." },
  "godiron_arrowheads": { en: "Heads of the idols' own metal, dark and warm, forty-five to the bar. The last arrowheads a smith will ever forge.", de: "Spitzen aus dem Metall der Götzen, dunkel und warm, fünfundvierzig je Barren. Die letzten Pfeilspitzen, die ein Schmied je schmiedet." },
  "godiron_axe": { en: "Godiron, the wreath-metal of the idols, set on an axe haft. It is not sentimental about what it cuts.", de: "Götzeneisen, das Kranzmetall der Bildnisse, auf einen Axtstiel gesetzt. Es ist nicht sentimental, was es zerteilt." },
  "godiron_bar": { en: "The wreath-metal of the idols, cast again in a mortal furnace. Dark, warm and heavier than it looks. The Idol Hall gives it up piece by piece.", de: "Das Kranzmetall der Götzen, in einem sterblichen Ofen neu gegossen. Dunkel, warm und schwerer, als er aussieht. Die Halle gibt ihn Stück für Stück her." },
  "godiron_battleaxe": { en: "The wreaths of the idols were cast from this. A battleaxe is a less dignified use for it, and a more honest one.", de: "Aus diesem Metall wurden die Kränze der Götzen gegossen. Eine Kampfaxt ist ein weniger würdiger Zweck dafür, und ein ehrlicherer." },
  "godiron_chainbody": { en: "Godiron drawn into rings, which the smiths say it likes least of all shapes. A hauberk of the idols' metal, and it holds the way the Hall held.", de: "Götzeneisen zu Ringen gezogen, was es laut den Schmieden am wenigsten mag. Ein Hemd aus dem Metall der Götzen, und es hält, wie die Halle hielt." },
  "godiron_dagger": { en: "Godiron, poured for the wreaths of the idols, drawn out to a knife's length. Small enough to hide. It does not hide.", de: "Götzeneisen, für die Kränze der Götzen gegossen, zu Messerlänge ausgezogen. Klein genug zum Verstecken. Es versteckt sich nicht." },
  "godiron_focus": { en: "An onyx set in a godiron blank, four measures of void bound into it. The metal was cast under the Stranger's eye. It still watches.", de: "Ein Onyx in einem Götzeneisen-Rohling, vier Maß Leere darin gebunden. Das Metall wurde unter den Augen des Fremden gegossen. Es schaut noch." },
  "godiron_fullhelm": { en: "Godiron closed over the whole head. It was poured for the idols' wreaths and now sits where a wreath would. It does not mind.", de: "Götzeneisen um den ganzen Kopf. Es wurde für die Kränze der Götzen gegossen und sitzt jetzt, wo ein Kranz säße. Es stört sich nicht daran." },
  "godiron_gauntlets": { en: "Godiron over the hands. The idols' metal has never been asked to make a fist before. It is learning.", de: "Götzeneisen über den Händen. Das Metall der Götzen wurde noch nie gebeten, eine Faust zu machen. Es lernt." },
  "godiron_greataxe": { en: "Three bars of godiron on a haft shortened twice and still too long. The idols' metal was never meant to be lifted.", de: "Drei Barren Götzeneisen an einem Stiel, zweimal gekürzt und noch zu lang. Das Metall der Götzen war nie zum Heben gedacht." },
  "godiron_greatsword": { en: "Godiron drawn out to a greatsword's length, three bars and a week at the forge. The idols' metal does not like to be shaped. It likes to cut.", de: "Götzeneisen, zu Großschwertlänge gezogen, drei Barren und eine Woche Esse. Das Metall der Götzen lässt sich ungern formen. Schneiden mag es." },
  "godiron_kiteshield": { en: "Godiron in a teardrop. The idols' metal has stopped more prayers than blows. It is learning the blows.", de: "Götzeneisen in Tropfenform. Das Metall der Götzen hat mehr Gebete abgehalten als Schläge. Die Schläge lernt es gerade." },
  "godiron_longbow": { en: "Godwood, the last rung of the ladder, from trees in the shadow of the Idol Hall. The grain runs the wrong way, and the arrows do not care.", de: "Götzenholz, die letzte Sprosse der Leiter, aus dem Schatten der Götzenhalle. Die Maserung läuft falsch herum, und den Pfeilen ist es gleich." },
  "godiron_mace": { en: "Godiron, the idols' metal, cast into something that breaks armor. Fitting, for a metal that watched its masters shattered.", de: "Götzeneisen, in etwas gegossen, das Rüstung bricht. Passend für ein Metall, das zusah, wie seine Herren zerschlagen wurden." },
  "godiron_maul": { en: "Three bars of godiron on a pole. The wreath-metal of the idols, used to flatten whatever still stands between you and the Hall.", de: "Drei Barren Götzeneisen an einer Stange. Das Kranzmetall der Götzen, gebraucht, um plattzuschlagen, was noch zwischen dir und der Halle steht." },
  "godiron_medhelm": { en: "A godiron cap, open at the face. The idols never showed their faces either.", de: "Eine Götzeneisenkappe, am Gesicht offen. Die Götzen zeigten ihr Gesicht auch nie." },
  "godiron_ore": { en: "The ore the idols' wreaths were cast from, dark and faintly warm. The husks of the Idol Hall still shed it when they break.", de: "Das Erz, aus dem die Kränze der Götzen gegossen wurden, dunkel und leise warm. Die Hülsen der Götzenhalle geben es her, wenn sie zerbrechen." },
  "godiron_platebody": { en: "Six bars of godiron over the chest, more than any other piece takes. The idols' metal, shaped to keep a heart in. It has kept worse things in.", de: "Sechs Barren Götzeneisen über der Brust, mehr als jedes andere Stück. Geformt, ein Herz zu bewahren. Es hat Schlimmeres bewahrt." },
  "godiron_platelegs": { en: "Three bars of godiron from hip to ankle. The idols stood for ages without stirring. The greaves have learned to walk.", de: "Drei Barren Götzeneisen von der Hüfte bis zum Knöchel. Die Götzen standen Zeitalter lang, ohne sich zu rühren. Die Schienen haben gehen gelernt." },
  "godiron_sabatons": { en: "Godiron over the boots. The idols never walked anywhere. Their metal is finding out what that is like.", de: "Götzeneisen über den Stiefeln. Die Götzen gingen nie irgendwohin. Ihr Metall erfährt gerade, wie das ist." },
  "godiron_scimitar": { en: "Godiron forced into a curve, longer at the forge than any straight blade. The idols' metal does not like to bend. It likes to come back round.", de: "Götzeneisen, in eine Kurve gezwungen, länger an der Esse als jede gerade Klinge. Das Metall der Götzen biegt sich ungern. Zurückkommen mag es." },
  "godiron_shortbow": { en: "Godwood bent short, the last wood on the ladder. The shots come faster the longer it goes, and it does not tire. Nothing from the Hall does.", de: "Götzenholz, kurz gebogen, das letzte Holz der Leiter. Die Schüsse werden schneller, und es wird nicht müde. Nichts aus der Halle wird das." },
  "godiron_spear": { en: "Godiron at the end of a long shaft, kept as far from the hand as a spear allows. Nobody likes holding the idols' metal.", de: "Götzeneisen am Ende eines langen Schafts, so weit von der Hand weg, wie ein Speer es erlaubt. Niemand hält das Metall der Götzen gern." },
  "godiron_staff": { en: "Godiron, the metal the idols' wreaths were cast from, around a shard of void. Nothing it touches is far from its end.", de: "Götzeneisen, das Metall der Götzenkränze, um einen Splitter Leere. Nichts, was es berührt, ist weit vom Ende entfernt." },
  "godiron_sword": { en: "Godiron, straight and plain, the way the smiths of Emberhold insist a sword should be. The idols' metal does not object. It never did.", de: "Götzeneisen, gerade und schlicht, wie die Schmiede der Glutfeste ein Schwert haben wollen. Das Metall der Götzen widerspricht nicht. Hat es nie." },
  "godiron_towershield": { en: "A tower shield of godiron, cast from the same pour as the wreaths. A wall made of what the Hall was made of. It holds.", de: "Ein Turmschild aus Götzeneisen, aus demselben Guss wie die Kränze. Eine Mauer aus dem, woraus die Halle gemacht ist. Sie hält." },
  "godiron_wand": { en: "Fourteen fire shards sealed in godiron. The metal knows the furnaces where the wreaths were cast, and it has not cooled since.", de: "Vierzehn Feuersplitter in Götzeneisen versiegelt. Das Metall kennt die Öfen, in denen die Kränze gegossen wurden. Kalt wurde es seither nie." },
  "godsbreath_elixir": { en: "Three godsbreath, divine essence and a godspark fungus: the last brew the craft teaches. One minute in which every strike falls like a verdict.", de: "Dreimal Götteratem, Göttliche Essenz, ein Götterfunken-Pilz: der letzte Sud der Kräuterkunde. Eine Minute, in der jeder Schlag wie ein Urteil fällt." },
  "godsbreath_seed": { en: "A seed as light as breath, found where the godsbreath grows. It takes most of an afternoon in the plot and gives a full crop of the herb.", de: "Ein Same, leicht wie ein Atemzug, gefunden, wo der Götteratem wächst. Im Beet braucht er einen guten Nachmittag und gibt eine volle Ernte." },
  "godspark_staff": { en: "Twelve void shards and an onyx around a core of godiron. A spark of the Idol lives in it, and it does not care whom it burns.", de: "Zwölf Leerensplitter und ein Onyx um einen Kern aus Götzeneisen. Ein Funke des Götzen wohnt darin, und ihm ist gleich, wen er verbrennt." },
  "godwood_log": { en: "The last wood on the ladder, and the name is no accident. Dense, dark and faintly warm, it goes into the finest bows and the godiron quiver.", de: "Das letzte Holz der Leiter, und der Name ist kein Zufall. Dicht, dunkel und leise warm, geht es in die besten Bögen und den Götzeneisen-Köcher." },
  "gorehorn_cleaver": { en: "A horn of the Maddened Bull, split and ground to an edge. It has gored before. The habit goes with it.", de: "Ein Horn des Rasenden Bullen, gespalten und zur Schneide geschliffen. Es hat schon aufgespießt. Die Gewohnheit kommt mit." },
  "grave_lily": { en: "A pale lily from the Gravewood that opens only over the buried. With divine essence it makes the elixir that quickens the hand.", de: "Eine bleiche Lilie aus dem Gräberwald, offen nur über Begrabenen. Mit Göttlicher Essenz gibt sie das Elixier, das die Hand schnell macht." },
  "grave_warden_band": { en: "The Grave Warden Sigil set in steel. The Order sealed the Crypt with this mark. Whoever wears it carries a little of the Order's weight.", de: "Das Grabwächter-Siegel in Stahl gefasst. Mit diesem Zeichen versiegelte der Orden die Krypta. Wer es trägt, trägt etwas vom Gewicht des Ordens." },
  "grave_warden_sigil": { en: "The Order's own seal, recovered from the depths it was meant to keep shut. Set in steel, it becomes a circlet the dead still answer to.", de: "Das Siegel des Ordens, aus der Tiefe geborgen, die es verschließen sollte. In Stahl gefasst wird ein Reif daraus, dem die Toten noch gehorchen." },
  "gravemoss_seed": { en: "A spore clump found among the grave fungus. Sown in a plot, it grows gravemoss without the walk to the graves.", de: "Ein Sporenklumpen, zwischen den Grabpilzen gefunden. Ins Beet gesät wächst Grabmoos daraus, ohne den Weg zu den Gräbern." },
  "gravensap": { en: "Resin bled from the trees that grow over old graves, dark and slow to set. Worked into oil, it becomes a salve that thickens the skin.", de: "Harz aus den Bäumen über alten Gräbern, dunkel und langsam im Festwerden. In Öl gearbeitet wird eine Salbe daraus, die die Haut dicker macht." },
  "gravesteel_bar": { en: "Gravesteel, the Order's metal, smelted from its ore with a single coal. Blades and plate of it are forged over crude bone, as the Wardens did.", de: "Das Metall des Ordens, mit einer einzigen Kohle geschmolzen. Klingen und Platten daraus schmiedet man, wie die Grabwächter, über morschem Knochen." },
  "gravesteel_cuirass": { en: "A pyroclast's cuirass of gravesteel from the Crypt, the Order's work under the scorch. What strikes it is struck back harder.", de: "Der Grabstahl-Kürass eines Pyroklasten aus der Krypta, die Arbeit des Ordens unter dem Brandschwarz. Was ihn trifft, wird härter zurückgetroffen." },
  "gravesteel_ore": { en: "Dark ore from the veins the Grave Wardens once worked. It takes coal to smelt, and the bar keeps the colour of the grave.", de: "Dunkles Erz aus den Adern, die der Orden der Grabwächter einst abbaute. Es braucht Kohle, und der Barren behält die Farbe des Grabes." },
  "gravetato": { en: "A potato with grey skin and white flesh, named for the ground it likes. It goes into the marshroot chowder and little else.", de: "Grau außen, weiß innen, benannt nach dem Boden, den sie mag. Sie wandert in den Sumpfwurzel-Eintopf und sonst kaum irgendwohin." },
  "gravetato_seed": { en: "A shrivelled eye of a seed potato, found while pulling marshroot. It grows in soil that has already buried something.", de: "Ein verschrumpeltes Auge einer Saatkartoffel, beim Sumpfwurzelstechen gefunden. Es wächst in Erde, die schon etwas begraben hat." },
  "gravetread_sabatons": { en: "A skeleton spearman's sabatons from the Crypt, the Order's work under the grave dirt. The dead do not rest between fights. Neither do these.", de: "Schuhe eines Skelett-Speerträgers aus der Krypta, Ordensarbeit unter Graberde. Die Toten rasten nicht zwischen Kämpfen. Die Schuhe auch nicht." },
  "gravewarden_greatshield": { en: "A Grave Warden's shield from the Crypt, gravesteel over bone, the Order's sigil still on the face. Built to keep the dead in. It keeps them off as well.", de: "Schild der Grabwächter, Grabstahl über Knochen, das Siegel des Ordens noch zu sehen. Gebaut, um die Toten drinnen zu halten. Draußen geht auch." },
  "graywort_seed": { en: "A grey little seed, sold for a few coins or picked out of the Ashfields. Plant it, and in a short while the first weed worth having comes up.", de: "Ein graues Samenkorn, für ein paar Münzen verkauft oder aus den Aschfeldern gelesen. Gepflanzt kommt bald das erste Kraut hoch, das sich lohnt." },
  "greater_healing_potion": { en: "Graywort boiled down with frostvine until it thickens. Cold going down, and it keeps mending for a few breaths after.", de: "Grauwurz, mit Frostranke eingekocht, bis der Sud dick wird. Kalt beim Schlucken, und er heilt noch ein paar Atemzüge lang weiter." },
  "greytooth_mantle": { en: "The pelt of Greytooth the Famished, who hunted the Wildwood until it was all teeth. It is never full. A little of every wound it deals comes back to the one who wears it.", de: "Das Fell von Grauzahn dem Ausgehungerten, der den Wildwald jagte, bis nur Zähne blieben. Es wird nie satt. Ein wenig jeder Wunde, die es schlägt, kommt zu seinem Träger zurück." },
  "grilled_boar_loin": { en: "Razorback loin, grilled with the fat on. The boar fought back, and the meat tastes like it.", de: "Klingenrücken-Lende, mit dem Fett gegrillt. Das Schwein hat sich gewehrt, und so schmeckt das Fleisch auch." },
  "grimwheat": { en: "Short, hard grain that grows where wheat refuses to. Porridge and honey cake are made from it, and nobody in Emberhold complains.", de: "Kurzes, hartes Korn, das wächst, wo Weizen sich weigert. Brei und Honigkuchen entstehen daraus, und keiner in der Glutfeste beschwert sich." },
  "grimwheat_porridge": { en: "Grimwheat boiled in water until it holds a spoon. Grey, heavy and honest. The Reach eats what grows.", de: "Grimmkorn, in Wasser gekocht, bis der Löffel steht. Grau, schwer und ehrlich. Das Reach isst, was wächst." },
  "grimwood_log": { en: "Dark, close-grained wood that shrugs off damp. Carvers make shields and fishing rods from it rather than bows.", de: "Dunkles, engmaseriges Holz, dem Nässe nichts anhat. Schnitzer machen Schilde und Angeln daraus, keine Bögen." },
  "grimwood_rod": { en: "Grimwood does not warp in river damp, which is all a rod needs to be. Carved for anyone the ash rod has grown too slow for.", de: "Düsterholz verzieht sich nicht in der Flussfeuchte, und mehr muss eine Angel nicht können. Für alle, denen die Esche zu langsam wurde." },
  "grimwood_shield": { en: "Grimwood planks, dark and tight-grained, bound with sinew. It smells of the stands it came from, which is to say of nothing good.", de: "Düsterholzbretter, dunkel und engmaserig, mit Sehne gebunden. Riecht nach den Wäldern, aus denen es stammt, also nach nichts Gutem." },
  "hardened_leather": { en: "Two scarred hides boiled and beaten into one stiff sheet. It turns a knife where cured leather would only slow it.", de: "Zwei Narbenleder, gekocht und zu einer steifen Platte geschlagen. Es wehrt ein Messer ab, wo gegerbtes Leder es nur bremsen würde." },
  "hardened_leather_body": { en: "Leather boiled hard and shaped into a cuirass. It knocks when you tap it, and arrows knock off it the same way.", de: "Leder hart gekocht und zu einem Kürass geformt. Es klopft, wenn man dagegen klopft, und Pfeile klopfen genauso ab." },
  "hardened_leather_boots": { en: "Leather boiled hard and shaped to the foot. They knock on stone and keep the toes where they belong.", de: "Leder hart gekocht und an den Fuß geformt. Sie klopfen auf Stein und halten die Zehen, wo sie hingehören." },
  "hardened_leather_helm": { en: "Leather boiled in wax until it rings when tapped. It turns an arrow as well as thin iron and weighs half as much.", de: "Leder in Wachs gekocht, bis es beim Klopfen klingt. Lenkt einen Pfeil so gut ab wie dünnes Eisen und wiegt die Hälfte." },
  "hardened_leather_legs": { en: "Leather boiled hard and shaped to the shin. They knock against each other when you walk, and arrows knock off them.", de: "Leder hart gekocht und ans Schienbein geformt. Sie schlagen beim Gehen aneinander, und Pfeile schlagen davon ab." },
  "hardened_leather_vambraces": { en: "Leather boiled hard and shaped to the forearm. A blade skids off it with a sound like a knock on a door.", de: "Leder hart gekocht und an den Unterarm geformt. Eine Klinge rutscht daran ab, mit einem Laut wie ein Klopfen an der Tür." },
  "hardened_warcape": { en: "Thornlinen over a panel of hardened leather at the shoulders. Cut the way Jorun cut the Mark's banners, before there was no Mark to cut them for.", de: "Dornleinen über einem Stück gehärtetem Leder an den Schultern. Geschnitten, wie Jorun die Banner der Mark schnitt, bevor es keine Mark mehr gab." },
  "heartforged_pendant": { en: "The Heart of the Idol in godiron, two things that should never have met, set on one chain. It is warm. It should not be.", de: "Das Herz des Götzen in Götzeneisen, zwei Dinge, die sich nie hätten treffen sollen, an einer Kette. Es ist warm. Es sollte das nicht sein." },
  "hedgewitch_twig": { en: "A hazel switch the boars root up somewhere in the Pastures. Some hedge-witch cut it for a purpose. The purpose still works.", de: "Ein Haselzweig, den die Wildschweine irgendwo auf den Weiden ausbuddeln. Eine Heckenhexe schnitt ihn für einen Zweck. Der Zweck wirkt noch." },
  "herb_bloodthistle": { en: "A thistle with red veins that bleeds when it is cut. Healing draughts, the keen-eye and bloodrage tonics and two stews all call for it.", de: "Eine Distel mit roten Adern, die blutet, wenn man sie schneidet. Heiltränke, zwei Tonika und zwei Eintöpfe verlangen danach." },
  "herb_godsbreath": { en: "A silver herb that moves without wind. The feasts, the fourth-tier runes and the last elixirs all take it, and the plots grow it for those who can.", de: "Ein silbernes Kraut, das sich ohne Wind bewegt. Festmähler, die Runen der vierten Stufe und die letzten Elixiere verlangen es, und die Beete tragen es." },
  "herb_gravemoss": { en: "Black moss that grows on consecrated ground and nowhere else. Greater healing, antidotes and the tonics of the bulwark and the harvest all begin with it.", de: "Schwarzes Moos, das auf geweihtem Boden wächst und nirgends sonst. Großer Heiltrank, Antigift und die Tonika von Bollwerk und Ernte beginnen damit." },
  "herb_marshroot": { en: "A thick brown root pulled from the bog edge, bitter and dependable. Half the early draughts and tonics begin with two of them.", de: "Eine dicke braune Wurzel vom Moorrand, bitter und verlässlich. Die Hälfte der frühen Tränke und Tonika beginnt mit zwei davon." },
  "hide_leggings": { en: "Leggings of boar hide, bristles and all, dragged out of the pasture scrub. The longer the fight goes, the better they sit.", de: "Beinlinge aus Wildschweinhaut, mit Borsten, aus dem Gestrüpp der Weiden gezogen. Je länger der Kampf geht, desto besser sitzen sie." },
  "highland_key": { en: "A key cold from the Highland wind, kept from the days when the aerie was locked. The way up is open now and the key is a keepsake.", de: "Ein Schlüssel, kalt vom Hochlandwind, aus der Zeit, als der Horst verschlossen war. Der Weg hinauf ist offen, der Schlüssel ein Andenken." },
  "hoargrim_scepter": { en: "Hoargrim the Lightless carried this when the Crypt's cold was his alone. The frost on it has never thawed.", de: "Raugram der Lichtlose trug es, als die Kälte der Krypta noch ihm allein gehörte. Der Reif darauf ist nie getaut." },
  "hollowed_recurve": { en: "A bow hollowed from an idol husk's arm, light as a reed. The first arrow carries everything the husk had left.", de: "Ein Bogen, aus dem Arm einer Götzenhülse gehöhlt, leicht wie Schilf. Der erste Pfeil trägt alles, was die Hülse noch hatte." },
  "hollowelm_log": { en: "Elm that grows hollow from the heart out, so a staff of it is already half carved. Runecrafters bind frost and shade into it.", de: "Ulme, die vom Kern her hohl wächst, sodass ein Stab daraus schon halb geschnitzt ist. Runenkundige binden Frost und Schatten hinein." },
  "hollowelm_staff": { en: "Hollow elm around aetherium, frost packed into the hollow. The hollow whistles in the cold, and it brings the cold everywhere.", de: "Hohlulme um Aetherium, Frost in den Hohlraum gepackt. Der Hohlraum pfeift bei Kälte, und Kälte nimmt er überallhin mit." },
  "hollowelm_wand": { en: "Hollow elm over aetherium, twelve shade runes packed into the hollow. What it leaves in a wound keeps working after the wound is made.", de: "Hohlulme über Aetherium, zwölf Schattenrunen im Hohlraum. Was er in einer Wunde lässt, arbeitet weiter, wenn die Wunde längst geschlagen ist." },
  "hollowveil_locket": { en: "The locket of Hollowveil the Forgotten, who kept praying after nothing was listening. It opens on nothing. Every wound it deals pours a little back into the ward.", de: "Das Medaillon von Hohlschleier dem Vergessenen, der weiterbetete, als nichts mehr ankam. Es öffnet sich auf nichts. Jede Wunde, die es schlägt, gießt etwas in den Ward zurück." },
  "hungerfang_tusk": { en: "A tusk of Rustbristle the Famished, ground to a point. It ate everything it killed. Something of that habit remains.", de: "Ein Hauer von Rostborste dem Ausgehungerten, zur Spitze geschliffen. Er fraß alles, was er riss. Etwas von der Gewohnheit ist geblieben." },
  "hunting_knife": { en: "A skinning knife lost in the Wildwood and found again in a hare's warren. It knows the look of a marked quarry.", de: "Ein Abhäutemesser, im Wildwald verloren und im Bau eines Waldhasen wiedergefunden. Es kennt den Anblick einer markierten Beute." },
  "idol_aegis": { en: "The Last Idol's own shield, the face still marked where the Stranger set his hand. It has not been breached and does not expect to be. The wounds behind it close on their own.", de: "Der Schild des Letzten Götzen, gezeichnet, wo der Fremde die Hand anlegte. Nie durchbrochen, und er rechnet nicht damit. Die Wunden dahinter schließen sich von selbst." },
  "idol_coin": { en: "Struck with a face nobody prays to any more, lifted from the Idol Hoard. Appraised, it sometimes turns out to hold an onyx or a trace of aether.", de: "Geprägt mit einem Gesicht, zu dem keiner mehr betet, aus dem Götzenschatz gestohlen. Manchmal steckt ein Onyx darin oder eine Spur Aether." },
  "idol_crown": { en: "The crown the Idol Hall's wardens carried before the throne, godiron and void-crystal, heavier than it looks and heavier than it should be. The wounds under it close on their own.", de: "Die Krone der Götzenwächter vor dem Thron, Götzeneisen und Leerenkristall, schwerer, als sie sein sollte. Die Wunden darunter schließen sich von selbst." },
  "idol_heart": { en: "What beat inside the Last Idol. It still does, slowly, if you hold it long enough. A jeweller can set it in godiron and make an amulet of it.", de: "Was im Letzten Götzen schlug. Es schlägt noch, langsam, wenn man es lange genug hält. In Götzeneisen gefasst wird ein Amulett daraus." },
  "idol_shard": { en: "A splinter from a broken idol, cold and faintly humming. The hall is full of them, and the voidweave robes and the rune of judgement are made with them.", de: "Ein Splitter aus einem zerbrochenen Götzen, kalt und leise summend. Die Halle ist voll davon, und Leerengewebe und die Rune des Gerichts brauchen sie." },
  "idolbound_signet": { en: "A signet of godiron the Idol Hall's priests wore to show whose they were. The seal is the Stranger's mark. The wounds under it close on their own.", de: "Siegelring aus Götzeneisen, den die Götzenpriester trugen, um zu zeigen, wem sie gehörten. Das Siegel ist das Zeichen des Fremden. Die Wunden darunter schließen sich von selbst." },
  "idolhall_key": { en: "A key of dark iron, once the only way through the sealed hall. The hall opens to the Chronicle now, and this only weighs down the bank.", de: "Ein Schlüssel aus dunklem Eisen, einst der einzige Weg in die versiegelte Halle. Heute öffnet die Chronik die Halle, und er beschwert nur die Bank." },
  "idolpriest_censer": { en: "A censer swung by the priests of the Idol Hall, its coals never cold. The smoke was meant for prayers. None of them arrived.", de: "Ein Räuchergefäß der Priester der Götzenhalle, die Kohlen darin nie kalt. Der Rauch war für Gebete gedacht. Angekommen ist keines." },
  "idolstep_sabatons": { en: "Sabatons from the Idol Hall, godiron shaped for feet that were never meant to move. The husks and the siege idols wore them to the throne. The wounds above them close on their own.", de: "Schuhe aus der Götzenhalle, Götzeneisen für Füße, die sich nie bewegen sollten. Hülsen und Belagerungsgötzen trugen sie zum Thron. Die Wunden darüber schließen sich von selbst." },
  "imp_horn": { en: "A stubby horn from the Imp of the Pastures, still warm a day later. It has no use anyone has found, and the Imp has more.", de: "Ein stumpfes Horn vom Imp der Weiden, einen Tag später noch warm. Niemand hat eine Verwendung dafür gefunden, und der Imp hat mehr davon." },
  "impbone_wand": { en: "A horn-bone from Embergrin the Unbidden, the imp that should never have reached the Pastures. It is still warm. It will stay warm.", de: "Ein Hornknochen von Glutgrinser dem Ungebetenen, dem Imp, der die Weiden nie hätte erreichen dürfen. Er ist noch warm. Er bleibt es." },
  "iron_arrow": { en: "An iron-headed arrow, the kind the Borderlands archers shoot back at you. Reliable, cheap and easy to lose.", de: "Ein Pfeil mit Eisenspitze, wie ihn die Bogenschützen der Grenzlande zurückschießen. Verlässlich, billig und leicht zu verlieren." },
  "iron_arrowheads": { en: "Plain iron heads, forty-five from one bar. They rust in the quiver if the archer is careless and bite all the same.", de: "Schlichte Eisenspitzen, fünfundvierzig aus einem Barren. Sie rosten im Köcher, wenn der Schütze nachlässig ist, und beißen trotzdem." },
  "iron_axe": { en: "Plain iron, broad-bitted, the kind every woodcutter and half the Reach's soldiers once carried.", de: "Schlichtes Eisen mit breitem Blatt, wie es jeder Holzfäller und das halbe Heer des Reachs einst trug." },
  "iron_battleaxe": { en: "The Mark issued these by the cartload. The goblins inherited the carts.", de: "Die Mark gab sie karrenweise aus. Die Karren haben die Goblins geerbt." },
  "iron_chainbody": { en: "Iron rings, thousands of them, each riveted shut. It weighs on the shoulders and it stops a cut dead.", de: "Eisenringe, Tausende, jeder vernietet. Es lastet auf den Schultern und bringt einen Hieb zum Stehen." },
  "iron_dagger": { en: "Iron, narrow, with a fuller to keep it light. Finds the gap in a guard the way water finds a crack.", de: "Eisen, schmal, mit einer Hohlkehle, damit er leicht bleibt. Findet die Lücke in der Deckung wie Wasser den Riss." },
  "iron_focus": { en: "Iron holds the essence the way it holds the cold. Plain, heavy, and it does not let go.", de: "Eisen hält die Essenz, wie es die Kälte hält. Schlicht, schwer, und es lässt nicht los." },
  "iron_fullhelm": { en: "Iron closed over the whole head, with a hinged visor that squeals until oiled. The Mark issued these to its wall-guards.", de: "Eisen um den ganzen Kopf, mit einem Klappvisier, das quietscht, bis es geölt ist. Die Mark gab sie ihren Wallwachen." },
  "iron_gauntlets": { en: "Iron over the knuckles and the back of the hand. The Mark's soldiers used them to punch as much as to parry.", de: "Eisen über Knöcheln und Handrücken. Die Soldaten der Mark schlugen damit so oft zu, wie sie parierten." },
  "iron_greataxe": { en: "The Mark's wall-breakers carried these. The walls are gone. The axe still works.", de: "Die Wallbrecher der Mark trugen sie. Die Wälle sind weg. Die Axt tut es noch." },
  "iron_greatsword": { en: "Iron, long and plain, the greatsword of the Mark's line infantry. Balanced so the point comes back up on its own.", de: "Eisen, lang und schlicht, das Großschwert der Linieninfanterie der Mark. So ausgewogen, dass die Spitze von selbst hochkommt." },
  "iron_kiteshield": { en: "Iron over wood, rimmed and riveted. Plain, dependable, and it takes a blow the way a wall takes rain.", de: "Eisen über Holz, gefasst und genietet. Schlicht, verlässlich, und er nimmt einen Schlag, wie eine Mauer den Regen nimmt." },
  "iron_longbow": { en: "Oak, slow to season and slower to tire. Heavier in the hand than birch, and it does not care how long you hold the draw.", de: "Eiche, langsam abgelagert und noch langsamer müde. Schwerer in der Hand als Birke, und es ist ihr gleich, wie lange du den Zug hältst." },
  "iron_mace": { en: "Iron, flanged, the Mark's answer to armor it could not cut. The answer still holds.", de: "Eisen, mit Flanschen, die Antwort der Mark auf Rüstung, die sie nicht durchschneiden konnte. Die Antwort gilt noch." },
  "iron_maul": { en: "Iron, two-handed, slow enough to count between swings. The Mark used these on gates. Goblins are easier than gates.", de: "Eisen, zweihändig, langsam genug, um zwischen den Schlägen zu zählen. Die Mark setzte sie an Toren ein. Goblins sind leichter als Tore." },
  "iron_medhelm": { en: "An iron cap with a nasal bar. Plain, cheap, and it has turned more blades than any of the fancier ones.", de: "Eine Eisenkappe mit Nasenschutz. Schlicht, billig, und sie hat mehr Klingen abgelenkt als jeder prächtigere Helm." },
  "iron_ore": { en: "Rust-brown and heavy, the ore the Reach runs on. Smelted plain it gives iron, smelted with coal it gives steel.", de: "Rostbraun und schwer, das Erz, mit dem das Reach arbeitet. Allein geschmolzen gibt es Eisen, mit Kohle gibt es Stahl." },
  "iron_pickaxe": { en: "Two bars of iron and a morning at the anvil. The first pickaxe that outlasts the vein it is swung at.", de: "Zwei Eisenbarren und ein Vormittag am Amboss. Die erste Spitzhacke, die länger hält als die Ader, in die sie schlägt." },
  "iron_platebody": { en: "An iron breastplate, plain and heavy, the kind the Mark hung on its line infantry by the hundred. It outlived the line.", de: "Ein Eisen-Brustpanzer, schlicht und schwer, wie die Mark ihn zu Hunderten an ihre Linie hängte. Er hat die Linie überlebt." },
  "iron_platelegs": { en: "Iron greaves and cuisses, three bars' worth, strapped over wool. The Mark marched in these. The march is over. The iron is not.", de: "Eisenschienen und Diechlinge, drei Barren schwer, über Wolle geschnallt. Die Mark marschierte darin. Der Marsch ist vorbei. Das Eisen nicht." },
  "iron_sabatons": { en: "Iron over the boot, heavy enough that every step is a decision. The Mark marched in these. It did not march fast.", de: "Eisen über dem Stiefel, schwer genug, dass jeder Schritt eine Entscheidung ist. Die Mark marschierte darin. Nicht schnell." },
  "iron_scimitar": { en: "Iron, curved, the Rakhari way of making a sword. They brought the pattern through the Mark. The smiths kept it.", de: "Eisen, gebogen, nach Rakhari-Art geschmiedet. Sie brachten das Muster durch die Mark. Die Schmiede haben es behalten." },
  "iron_shortbow": { en: "Oak, cut short and strung heavy. Slow to tire, quick to loose, and it does not care about the weather.", de: "Eiche, kurz geschnitten und schwer bespannt. Wird langsam müde, schießt schnell, und das Wetter ist ihr gleich." },
  "iron_sickle": { en: "An iron crescent forged to be sharpened again and again. Herbs and reeds come away in one clean cut.", de: "Eine eiserne Sichel, geschmiedet, um immer wieder nachgeschärft zu werden. Kräuter und Schilf fallen mit einem sauberen Schnitt." },
  "iron_spear": { en: "Iron on a pole, the way the Mark armed its first line. Cheap, long, quick, and the goblins copied it exactly.", de: "Eisen an einer Stange, wie die Mark ihre erste Reihe bewaffnete. Billig, lang, schnell, und die Goblins haben es genau nachgebaut." },
  "iron_staff": { en: "Iron-bound and heavier than it looks. The shard at its head smolders in the dark like a coal that refuses to go out.", de: "Eisenbeschlagen und schwerer, als er aussieht. Der Splitter am Kopf glimmt im Dunkeln wie eine Kohle, die nicht ausgehen will." },
  "iron_sword": { en: "Iron, the sword the Mark issued by the thousand. Most of them are in goblin hands now. This one is not.", de: "Eisen, das Schwert, das die Mark zu Tausenden ausgab. Die meisten sind jetzt in Goblinhand. Dieses nicht." },
  "iron_towershield": { en: "A full door of iron. The Mark lined its walls with these. The walls are gone, and the doors are still stopping things.", de: "Eine volle Tür aus Eisen. Die Mark säumte ihre Wälle damit. Die Wälle sind weg, und die Türen halten noch immer etwas auf." },
  "iron_wand": { en: "Iron and a cold shard, plain as a nail. It does one thing, and it does it before the enemy has finished raising a hand.", de: "Eisen und ein kalter Splitter, schlicht wie ein Nagel. Er kann eines, und das, bevor der Gegner die Hand ganz oben hat." },
  "ironhide_body": { en: "Five studded hides pressed into one cuirass, nearly plate and nowhere near its weight. The studs are the only iron in it.", de: "Fünf genietete Häute zu einem Kürass gepresst, fast Platte und nicht annähernd so schwer. Die Nieten sind das einzige Eisen daran." },
  "ironhide_boots": { en: "Two studded hides pressed into treads nearly as hard as iron. The studs are the only metal in them. The foot is grateful.", de: "Zwei genietete Häute zu Stiefeln gepresst, fast so hart wie Eisen. Die Nieten sind das einzige Metall daran. Der Fuß ist dankbar." },
  "ironhide_helm": { en: "Studded leather doubled and riveted until it is nearly plate, then shaped into a coif that still lets you hear. Three hides go into one.", de: "Genietetes Leder, verdoppelt und vernietet, bis es fast Platte ist, dann zu einer Haube geformt, die noch hören lässt. Drei Häute für eine." },
  "ironhide_legs": { en: "Four studded hides pressed into greaves nearly as hard as iron and nowhere near as cold. The studs are the only metal in them.", de: "Vier genietete Häute zu Beinschienen gepresst, fast so hart wie Eisen und nicht halb so kalt. Die Nieten sind das einzige Metall daran." },
  "ironhide_vambraces": { en: "Two studded hides pressed into one vambrace, nearly as hard as iron and nowhere near as cold.", de: "Zwei genietete Häute zu einem Armschützer gepresst, fast so hart wie Eisen und nicht halb so kalt." },
  "ironreed_seed": { en: "A hard grey seed found among the grave fungus. It grows a reed stiff enough to scribe the runes of the second tier on.", de: "Ein harter grauer Same, zwischen den Grabpilzen gefunden. Daraus wächst ein Schilf, steif genug für die Runen der zweiten Stufe." },
  "ironvine": { en: "A vine that rusts rather than rots when it dies. Brewed with rimecap, it makes the bloodmend draught.", de: "Eine Ranke, die rostet statt zu verrotten, wenn sie stirbt. Mit Raureifpilz gebraut gibt sie den Blutheil-Trank." },
  "ironvine_seed": { en: "A seed with a shell like a nail head, found in the Cinderwood and the Frostmire. The vine it grows is tough as wire.", de: "Ein Same mit einer Schale wie ein Nagelkopf, gefunden im Glutwald und im Frostmoor. Die Ranke, die daraus wächst, ist zäh wie Draht." },
  "item_scrap": { en: "Bent nails, broken buckles, a hinge from a door that no longer exists. Four handfuls melt down to one copper bar.", de: "Krumme Nägel, zerbrochene Schnallen, ein Scharnier von einer Tür, die es nicht mehr gibt. Vier Handvoll schmelzen zu einem Kupferbarren." },
  "kraken_maw": { en: "A kraken's beak set on a whalebone grip. Whatever it does not finish on one body, it carries to the next.", de: "Ein Krakenschnabel auf Walknochengriff. Was er an einem Körper nicht aufbraucht, trägt er zum nächsten." },
  "krakenhide_cuirass": { en: "Kraken skin from the deep Shoals, rubbery and cold, cured into a cuirass. The first cut in it is the one that counts.", de: "Krakenhaut aus den tiefen Untiefen, gummiartig und kalt, zu einem Kürass gegerbt. Der erste Schnitt darin ist der, der zählt." },
  "last_idol_mantle": { en: "The Last Idol's mantle, godiron thread over a cloth that was never woven by hands. It sat on the throne for an age without a crease. The wounds under it close on their own.", de: "Der Mantel des Letzten Götzen, Götzeneisenfaden über Stoff, den keine Hand je webte. Ein Zeitalter auf dem Thron, ohne eine Falte. Die Wunden darunter schließen sich von selbst." },
  "leather_body": { en: "Three rawhides stitched into a jerkin that creaks when you breathe. It is warm, and it is better than a shirt.", de: "Drei Rohleder zu einem Wams genäht, das beim Atmen knarrt. Es ist warm, und es ist besser als ein Hemd." },
  "leather_boots": { en: "One rawhide, folded and stitched into boots that squeak. They keep the stones out. The water finds its own way in.", de: "Ein Rohleder, zu Stiefeln gefaltet und genäht, die quietschen. Sie halten die Steine draußen. Das Wasser findet seinen Weg." },
  "leather_cape": { en: "Nettlecloth with a strip of cured leather at the collar so it does not tear where the clasp pulls. It keeps the rain off the back.", de: "Nesselstoff mit einem Streifen gegerbtem Leder am Kragen, damit er nicht reißt, wo die Spange zieht. Hält den Regen vom Rücken." },
  "leather_helm": { en: "Rawhide stitched into a cap, stiff and smelling of the carcass. It keeps the rain off and little else.", de: "Rohleder zu einer Kappe genäht, steif und nach Kadaver riechend. Hält den Regen ab und wenig sonst." },
  "leather_legs": { en: "Two rawhides wrapped around the legs and laced up the side. Stiff for a week, then they take the shape of you.", de: "Zwei Rohleder um die Beine gewickelt und seitlich geschnürt. Eine Woche steif, dann nehmen sie deine Form an." },
  "leather_warcape": { en: "A heavier cut of nettlecloth, leather-backed, made to take a blow across the shoulders and not come apart.", de: "Ein schwererer Schnitt aus Nesselstoff, mit Leder unterlegt, gemacht, einen Schlag über die Schultern zu nehmen, ohne aufzugehen." },
  "litany_wand": { en: "A prayer eater's rod from the Idol Hall. Every fifth word of the litany was never meant for a god.", de: "Die Rute eines Gebetsfressers aus der Götzenhalle. Jedes fünfte Wort der Litanei war nie für einen Gott bestimmt." },
  "magic_binder": { en: "A grey paste sold by the jar. Smeared on a bar before it goes into the forge, it makes the metal hold a spell instead of shrugging it off.", de: "Eine graue Paste, nach Tiegeln verkauft. Vor dem Ofen auf den Barren gestrichen, lässt sie das Metall einen Zauber halten statt abschütteln." },
  "mandrake_root": { en: "A forked root that looks a little too much like a person. Steeped in water, it makes a tincture that heals well.", de: "Eine gegabelte Wurzel, die einem Menschen ein wenig zu ähnlich sieht. In Wasser gezogen gibt sie eine Tinktur, die gut heilt." },
  "mandrake_seed": { en: "A pale seed found among the pale fungus. Mandrake grows from it, root first, and the root is what the tincture wants.", de: "Ein bleicher Same, zwischen den Bleichpilzen gefunden. Alraune wächst daraus, die Wurzel zuerst, und die Wurzel ist es, was die Tinktur will." },
  "mandrake_tincture": { en: "Mandrake root, bruised and steeped. It heals well, and is said to scream a little when the stopper comes out.", de: "Alraunenwurzel, zerstoßen und gezogen. Heilt gut, und angeblich schreit sie ein wenig, wenn der Stöpsel herauskommt." },
  "mariner_cloak": { en: "A sailor's oilcloak, brought back by the tide with the name still sewn in the collar. After a kill, the next one comes sooner.", de: "Ölmantel eines Seemanns, von der Flut zurückgebracht, der Name noch im Kragen. Nach einem Kill geht es schneller weiter." },
  "marrow_cap": { en: "The skull of a hollow marrow from the Plague Chambers, worn as a cap. Something in it is still hungry, and each kill feeds it a little.", de: "Der Schädel eines Hohlen Marks aus den Pestkammern, als Kappe getragen. Etwas darin hat noch Hunger, und jeder Kill stillt ihn ein wenig." },
  "marrowcleaver": { en: "The cleaver of Marrowcleave the Starving, who split bone to get at what was inside. It finishes what is already on its knees.", de: "Das Beil von Markspalter dem Darbenden, der Knochen spaltete, um an das Innere zu kommen. Es beendet, was schon auf den Knien ist." },
  "marshroot_chowder": { en: "Perch, hen and gravetato in a marshroot broth, four bowls to a pot. It settles in the stomach and keeps a body standing a little longer.", de: "Barsch, Huhn und Grabkartoffel in Sumpfwurzelbrühe, vier Schalen aus einem Topf. Legt sich in den Magen und hält den Leib länger aufrecht." },
  "marshroot_seed": { en: "Seed for the marshroot, picked up among the sootcaps. Sown in a plot, it spares the walk to the marsh.", de: "Saat für die Sumpfwurzel, zwischen den Rußkappen aufgelesen. Ins Beet gesät erspart sie den Weg zum Sumpf." },
  "masters_mark": { en: "A cast mark like the ones the idols wear on the breast. It once opened the Sanctum. The way needs no key now, only the whole Chronicle.", de: "Ein gegossenes Zeichen, wie die Götzen es auf der Brust tragen. Es öffnete einst das Sanktum. Heute braucht der Weg keinen Schlüssel, nur die Chronik." },
  "minor_healing_potion": { en: "Graywort and a pinch of ashen dust, boiled thin. It works slowly, over a few breaths, which is still faster than no draught at all.", de: "Grauwurz und eine Prise Aschestaub, dünn gekocht. Wirkt langsam, über ein paar Atemzüge, und das ist immer noch schneller als gar kein Sud." },
  "mire_hexstaff": { en: "Crawler bone lashed to a bog-cured pole. The wounds it opens fester instead of closing.", de: "Kriecherknochen an eine moorgegerbte Stange gebunden. Wunden, die er reißt, eitern, statt sich zu schließen." },
  "mireclutch_fang": { en: "A fang of Mireclutch the Venomous, still weeping at the root. Its poison is not content with one body.", de: "Ein Fangzahn von Moorgriff dem Giftigen, an der Wurzel noch nässend. Sein Gift begnügt sich nicht mit einem Körper." },
  "mirrorglass_bow": { en: "A stave of basilisk glass from the Mirror Halls. The arrows carry a cold the Tower keeps for anything it does not want moving.", de: "Ein Stab aus Basiliskenglas aus den Spiegelhallen. Die Pfeile tragen eine Kälte, die der Turm für alles bereithält, was sich nicht rühren soll." },
  "mithril_arrow": { en: "Mithril-tipped and light in the hand. It flies flatter than steel and the quiver weighs half as much for a day's shooting.", de: "Mit Mithrilspitze und leicht in der Hand. Fliegt flacher als Stahl, und der Köcher wiegt für einen Tag Schießen halb so viel." },
  "mithril_arrowheads": { en: "Light mithril heads, forty-five to the bar, so thin they sing in flight. Fletchers past the fortieth level set them on the shaft.", de: "Leichte Mithrilspitzen, fünfundvierzig je Barren, so dünn, dass sie im Flug singen. Bogner ab Level 40 setzen sie auf den Schaft." },
  "mithril_axe": { en: "Mithril on a short haft, half the weight of iron. Felling with it feels like cheating, and the trees agree.", de: "Mithril an kurzem Stiel, halb so schwer wie Eisen. Damit zu fällen fühlt sich an wie Betrug, und die Bäume sehen das genauso." },
  "mithril_bar": { en: "A pale, light bar that takes a keener edge than iron and weighs half as much on the belt. The goblin warband hoards a few.", de: "Ein blasser, leichter Barren, der eine schärfere Schneide nimmt als Eisen und halb so viel wiegt. Die Goblin-Kriegsbande hortet ein paar davon." },
  "mithril_battleaxe": { en: "Mithril lets the head grow without the weight growing with it. The swing comes round faster than the enemy expects.", de: "Mithril lässt den Kopf wachsen, ohne dass das Gewicht mitwächst. Der Schwung kommt schneller herum, als der Gegner erwartet." },
  "mithril_chainbody": { en: "Mithril rings so light the whole hauberk folds into a pack. It stops an axe. The axe is surprised.", de: "Mithrilringe, so leicht, dass das ganze Hemd in einen Beutel passt. Es hält eine Axt auf. Die Axt ist überrascht." },
  "mithril_dagger": { en: "Mithril, light as a kitchen knife and nothing like one. The point rides in ahead of the hand.", de: "Mithril, leicht wie ein Küchenmesser und keines. Die Spitze ist vor der Hand da." },
  "mithril_focus": { en: "Mithril takes aether essence like cloth takes dye. Light, silver-grey, and awake the moment it is picked up.", de: "Mithril nimmt Aetheressenz an wie Stoff die Farbe. Leicht, silbergrau und wach, sobald man es aufnimmt." },
  "mithril_fullhelm": { en: "Mithril closed over the whole head and still lighter than an iron cap. The visor does not squeal. Nothing on it does.", de: "Mithril um den ganzen Kopf und immer noch leichter als eine Eisenkappe. Das Visier quietscht nicht. Nichts daran tut das." },
  "mithril_gauntlets": { en: "Mithril over the hands, light enough to thread a needle in. Hard enough that the needle would break first.", de: "Mithril über den Händen, leicht genug, um darin eine Nadel einzufädeln. Hart genug, dass die Nadel zuerst bräche." },
  "mithril_greataxe": { en: "A greataxe you can actually lift. Mithril took the weight out and left the width in.", de: "Eine Großaxt, die man tatsächlich heben kann. Mithril hat das Gewicht herausgenommen und die Breite dringelassen." },
  "mithril_greatsword": { en: "Mithril makes a greatsword that swings like a longsword and lands like a greatsword. Few arguments survive it.", de: "Mithril macht ein Großschwert, das wie ein Langschwert schwingt und wie ein Großschwert trifft. Wenige Einwände überleben das." },
  "mithril_kiteshield": { en: "Mithril over a thin wooden core, light as a hat. It blocks like something three times its weight, which it was built to replace.", de: "Mithril über dünnem Holzkern, leicht wie ein Hut. Blockt wie etwas mit dreifachem Gewicht, das es ersetzen sollte." },
  "mithril_longbow": { en: "Blightwood, pale and veined with rot that stopped short of the heartwood. The sick wood bends further than the healthy ever did.", de: "Pestholz, blass und von Fäulnis durchzogen, die vor dem Kernholz haltmachte. Das kranke Holz biegt sich weiter, als gesundes je konnte." },
  "mithril_mace": { en: "Mithril lets a mace be swung like a hammer and still get through a breastplate. The arm is grateful.", de: "Mithril lässt einen Streitkolben wie einen Hammer schwingen und trotzdem durch den Brustpanzer gehen. Der Arm ist dankbar." },
  "mithril_maul": { en: "A maul light enough to swing twice. The enemy rarely needs the second.", de: "Ein Hammer, leicht genug für zwei Schwünge. Der Gegner braucht den zweiten selten." },
  "mithril_medhelm": { en: "A mithril cap you forget you are wearing until something bounces off it.", de: "Eine Mithrilkappe, die man vergisst, bis etwas davon abprallt." },
  "mithril_ore": { en: "Pale ore with a faint silver gleam, lighter than it has any right to be. Two lumps and two coal make a single bar.", de: "Blasses Erz mit einem schwachen Silberglanz, leichter, als es sein dürfte. Zwei Brocken und zwei Kohle geben einen einzigen Barren." },
  "mithril_pickaxe": { en: "Light where iron is heavy, and the head keeps its edge deep into the rock. Miners who own one stop lending it.", de: "Leicht, wo Eisen schwer ist, und der Kopf hält seine Schneide tief im Fels. Wer eine hat, verleiht sie nicht mehr." },
  "mithril_platebody": { en: "A mithril breastplate, silver-grey and half the weight of steel. You can run in it. The smiths of Emberhold do not ask why you would want to.", de: "Ein Mithril-Brustpanzer, silbergrau und halb so schwer wie Stahl. Man kann darin rennen. Die Schmiede der Glutfeste fragen nicht, wozu." },
  "mithril_platelegs": { en: "Mithril greaves that weigh no more than leather. You can climb in them. The plate does not seem to mind.", de: "Mithril-Beinschienen, nicht schwerer als Leder. Man kann darin klettern. Die Platte scheint sich nicht daran zu stören." },
  "mithril_sabatons": { en: "Mithril over the boots, light enough to run in and hard enough that running is rarely needed.", de: "Mithril über den Stiefeln, leicht genug zum Rennen und hart genug, dass Rennen selten nötig ist." },
  "mithril_scimitar": { en: "Mithril in a curve so light it barely stops moving. The cuts come faster the longer the fight lasts.", de: "Mithril in einer Kurve, so leicht, dass es kaum stillsteht. Die Schnitte kommen schneller, je länger der Kampf dauert." },
  "mithril_shortbow": { en: "Blightwood bent short. The rot in the grain makes it bend where healthy wood would break.", de: "Pestholz, kurz gebogen. Die Fäulnis in der Maserung lässt es biegen, wo gesundes Holz bräche." },
  "mithril_spear": { en: "Mithril makes the spear quicker than the hand that holds it. Keep up.", de: "Mithril macht den Speer schneller als die Hand, die ihn hält. Halt mit." },
  "mithril_staff": { en: "Light in the hand, with seven frost shards set in a mithril ring. Breath fogs around its head on the warmest day.", de: "Leicht in der Hand, sieben Frostsplitter in einem Mithrilring. Selbst am wärmsten Tag beschlägt der Atem um seinen Kopf." },
  "mithril_sword": { en: "Mithril, straight and silver-grey. It weighs what a sword should and cuts like one that weighs twice as much.", de: "Mithril, gerade und silbergrau. Wiegt, was ein Schwert wiegen soll, und schneidet wie eines mit doppeltem Gewicht." },
  "mithril_towershield": { en: "A tower shield that can be lifted with one arm and kept there. Mithril took the weight out and left the wall in.", de: "Ein Turmschild, den man mit einem Arm heben und halten kann. Mithril hat das Gewicht herausgenommen und die Mauer dringelassen." },
  "mithril_wand": { en: "Mithril with ember essence in the shaft. Light enough to flick, and whatever it flicks at starts to smolder.", de: "Mithril mit Glutessenz im Schaft. Leicht genug zum Schnippen, und was er anschnippt, beginnt zu schwelen." },
  "moltengrip_gauntlets": { en: "Gauntlets from the Slag Pit, the fingers fused by heat that was alive. They grip hardest when the hand inside is nearly done.", de: "Stulpen aus der Schlackengrube, die Finger von einer Hitze verschmolzen, die lebte. Sie greifen am härtesten, wenn die Hand fast am Ende ist." },
  "morvane_warplate": { en: "The plate of Morvane the Reforged, beaten back into shape by the Slag Pit's heat more than once. Whatever hits it, it hits back.", de: "Die Platte von Morvane dem Neugeschmiedeten, von der Grubenhitze mehr als einmal in Form zurückgeschlagen. Was sie trifft, trifft sie zurück." },
  "mossweave_leggings": { en: "Moss golem's hide, woven through with root and still damp. Golems are built to meet things their own size. These leggings expect bigger.", de: "Moosgolem-Haut, mit Wurzeln durchwoben und noch feucht. Golems sind für Gegner ihrer Größe gebaut. Diese Beinlinge rechnen mit größeren." },
  "mourncedar_log": { en: "Cedar from the quiet slopes, red-hearted and resinous. Crafters carve rods from it, and runecrafters a sceptre for the storm.", de: "Zeder von den stillen Hängen, rotkernig und harzig. Handwerker schnitzen Angeln daraus, Runenkundige ein Zepter für den Sturm." },
  "mourncedar_rod": { en: "Mourncedar bends almost to the water before it breaks. A rod for the pools where the fish fight back.", de: "Trauerzeder biegt sich fast bis ins Wasser, bevor sie bricht. Eine Angel für die Becken, in denen die Fische sich wehren." },
  "mourncedar_scepter": { en: "Mourncedar around an aetherium core, storm shards set along the grain. The wood takes a charge the way tinder takes a spark.", de: "Trauerzeder um einen Kern aus Aetherium, Sturmsplitter in die Maserung gesetzt. Das Holz nimmt Ladung an wie Zunder den Funken." },
  "muckboots": { en: "Boots from an empty byre, caked to the knee with what byres are caked with. After every kill, the next one comes a little quicker.", de: "Stiefel aus einem leeren Stall, bis zum Knie verkrustet mit dem, womit Ställe verkrustet sind. Nach jedem Kill kommt der nächste etwas schneller." },
  "murkvein_bar": { en: "Smelted from a vein that should have been left shut. The bar drinks torchlight, and the only thing anyone forges from it is a longsword.", de: "Aus einer Ader geschmolzen, die man besser zugelassen hätte. Er schluckt Fackellicht, und das Einzige, was je daraus wird, ist ein Langschwert." },
  "necrosignet_ring": { en: "The Necromancer Lord's signet, the last Castellan's seal turned to the wrong use. What it marks does not mend.", de: "Der Siegelring des Nekromantenfürsten, das Siegel des letzten Kastellans zu falschem Zweck gewendet. Was er zeichnet, heilt nicht." },
  "nekro_reaperblade": { en: "The last Castellan's sword, turned against the dead he once kept. It drinks a little of what it cuts and leaves rot behind.", de: "Das Schwert des letzten Kastellans, gegen die Toten gewendet, die er hütete. Es trinkt von dem, was es schneidet, und lässt Fäulnis zurück." },
  "nightbloom_seed": { en: "A seed that glints a little in the dark, picked from the nightbloom itself. Sown, it grows the flower in an evening and a half.", de: "Ein Same, der im Dunkeln ein wenig glänzt, von der Nachtblüte selbst gelesen. Gesät wächst die Blume in anderthalb Abenden." },
  "nightshade": { en: "Glossy black berries on a dark stem. Pressed in clear oil, they make an extract that lets the body hold more life for a while.", de: "Glänzende schwarze Beeren an dunklem Stiel. In klarem Öl gepresst geben sie einen Extrakt, der den Leib eine Weile mehr Leben halten lässt." },
  "nightshade_extract": { en: "Nightshade pressed in clear oil. Poison in any other hand, but measured right it lets the body hold more life than it should.", de: "Nachtschatten, in klarem Öl gepresst. In jeder anderen Hand ein Gift, richtig dosiert lässt er den Leib mehr Leben halten, als ihm zusteht." },
  "nightshade_seed": { en: "A black seed from the Blightmarsh and the Cinderwood. What grows from it is poison in most hands and a tonic in a herbalist's.", de: "Ein schwarzer Same aus Seuchensumpf und Glutwald. Was daraus wächst, ist Gift in den meisten Händen und Tonikum in denen eines Kräuterkundigen." },
  "ninth_wardens_signet": { en: "The signet of the Ninth Warden, whom nobody counted. It knows the idols' constructs from the inside and strikes them there. The wounds under it close on their own.", de: "Das Siegel des Neunten Wächters, den niemand mitzählte. Es kennt die Konstrukte der Götzen von innen und trifft sie dort. Die Wunden darunter schließen sich von selbst." },
  "oldgrowth_plate": { en: "The bark of Oldgrowth the Unrooted, who walked the Blackthorn for longer than the trees have stood. It is still growing, and every kill feeds it.", de: "Die Rinde von Altwuchs dem Entwurzelten, der länger durch den Schwarzdorn ging, als die Bäume stehen. Sie wächst noch, und jeder Kill nährt sie." },
  "onyx": { en: "Cut black and set in runite. The rings and amulets made with it are the archer's and the thief's, and the godiron focus takes one as well.", de: "Schwarz geschliffen und in Runit gefasst. Die Ringe und Amulette daraus gehören Schützen und Dieben, und der Götzeneisen-Fokus nimmt auch einen." },
  "onyx_amulet": { en: "Onyx in runite, black on blue. It drinks the light the way the stone does, and whatever it is pointed at finds its armor less helpful.", de: "Onyx in Runit, Schwarz auf Blau. Es schluckt das Licht wie der Stein, und wogegen es gerichtet ist, dem hilft seine Rüstung weniger." },
  "onyx_ring": { en: "Onyx in runite, the swordsman's ring. Black on blue, and whatever it is turned against finds its armor less helpful.", de: "Onyx in Runit, der Ring der Schwertkämpfer. Schwarz auf Blau, und wogegen er gerichtet ist, dem hilft seine Rüstung weniger." },
  "padfoot_boots": { en: "Boots soled with forest hare pads, the quietest thing in the Wildwood. After a kill they are already moving.", de: "Stiefel, mit den Pfoten von Waldhasen besohlt, dem leisesten, was der Wildwald hat. Nach einem Kill sind sie schon unterwegs." },
  "palemourn_shroud": { en: "The shroud of Palemourn the Cliffwarden, who kept watch over the Gravecliff's dead and became one of them. Whatever it touches does not mend.", de: "Das Leichentuch von Bleichgram dem Klippenwächter, der über die Toten der Grabklippen wachte und einer von ihnen wurde. Was es berührt, heilt nicht." },
  "palereed_seed": { en: "A reed seed as light as ash, shaken loose while gathering sootcaps. The first runes are scribed on the reed it grows.", de: "Ein Schilfsamen, leicht wie Asche, beim Rußkappensammeln abgeschüttelt. Auf dem Schilf, das daraus wächst, werden die ersten Runen geritzt." },
  "panacea_elixir": { en: "Godsbreath and godspark fungus, drawn in water. The poison leaves, the body fills with borrowed vigour, and for a while nothing seems able to bring it down.", de: "Götteratem und Götterfunken-Pilz in Wasser gezogen. Das Gift geht, der Leib füllt sich mit geliehener Kraft, und eine Weile wirft ihn nichts um." },
  "paragon_key": { en: "The Last Idol held it, and the Judgement hands over another. It opens the Paragon Spire, and nothing else has ever opened it.", de: "Der Letzte Götze hielt ihn, und das Gericht gibt einen weiteren her. Er öffnet den Paragonturm, und nichts anderes hat ihn je geöffnet." },
  "pearl_of_the_deep": { en: "A pearl from the Deep Kraken's gullet, the size of a fist and cold as the water it came from. Each kill gives a little of the wearer back.", de: "Eine Perle aus dem Schlund der Tiefenkrake, faustgroß und kalt wie das Wasser, aus dem sie kam. Jeder Kill gibt dem Träger etwas zurück." },
  "pelt_mantle": { en: "A wild stag's pelt, hung from the shoulders with the head still on. Whatever hunts beside you takes it for a signal.", de: "Das Fell eines Wildhirschs, von den Schultern hängend, der Kopf noch daran. Was neben dir jagt, nimmt es als Zeichen." },
  "pigment_radiant": { en: "Pigment that gives off its own light, ground from radiant blooms. Every rune of the third and fourth tier is painted with it.", de: "Pigment, das eigenes Licht abgibt, aus Strahlblüten zerrieben. Jede Rune der dritten und vierten Stufe wird damit gemalt." },
  "pigment_umber": { en: "Brown pigment from umber pods and umberleaf, ground fine. Runecrafters paint the first runes with it.", de: "Braunes Pigment aus Umbra-Schoten und Umbrablatt, fein zerrieben. Runenkundige malen die ersten Runen damit." },
  "pigment_verdant": { en: "Green pigment from verdant blooms and verdantcaps. The runes of the hunt and the arcane, and most of the second tier, are painted with it.", de: "Grünes Pigment aus Grünblüten und Grünkappen. Die Runen der Jagd und des Arkanen und die meisten der zweiten Stufe werden damit gemalt." },
  "pigment_violet": { en: "Violet pigment from violet petals and violetbloom. Runecrafters paint precision, swiftness, evasion and the bulwark with it.", de: "Violettes Pigment aus Violetteblüten und Violettblüte. Runenkundige malen Präzision, Schnelle, Ausweichen und das Bollwerk damit." },
  "pitchfork_spear": { en: "A pitchfork from an empty byre, two tines snapped off and the third filed sharp. Made for hay, better against anything bigger than you.", de: "Eine Mistgabel aus einem leeren Stall, zwei Zinken abgebrochen, die dritte scharf gefeilt. Für Heu gemacht, besser gegen alles Größere." },
  "plaguebone_buckler": { en: "A shambling carcass's ribcage, pressed flat and strapped. Nothing that bleeds on it heals well afterward.", de: "Der Brustkorb einer Taumelnden Leiche, flachgedrückt und mit Riemen versehen. Was darauf blutet, heilt danach nicht gut." },
  "potion_antidote": { en: "Marshroot and a sootcap in water. It tastes of smoke and marsh and drives a poison out before it settles in.", de: "Sumpfwurzel und eine Rußkappe in Wasser. Schmeckt nach Rauch und Moor und treibt ein Gift aus, bevor es sich festsetzt." },
  "potion_greater_antidote": { en: "Gravemoss and grave fungus in water. Clears the poison and leaves the body sturdier for a while, as if the grave had lent it something.", de: "Grabmoos und Grab-Pilz in Wasser. Räumt das Gift aus und lässt den Leib eine Weile fester zurück, als hätte das Grab ihm etwas geliehen." },
  "potion_greater_heal": { en: "Gravemoss steeped in water until the draught turns black. What grows on the dead mends the living, and nobody asks why.", de: "Grabmoos, in Wasser gezogen, bis der Trank schwarz wird. Was auf den Toten wächst, heilt die Lebenden, und keiner fragt, warum." },
  "potion_heal": { en: "Bloodthistle boiled down to a red draught. It stings on the way down and mends on the way through.", de: "Blutdistel, zu einem roten Trank eingekocht. Brennt auf dem Weg hinunter und heilt auf dem Weg hindurch." },
  "potion_lesser_heal": { en: "Marshroot again, with a pinch of ash essence so it reaches deeper. Bitter, grey and quick.", de: "Wieder Sumpfwurzel, mit einer Prise Ascheessenz, damit sie tiefer reicht. Bitter, grau und schnell." },
  "potion_minor_heal": { en: "Two marshroots steeped in water. The first thing a herbalist learns to make, and it still closes a wound.", de: "Zwei Sumpfwurzeln, in Wasser gezogen. Das Erste, was ein Kräuterkundiger lernt, und es schließt noch immer eine Wunde." },
  "potion_potent_heal": { en: "Nightbloom petals steeped cold, so the draught keeps their faint light. It heals far more than its pale colour suggests.", de: "Nachtblütenblätter, kalt gezogen, damit der Trank ihr schwaches Leuchten behält. Heilt weit mehr, als die blasse Farbe vermuten lässt." },
  "pyre_staff": { en: "Carried by the Crypt's pyroclasts, who burn what the Necromancer Lord no longer needs. A clean hit goes up like dry kindling.", de: "Getragen von den Pyroklasten der Krypta, die verbrennen, was der Nekromantenfürst nicht mehr braucht. Ein sauberer Treffer geht hoch wie Reisig." },
  "pyrebound_vestment": { en: "The robe of Ossuar the Pyrebound, who burned in the Crypt and did not stop. Warm, and whatever burns or bleeds near it does so worse.", de: "Die Robe von Ossuar dem Glutgebundenen, der brannte und nicht aufhörte. Warm, und was in ihrer Nähe brennt oder blutet, tut es schlimmer." },
  "quietstep_boots": { en: "Vex the Throatfinder's boots, soled in felt and never once heard. Whoever wears them arrives before the fight does, and the first blow is the one that counts.", de: "Die Stiefel von Vex dem Kehlenfinder, in Filz besohlt und nie gehört. Wer sie trägt, ist vor dem Kampf da, und der erste Schlag zählt." },
  "radiantbloom_seed": { en: "A seed that shines faintly through the pouch, found among the godsbreath. The bloom it grows is crushed for radiant pigment.", de: "Ein Same, der schwach durch den Beutel scheint, beim Götteratem gefunden. Die Blüte daraus wird zu Strahlendem Pigment zerstoßen." },
  "ranger_cape": { en: "Linen dyed the grey-green of the Blackthorn, a leather yoke across the shoulders. It is quiet in the brush and dry by morning.", de: "Leinen, graugrün wie der Schwarzdorn gefärbt, ein Lederjoch über den Schultern. Leise im Gestrüpp und bis zum Morgen trocken." },
  "raw_abyssal_crawler": { en: "Dredged from the bottom, all legs and shell and bad temper. Braised, or the heart of the abyssal feast.", de: "Vom Grund geschleppt, nur Beine, Panzer und schlechte Laune. Geschmort, oder das Herzstück des Abgrund-Festmahls." },
  "raw_ashen_sturgeon": { en: "A sturgeon the length of a man, grey as the fields it is named for, speared in deep water. Smoked, it keeps for weeks.", de: "Ein Stör so lang wie ein Mann, grau wie die Felder, nach denen er heißt, in tiefem Wasser harpuniert. Geräuchert hält er wochenlang." },
  "raw_ashpike": { en: "A grey pike netted from ash-clouded water. It fights the net the whole way up and grills well for it.", de: "Ein grauer Hecht, aus aschtrübem Wasser gekeschert. Er wehrt sich den ganzen Weg nach oben und grillt umso besser." },
  "raw_beef": { en: "A cut from a Pastures cow or a maddened bull, or lifted from a goblin butcher who had the same idea. Seared, or stewed with bloodgrain.", de: "Von Weidenkuh oder rasendem Bullen, oder einem Goblin-Schlächter abgenommen, der dieselbe Idee hatte. Gebraten, oder mit Blutgetreide geschmort." },
  "raw_bloodfang_eel": { en: "An eel with teeth, trapped rather than hooked because it bites through line. Seared alone, or the fat for three good dishes.", de: "Ein Aal mit Zähnen, gefangen statt geangelt, weil er Schnüre durchbeißt. Allein angebraten, oder das Fett für drei gute Gerichte." },
  "raw_boar_loin": { en: "The loin of a razorback boar from the Pastures, dark and marbled. It grills in the time it takes to sharpen the knife.", de: "Die Lende eines Klingenrücken-Keilers von den Weiden, dunkel und marmoriert. Sie grillt, während man das Messer schärft." },
  "raw_bog_fowl": { en: "A marsh bird, plucked, with the smell of the Ashfields still on it. Dust vultures carry them half eaten, and the rest is yours.", de: "Ein Sumpfvogel, gerupft, mit dem Geruch der Aschfelder noch daran. Die Staubgeier tragen sie halb gefressen herum, und der Rest gehört dir." },
  "raw_chicken": { en: "A plucked Pastures hen, and now and then one turns up among the shed feathers. The first meat most settlers cook.", de: "Ein gerupftes Weidenhuhn, und ab und zu findet sich eines zwischen den gesammelten Federn. Das erste Fleisch, das die meisten Siedler braten." },
  "raw_cod": { en: "Cod from the cold water, netted by the dozen. The drowned of the reef carry them too, for reasons nobody wants explained.", de: "Kabeljau aus kaltem Wasser, dutzendweise gekeschert. Die Ertrunkenen des Riffs tragen ihn auch bei sich, aus Gründen, die keiner wissen will." },
  "raw_dirgefin": { en: "A fish that makes a low sound when it is pulled from the water, and keeps making it. Steamed gently, it stops.", de: "Ein Fisch, der einen tiefen Ton von sich gibt, wenn man ihn aus dem Wasser zieht, und damit nicht aufhört. Sanft gedünstet hört er auf." },
  "raw_duskfin_carp": { en: "A carp with fins the colour of evening. Steamed whole, or cooked down into the ranger's stew and the spellwarden bisque.", de: "Ein Karpfen mit Flossen in der Farbe des Abends. Im Ganzen gedämpft, oder im Jäger-Eintopf und in der Zauberwächter-Bisque verkocht." },
  "raw_ghostfin_pike": { en: "A pike with fins so pale they vanish under water. Roasted on its own, or two of them go into the bloodgrain stew.", de: "Ein Hecht mit Flossen so bleich, dass sie unter Wasser verschwinden. Allein geröstet, oder zwei davon wandern in den Blutgetreide-Eintopf." },
  "raw_hare_meat": { en: "The leg of a forest hare from the Wildwood, lean and dark. Roasted over coals, it is gone before it cools.", de: "Die Keule eines Waldhasen aus dem Wildwald, mager und dunkel. Über Kohlen geröstet ist sie weg, bevor sie abkühlt." },
  "raw_idolscale": { en: "The last fish the water gives up, scaled like the idols' wreaths and nearly as heavy. Only a consecration will cook it.", de: "Der letzte Fisch, den das Wasser hergibt, geschuppt wie die Kränze der Götzen und beinahe so schwer. Nur eine Weihe bringt ihn gar." },
  "raw_murk_perch": { en: "A bog perch, muddy-tasting and plentiful. Fried on its own or stewed into the marshroot chowder, four bowls at a time.", de: "Ein Moorbarsch, modrig im Geschmack und reichlich vorhanden. Allein gebraten oder in den Sumpfwurzel-Eintopf geschmort, vier Schalen auf einmal." },
  "raw_roc_drumstick": { en: "The leg of a young roc, as long as a man's arm. Highland hunters bring one home and the whole camp eats.", de: "Die Keule eines jungen Roc, so lang wie ein Männerarm. Hochlandjäger bringen eine heim, und das ganze Lager isst." },
  "raw_salmon": { en: "Salmon from the running water, silver and strong on the hook. The tide sirens of the coast hoard them, which is one more reason to fight them.", de: "Lachs aus fließendem Wasser, silbern und kräftig am Haken. Die Gezeitensirenen der Küste horten ihn, ein Grund mehr, sich mit ihnen anzulegen." },
  "raw_shadowcarp": { en: "A dark carp from the slow water, fat and sluggish on the line. Pan-fried, it is better than it looks.", de: "Ein dunkler Karpfen aus trägem Wasser, fett und schwerfällig an der Schnur. Gebraten ist er besser, als er aussieht." },
  "raw_shrimp": { en: "Small grey shrimp netted in the shallows, the first catch of anyone with a line. The mud crabs of the coast carry a few as well.", de: "Kleine graue Shrimps, in den Untiefen gekeschert, der erste Fang von jedem mit einer Schnur. Die Schlickkrabben der Küste tragen auch ein paar." },
  "raw_soulfish": { en: "It comes to the lure, not the bait, and it looks at you on the way up. Sanctified on its own, or the centre of the two great feasts.", de: "Er kommt auf den Köder, nicht aufs Futter, und sieht dich auf dem Weg nach oben an. Geläutert, oder die Mitte der zwei großen Festmähler." },
  "raw_trout": { en: "A river trout, speckled and quick. It is on the hook before the bait has settled, most days.", de: "Eine Flussforelle, gesprenkelt und flink. An den meisten Tagen hängt sie am Haken, bevor der Köder sich gesetzt hat." },
  "raw_voidray": { en: "A flat, dark ray speared in the deep pools where the veil is thin. Seared alone, or laid over ambergrain for the banquet.", de: "Ein flacher, dunkler Rochen aus den tiefen Becken, wo der Schleier dünn ist. Allein angebraten, oder über Bernsteingetreide fürs Bankett." },
  "raw_wolf_haunch": { en: "A haunch from a thorn wolf or a grey wolf, tough and bloody. Seared hard, it makes a steak that fights back a little.", de: "Eine Keule von Dornwolf oder Grauwolf, zäh und blutig. Scharf angebraten gibt sie ein Steak, das sich noch ein wenig wehrt." },
  "raw_wraithscale": { en: "A fish with scales like frost on glass, speared in water that is colder than it should be. Smoked, or the base of all three witherleek dishes.", de: "Ein Fisch mit Schuppen wie Reif auf Glas, harpuniert in Wasser, das zu kalt ist. Geräuchert, oder die Grundlage aller drei Welklauch-Gerichte." },
  "raw_wyvern_haunch": { en: "A wyvern's haunch, dark and dense, cut from the beasts of the Highlands. Charred on its own, and two of them go into every great feast.", de: "Die Keule eines Wyverns, dunkel und dicht, den Bestien des Hochlands abgeschnitten. Allein flambiert, und zwei davon gehen in jedes Festmahl." },
  "reed_iron": { en: "Reed with a grey stem that does not bend. Runecrafters scribe the second tier of runes on it, and the bulwark and the hunt from the first.", de: "Schilf mit grauem Halm, der sich nicht biegt. Runenkundige ritzen die zweite Runenstufe darauf, und vom ersten Rang das Bollwerk und die Jagd." },
  "reed_pale": { en: "Pale reed from the first plots, dried and split. Runecrafters bind the runes of keen, precision, swiftness, aegis and evasion to it.", de: "Bleiches Schilf aus den ersten Beeten, getrocknet und gespalten. Schärfe, Präzision, Schnelle, Ägide und Ausweichen werden als Runen darauf geritzt." },
  "reed_void": { en: "Black reed with a stem that is cold to hold. The third and fourth tier of runes are scribed on it, and nothing less will carry them.", de: "Schwarzes Schilf, kalt in der Hand. Die dritte und vierte Runenstufe werden darauf geritzt, und nichts Geringeres trägt sie." },
  "reefscale_helm": { en: "A helm scaled with reef shell, taken from a reef drowned who no longer needed it. The salt never dries, and kills under it close wounds.", de: "Ein Helm, mit Riffschale beschuppt, einem Riff-Ertrunkenen abgenommen. Das Salz trocknet nie, und Kills darunter schließen Wunden." },
  "revenant_elixir": { en: "Voidbloom and wraithcap, grown where the dead once walked. It pulls a body back from the edge, and something in the vial listens while it does.", de: "Leerenblüte und Wichtkappe, gewachsen, wo die Toten gingen. Es holt den Leib von der Kante zurück, und etwas im Fläschchen hört dabei zu." },
  "revenant_greatshield": { en: "The Iron Revenant's shield, forged by a smith who died in his armor and kept working. It finishes what is already falling against it.", de: "Schild des Eisenrevenants, von einem Schmied gemacht, der in seiner Rüstung starb und weiterarbeitete. Er beendet, was schon dagegen fällt." },
  "ridgetyrant_greaves": { en: "The greaves of Vessk the Ridgetyrant, wyvern scale over a lining that was never meant to come off. They hold hardest when their wearer is nearly spent.", de: "Die Beinschienen von Vessk dem Grattyrannen, Wyvernschuppe über einem Futter, das nie abgehen sollte. Sie halten am härtesten, wenn ihr Träger fast am Ende ist." },
  "rimebound_leggings": { en: "The leggings of Skalva the Rimebound, frozen to her and never thawed. The cold on them bites whatever is already slowed.", de: "Die Beinlinge von Skalva der Frostgebundenen, an ihr festgefroren und nie getaut. Die Kälte darauf beißt, was schon langsam ist." },
  "rimecap": { en: "A frost-white mushroom from the Frostmire, firm as ice until it thaws in the pot. With ironvine it makes the bloodmend draught.", de: "Ein reifweißer Pilz aus dem Frostmoor, fest wie Eis, bis er im Topf auftaut. Mit Eisenranke gibt er den Blutheil-Trank." },
  "risotto_starcap": { en: "Ambergrain stirred slow with a shaved starcap truffle. Rich enough that the body keeps mending long after the plate is empty.", de: "Bernsteingetreide, langsam gerührt, mit gehobelter Sternkappen-Trüffel. So gehaltvoll, dass der Leib noch lange heilt, wenn der Teller leer ist." },
  "rivetfist_gloves": { en: "A goblin spearman's gloves, the knuckles studded with rivets pulled from the Mark's old gates. They hit hardest when things look bad.", de: "Goblinhandschuhe, die Knöchel mit Nieten aus den alten Toren der Mark besetzt. Sie schlagen am härtesten, wenn es schlecht steht." },
  "roasted_bog_fowl": { en: "A marsh bird roasted on a spit. Stringy, a little smoky, and the first bird most settlers eat that is not a hen.", de: "Ein Sumpfvogel am Spieß geröstet. Faserig, leicht rauchig, und der erste Vogel, den die meisten essen, der kein Huhn ist." },
  "roasted_hare": { en: "A forest hare's leg roasted over coals. Lean meat from the Wildwood, gone in four bites.", de: "Eine Waldhasenkeule über Kohlen geröstet. Mageres Fleisch aus dem Wildwald, in vier Bissen weg." },
  "roc_drumstick_grilled": { en: "A roc's drumstick is the size of a child, and the grill takes the whole evening. Highland hunters share one between three.", de: "Eine Roc-Keule hat die Größe eines Kindes, und der Grill braucht den ganzen Abend. Hochlandjäger teilen sich eine zu dritt." },
  "rootling_club": { en: "A rootling's own limb, knotted and hard as stone. Each blow lands a little heavier than the last, like the forest closing in.", de: "Das Glied eines Wurzlings, knotig und hart wie Stein. Jeder Schlag landet etwas schwerer als der vorige, als rücke der Wald näher." },
  "rotfang_dagger": { en: "A rot rat's incisor on a bone grip, from the Plague Chambers. The sickness in it does not stay with the first one it bites.", de: "Der Nagezahn einer Seuchenratte auf Knochengriff, aus den Pestkammern. Die Seuche darin bleibt nicht beim Ersten, den sie beißt." },
  "rough_bloodstone": { en: "Dark stone with red veins, dug from its own seam near the gravesteel. The Order set it in their jewellery, and jewellers still do.", de: "Dunkler Stein mit roten Adern, gebrochen nahe dem Grabstahl. Der Orden fasste ihn in seinen Schmuck, und die Juweliere tun es noch." },
  "rough_diamond": { en: "A clouded white stone from the diamond seam, and the rarest find in half the mines of the Reach. Cut, it goes into mithril.", de: "Ein trüber weißer Stein aus der Diamantader, der seltenste Fund in der Hälfte aller Bergwerke des Reachs. Geschliffen wandert er in Mithril." },
  "rough_garnet": { en: "A dull red stone turned up in the shallow veins, now and then in a stolen purse. Cut, it is the first gem a jeweller sets.", de: "Ein matter roter Stein aus den flachen Adern, hin und wieder aus einem gestohlenen Beutel. Geschliffen der erste Stein, den ein Juwelier fasst." },
  "rough_godgem": { en: "The last stone the Reach gives up, from a seam at the very bottom of the ladder. Rough, it is only heavy. Cut, it is something else.", de: "Der letzte Stein, den das Reach hergibt, aus einer Ader ganz am Ende der Leiter. Roh ist er nur schwer. Geschliffen ist er etwas anderes." },
  "rough_onyx": { en: "Black stone from the onyx seam, and now and then from an idol coin that turned out to be worth more. Cut, it is set in runite.", de: "Schwarzer Stein aus der Onyxader, hin und wieder aus einer Götzenmünze, die mehr wert war, als sie aussah. Geschliffen wird er in Runit gefasst." },
  "rough_ruby": { en: "Red stone from the ruby seam, with the odd one turning up in deep coal or a melted insignia. Cut, it belongs in steel.", de: "Roter Stein aus der Rubinader, und der eine oder andere aus tiefer Kohle oder einem eingeschmolzenen Abzeichen. Geschliffen gehört er in Stahl." },
  "rough_sapphire": { en: "Blue stone from its own seam, and once in a while from a strongbox that was not yours. Cut, it goes into iron and leather.", de: "Blauer Stein aus seiner eigenen Ader, und ab und zu aus einer Geldkassette, die nicht deine war. Geschliffen wandert er in Eisen und Leder." },
  "rough_voidstone": { en: "A stone that is dark in a way the eye keeps sliding off. Mined from its own seam high in the ladder, cut into bloodiron and titanium.", de: "Ein Stein, so dunkel, dass das Auge immer wieder abrutscht. Hoch in der Leiter aus seiner eigenen Ader gebrochen, in Bluteisen und Titan gefasst." },
  "ruby": { en: "Cut and set in steel or scaled leather. Rings, amulets, the emberglass ring, and the staffs that call storms and void are made around it.", de: "Geschliffen und in Stahl oder Schuppenleder gefasst. Ringe, Amulette, der Glutglas-Ring und die Stäbe, die Sturm und Leere rufen, brauchen ihn." },
  "ruby_amulet": { en: "A ruby in steel, red as a forge mouth. It sits warm against the chest and puts weight behind the arm.", de: "Ein Rubin in Stahl, rot wie ein Essenmund. Liegt warm auf der Brust und legt Gewicht hinter den Arm." },
  "ruby_ring": { en: "A ruby in steel, red as a forge mouth. It warms the hand and puts weight behind whatever the hand swings.", de: "Ein Rubin in Stahl, rot wie ein Essenmund. Er wärmt die Hand und legt Gewicht hinter alles, was die Hand schwingt." },
  "rune_aegis_i": { en: "Ash essence and umber on pale reed. Set into plate, it thickens the armour a little, the way a second coat of paint thickens a wall.", de: "Ascheessenz und Umbra auf bleichem Schilf. In Platte gesetzt, verstärkt sie die Rüstung ein wenig, wie ein zweiter Anstrich eine Wand." },
  "rune_aegis_ii": { en: "Grave essence and verdant pigment on iron reed. The plate it is set into turns blows that would have got through.", de: "Grabessenz und Grün-Pigment auf Eisenschilf. Die Platte, in die sie gesetzt wird, hält Hiebe ab, die sonst durchgekommen wären." },
  "rune_aegis_iii": { en: "Hollow essence under radiant pigment on void reed. The strongest aegis rune, and plate that carries it shrugs off what should have dented it.", de: "Hohle Essenz unter Strahlendem Pigment. Die stärkste Ägide-Rune, und Platte damit schüttelt ab, was sie hätte eindellen müssen." },
  "rune_ambush_iv": { en: "Divine essence, godsbreath and void reed, scribed for leather. The first blow struck by whoever wears it lands far harder than any that follow.", de: "Göttliche Essenz und Götteratem, für Leder geritzt. Der erste Hieb, den der Träger führt, sitzt weit härter als alle, die folgen." },
  "rune_arcane_i": { en: "Mire essence and dim essence under verdant pigment. Set into a staff, wand or sceptre, it sharpens the caster's mind a little.", de: "Sumpfessenz und Trübessenz unter Grün-Pigment. In Stab, Zauberstab oder Zepter gesetzt, schärft sie den Geist des Zauberers ein wenig." },
  "rune_arcane_ii": { en: "Grave essence and two aether essences on iron reed. A magic weapon that carries it casts as if its wielder had read twice as many books.", de: "Grabessenz und zwei Aetheressenzen auf Eisenschilf. Eine Magiewaffe damit zaubert, als hätte ihr Träger doppelt so viele Bücher gelesen." },
  "rune_arcane_iii": { en: "Two divine essences and three of aether, bound in radiant light. The strongest arcane rune, and a staff set with it carries a scholar's whole mind.", de: "Zwei Göttliche und drei Aetheressenzen in strahlendem Licht. Die stärkste Arkan-Rune, und der Stab damit trägt den Verstand eines Gelehrten." },
  "rune_bounty": { en: "Two godsbreath, divine essence and relic dust, scribed for a ring or an amulet. Whoever wears it hits the monster of their Slayer contract harder than anything else.", de: "Götteratem und Göttliche Essenz, für Ring oder Amulett geritzt. Wer sie trägt, trifft das Monster seines Slayer-Auftrags am härtesten." },
  "rune_bulwark_i": { en: "Ash essence and umber on iron reed. Set into a shield, it puts the shield a little more often where the blow was going.", de: "Ascheessenz und Umbra auf Eisenschilf. In einen Schild gesetzt, bringt sie den Schild etwas öfter dorthin, wo der Hieb hinwollte." },
  "rune_bulwark_ii": { en: "Grave essence and violet pigment on iron reed. The shield that carries it catches blows the arm never saw coming.", de: "Grabessenz und Violett-Pigment auf Eisenschilf. Der Schild, der sie trägt, fängt Hiebe, die der Arm nie kommen sah." },
  "rune_bulwark_iii": { en: "Divine essence and radiant pigment on void reed. A shield set with it is a wall with a handle.", de: "Göttliche Essenz und Strahlendes Pigment auf Leerenschilf. Ein Schild damit ist eine Mauer mit Griff." },
  "rune_chronicle": { en: "Godbloom, divine essence and three relic dusts, scribed for a ring or an amulet. Whoever wears it is written down more carefully: every fight teaches a little more.", de: "Götzenblüte und Göttliche Essenz, für Ring oder Amulett geritzt. Wer sie trägt, wird sorgfältiger verzeichnet: Jeder Kampf lehrt ein wenig mehr." },
  "rune_evasion_i": { en: "Mire essence and umber on pale reed. Set into leather, it makes the wearer a little harder to hit, which is all leather has ever promised.", de: "Sumpfessenz und Umbra auf bleichem Schilf. In Leder gesetzt, macht sie den Träger schwerer zu treffen, und mehr hat Leder nie versprochen." },
  "rune_evasion_ii": { en: "Grave essence and violet pigment on iron reed. Leather set with it moves with the body instead of a half-step behind it.", de: "Grabessenz und Violett-Pigment auf Eisenschilf. Leder damit bewegt sich mit dem Leib statt einen halben Schritt hinter ihm." },
  "rune_evasion_iii": { en: "Hollow essence and radiant pigment on void reed. Leather that carries it is where the blow is not.", de: "Hohle Essenz und Strahlendes Pigment auf Leerenschilf. Leder damit ist dort, wo der Hieb nicht ist." },
  "rune_flame_i": { en: "A rune drawn in umber over a single ember essence. Set into any weapon, it gives the strike a chance to set the target burning.", de: "In Umbra über einer einzigen Glutessenz gezogen. In eine Waffe gesetzt, gibt sie dem Treffer eine Chance, das Ziel in Brand zu setzen." },
  "rune_flame_ii": { en: "Two ember essences under verdant pigment on iron reed. The fire it lends a weapon catches more often and burns hotter.", de: "Zwei Glutessenzen unter Grün-Pigment auf Eisenschilf. Das Feuer, das sie einer Waffe leiht, fängt öfter und brennt heißer." },
  "rune_flame_iii": { en: "Three ember essences bound into void reed with radiant pigment. A weapon that carries it leaves its targets burning long after the blow.", de: "Drei Glutessenzen, mit Strahlendem Pigment in Leerenschilf gebunden. Eine Waffe damit lässt ihre Ziele noch lange nach dem Hieb brennen." },
  "rune_frost_i": { en: "A frost essence under umber on pale reed, cold to hold. Set into a weapon, the blow has a chance to chill the target and slow its arm.", de: "Eine Frostessenz unter Umbra, kalt in der Hand. In eine Waffe gesetzt, kann der Hieb das Ziel unterkühlen und seinen Arm bremsen." },
  "rune_frost_ii": { en: "Two frost essences in verdant pigment on iron reed. The weapon chills more often, and the chill lasts.", de: "Zwei Frostessenzen in Grün-Pigment auf Eisenschilf. Die Waffe unterkühlt öfter, und die Kälte bleibt." },
  "rune_frost_iii": { en: "Three frost essences bound into void reed under radiant light. A weapon that carries it leaves ice in the wound, and the third chill in a row freezes the enemy outright.", de: "Drei Frostessenzen, in Leerenschilf gebunden. Eine Waffe damit lässt Eis in der Wunde, und die dritte Unterkühlung in Folge friert den Gegner ein." },
  "rune_gleaning": { en: "Two godbloom, two divine essences and relic dust, the dearest rune the craft knows. Jewellery set with it finds more in every fallen enemy.", de: "Zwei Götzenblüten und zwei Göttliche Essenzen, die teuerste Rune des Handwerks. Schmuck damit findet mehr in jedem gefallenen Gegner." },
  "rune_hunter_i": { en: "Mire essence and verdant pigment on iron reed, the hunter's mark. Set into a bow, it steadies the drawing hand.", de: "Sumpfessenz und Grün-Pigment auf Eisenschilf, das Zeichen des Jägers. In einen Bogen gesetzt, macht sie die ziehende Hand ruhig." },
  "rune_hunter_ii": { en: "The hunter's rune again, grave essence under verdant pigment. The bow that carries it is drawn by a surer hand.", de: "Noch einmal die Jagd-Rune, Grabessenz unter Grün-Pigment. Der Bogen, der sie trägt, wird von einer sichereren Hand gespannt." },
  "rune_hunter_iii": { en: "Divine essence and radiant pigment on void reed. A bow set with it is drawn as if the archer had hunted all their life, and most of them have.", de: "Göttliche Essenz und Strahlendes Pigment auf Leerenschilf. Ein Bogen damit wird gespannt, als hätte der Schütze sein Leben lang gejagt." },
  "rune_iron_answer_iv": { en: "A godiron bar bound into void reed with divine essence. Plate set with it answers every blow it takes with a little iron of its own.", de: "Ein Götzeneisenbarren, in Leerenschilf gebunden. Platte damit antwortet auf jeden Hieb, den sie nimmt, mit etwas eigenem Eisen." },
  "rune_judgement_iv": { en: "An idol shard bound with divine essence and relic dust. A weapon that carries it falls hardest on an enemy that is already nearly done.", de: "Ein Götzensplitter, mit Göttlicher Essenz gebunden. Eine Waffe damit fällt am härtesten auf einen Gegner, der schon fast erledigt ist." },
  "rune_keen_i": { en: "Umber on pale reed, bound with ash essence. Set into a melee weapon at the enchanting table, it puts a little more strength behind the swing.", de: "Umbra auf bleichem Schilf, mit Ascheessenz gebunden. In eine Nahkampfwaffe gesetzt, legt sie etwas mehr Kraft hinter den Hieb." },
  "rune_keen_ii": { en: "The keen rune scribed again on iron reed with verdant pigment. The blade it is set in hits like a stronger arm is swinging it.", de: "Die Schärfe-Rune, neu auf Eisenschilf mit Grün-Pigment geritzt. Die Klinge, in der sie sitzt, trifft, als schwinge sie ein stärkerer Arm." },
  "rune_keen_iii": { en: "Radiant pigment on void reed, bound with hollow essence. The strongest of the keen runes, and a melee weapon that carries it swings with a giant's strength.", de: "Strahlendes Pigment auf Leerenschilf, mit Hohler Essenz gebunden. Die stärkste Schärfe-Rune, und die Nahkampfwaffe damit schlägt mit Riesenkraft." },
  "rune_precise_i": { en: "Ash essence and umber on pale reed, drawn with a steady hand. Set into any weapon, it brings a little luck to the strike, and luck is what makes a hit a critical one.", de: "Ascheessenz und Umbra auf bleichem Schilf. In eine Waffe gesetzt, bringt sie dem Treffer Glück, und Glück macht aus einem Treffer einen kritischen." },
  "rune_precise_ii": { en: "The precise rune on iron reed, violet pigment over grave essence. The weapon's luck grows, and with it the chance that a blow lands where it hurts most.", de: "Die Präzise-Rune auf Eisenschilf, Violett über Grabessenz. Das Glück der Waffe wächst, und mit ihm die Chance, dass ein Hieb sitzt, wo er wehtut." },
  "rune_precise_iii": { en: "Violet on void reed, bound with hollow essence. The most luck a weapon can carry from a rune, and the critical blows come more often and hit harder.", de: "Violett auf Leerenschilf, mit Hohler Essenz gebunden. So viel Glück, wie eine Rune einer Waffe geben kann, und die kritischen Treffer kommen öfter." },
  "rune_restless": { en: "Three relic dusts and two godsbreath on void reed. Jewellery set with it will not let its wearer rest: the pause after each kill is shorter.", de: "Drei Reliktstaub und zwei Götteratem. Schmuck damit lässt seinen Träger nicht ruhen: Die Pause nach jedem besiegten Gegner ist kürzer." },
  "rune_second_arrow_iv": { en: "Hollow essence, godsbreath and relic dust, bound for the bow. Now and then the arrow it is set into is followed by a second one nobody nocked.", de: "Hohle Essenz, Götteratem und Reliktstaub, für den Bogen gebunden. Hin und wieder folgt dem Pfeil ein zweiter, den niemand aufgelegt hat." },
  "rune_storm_i": { en: "A storm essence under umber on pale reed, still crackling. Set into a weapon, the blow has a chance to shock the target and make it stumble.", de: "Eine Sturmessenz unter Umbra, noch knisternd. In eine Waffe gesetzt, kann der Hieb das Ziel schocken und straucheln lassen." },
  "rune_storm_ii": { en: "Two storm essences in verdant pigment on iron reed. The weapon shocks more often, and the stumble lasts longer.", de: "Zwei Sturmessenzen in Grün-Pigment auf Eisenschilf. Die Waffe schockt öfter, und das Straucheln dauert länger." },
  "rune_storm_iii": { en: "Three storm essences bound into void reed under radiant light. A weapon that carries it hits like a lightning strike and leaves the enemy reeling.", de: "Drei Sturmessenzen, in Leerenschilf gebunden. Eine Waffe damit trifft wie ein Blitzschlag und lässt den Gegner taumeln." },
  "rune_swift_i": { en: "Three pale reeds under umber and a mire essence. Set into a weapon, it loosens the wrist a little, and a little dexterity is enough to notice.", de: "Drei bleiche Schilfhalme unter Umbra und Sumpfessenz. In eine Waffe gesetzt, lockert sie das Handgelenk ein wenig, und das merkt man schon." },
  "rune_swift_ii": { en: "Violet pigment and grave essence on iron reed. The weapon that carries it moves in the hand like it weighs less than it does.", de: "Violett-Pigment und Grabessenz auf Eisenschilf. Die Waffe, die sie trägt, bewegt sich in der Hand, als wöge sie weniger, als sie wiegt." },
  "rune_swift_iii": { en: "Hollow essence under radiant pigment on void reed. Any weapon set with it answers the hand before the hand has finished asking.", de: "Hohle Essenz unter Strahlendem Pigment auf Leerenschilf. Jede Waffe damit gehorcht der Hand, bevor die Hand ausgesprochen hat." },
  "rune_tallyman": { en: "Godsbreath, divine essence and relic dust, bound for jewellery. It keeps count, and every fifth blow its wearer lands comes with interest.", de: "Götteratem, Göttliche Essenz und Reliktstaub, für Schmuck gebunden. Sie zählt mit, und jeder fünfte Treffer ihres Trägers kommt mit Zinsen." },
  "rune_thin_veil_iv": { en: "Three aether essences, godsbreath and relic dust on void reed. A staff set with it casts harder while the caster's ward is nearly whole.", de: "Drei Aetheressenzen, Götteratem und Reliktstaub. Ein Stab damit zaubert härter, solange der Ward des Zauberers fast ganz ist." },
  "rune_unbroken_wall_iv": { en: "Two godiron bars bound into void reed with divine essence. A shield set with it heals its bearer a little every time it catches a blow.", de: "Zwei Götzeneisenbarren, in Leerenschilf gebunden. Ein Schild damit heilt seinen Träger ein wenig, sooft er einen Hieb fängt." },
  "rune_veil_drinker_iv": { en: "Divine essence and three of aether, bound for cloth. A robe set with it drinks a little of every wound the caster deals and pours it back into the ward.", de: "Göttliche Essenz und Aether, für Stoff gebunden. Eine Robe damit trinkt von jeder Wunde, die der Zauberer schlägt, und füllt damit den Ward." },
  "rune_warding_i": { en: "Mire essence, umber and a single aether essence. Set into cloth, it holds a little more ward than the weave alone could.", de: "Sumpfessenz, Umbra und eine einzige Aetheressenz. In Stoff gesetzt, hält sie etwas mehr Ward, als das Gewebe allein könnte." },
  "rune_warding_ii": { en: "Grave essence and two of aether under verdant pigment. A robe that carries it keeps its ward up through more than the caster expected.", de: "Grabessenz und zwei Aetheressenzen unter Grün-Pigment. Eine Robe damit hält ihren Ward länger aufrecht, als der Zauberer erwartet hat." },
  "rune_warding_iii": { en: "Divine essence and three of aether in radiant light. The strongest warding rune, and cloth set with it holds a ward that would shame most plate.", de: "Göttliche Essenz und drei Aetheressenzen in strahlendem Licht. Die stärkste Abwehr-Rune, und Stoff damit hält einen Ward, der Platte beschämt." },
  "rune_warpath_iv": { en: "Hollow essence, godsbreath and relic dust on void reed. A melee weapon set with it hits harder with every blow that lands, until the enemy falls or a new one steps up.", de: "Hohle Essenz, Götteratem und Reliktstaub. Eine Nahkampfwaffe damit trifft mit jedem Treffer härter, bis der Gegner fällt oder ein neuer antritt." },
  "rune_wasting_iv": { en: "Divine essence, three ember essences, godsbreath and relic dust. Any weapon set with it makes its burns, bleeds and poisons eat deeper.", de: "Göttliche Essenz, drei Glutessenzen, Götteratem und Reliktstaub. Jede Waffe damit lässt ihre Brände, Blutungen und Gifte tiefer fressen." },
  "runite_arrow": { en: "Runite-headed and faintly blue at the tip. Archers say it finds the gap in a guard on its own, which is not true, but it is close.", de: "Mit Runitspitze und einem schwachen Blau am Ende. Schützen sagen, er finde die Lücke in der Deckung von selbst. Stimmt nicht, aber fast." },
  "runite_arrowheads": { en: "Runite heads with the bar's blue sheen still on them, forty-five to the bar. They are worth more than the shafts they sit on.", de: "Runitspitzen, der blaue Schimmer des Barrens noch daran, fünfundvierzig je Barren. Sie sind mehr wert als die Schäfte, auf denen sie sitzen." },
  "runite_axe": { en: "A runite bit with a blue sheen along the edge. Old smiths say the light sits where the metal is thinnest.", de: "Ein Runitblatt mit blauem Schimmer an der Schneide. Alte Schmiede sagen, das Licht sitzt dort, wo das Metall am dünnsten ist." },
  "runite_battleaxe": { en: "A runite crescent with the blue sheen pooled along the edge. The old light seems to like a wide blade.", de: "Ein Runit-Halbmond, der blaue Schimmer an der Schneide gesammelt. Das alte Licht scheint ein breites Blatt zu mögen." },
  "runite_chainbody": { en: "Runite rings with the blue sheen running through the weave like water. In the dark you glow faintly, and nothing gets through.", de: "Runitringe, der blaue Schimmer läuft durch das Geflecht wie Wasser. Im Dunkeln leuchtest du leise, und nichts kommt durch." },
  "runite_dagger": { en: "Runite with the blue sheen gathered at the point. Small, quick, and lit from inside where it matters.", de: "Runit, der blaue Schimmer an der Spitze gesammelt. Klein, schnell und von innen beleuchtet, wo es zählt." },
  "runite_focus": { en: "The blue sheen of runite deepens with aether until it looks lit from inside. Nothing in it burns. It only thinks.", de: "Der blaue Schimmer des Runits vertieft sich mit Aether, bis es von innen beleuchtet wirkt. Nichts darin brennt. Es denkt nur." },
  "runite_fullhelm": { en: "Runite over the whole head, the blue sheen caught in the visor slit. From outside it looks like the helm is watching.", de: "Runit um den ganzen Kopf, der blaue Schimmer im Sehschlitz gefangen. Von außen sieht es aus, als schaue der Helm." },
  "runite_gauntlets": { en: "Runite over the hands, the blue sheen brightest at the knuckles. The old light likes a fist, apparently.", de: "Runit über den Händen, der blaue Schimmer an den Knöcheln am hellsten. Das alte Licht mag offenbar eine Faust." },
  "runite_greataxe": { en: "Runite wide enough to show the blue sheen as a band. The old light runs the length of the edge.", de: "Runit, breit genug, dass der blaue Schimmer als Band erscheint. Das alte Licht läuft die ganze Schneide entlang." },
  "runite_greatsword": { en: "A runite blade with the blue sheen running its full length. In the dark it is the only thing the enemy sees.", de: "Eine Runitklinge, der blaue Schimmer über die ganze Länge. Im Dunkeln ist sie das Einzige, was der Gegner sieht." },
  "runite_kiteshield": { en: "Runite in a teardrop, the blue sheen brightest at the boss. The old light seems to prefer being hit to hitting.", de: "Runit in Tropfenform, der blaue Schimmer am Buckel am hellsten. Das alte Licht scheint lieber getroffen zu werden als zu treffen." },
  "runite_longbow": { en: "Bloodoak, grown on old battlefield soil, dark as dried blood and twice as heavy. It was always going to end up a weapon.", de: "Bluteiche, gewachsen auf altem Schlachtfeldboden, dunkel wie getrocknetes Blut und doppelt so schwer. Es sollte immer eine Waffe werden." },
  "runite_mace": { en: "Runite, the blue sheen pooled in the flanges. Old light, new dents.", de: "Runit, der blaue Schimmer in den Flanschen gesammelt. Altes Licht, neue Beulen." },
  "runite_maul": { en: "Runite in a block the size of a loaf, the sheen gone deep blue at the striking face. Old light does not mind being a hammer.", de: "Runit, ein Block so groß wie ein Brotlaib, der Schimmer auf der Schlagfläche tiefblau. Altes Licht hat nichts dagegen, als Hammer zu dienen." },
  "runite_medhelm": { en: "A runite cap, open-faced, the sheen brightest at the brow. Old light sits well on a soldier's head.", de: "Eine Runitkappe, offen, der Schimmer an der Stirn am hellsten. Altes Licht sitzt gut auf einem Soldatenkopf." },
  "runite_ore": { en: "Ore veined with old runic light, mined where the rock still remembers being written on. The sheen survives the furnace.", de: "Erz, von altem Runenlicht durchzogen, gebrochen, wo der Fels noch weiß, dass man ihn beschrieb. Der Schimmer überlebt den Ofen." },
  "runite_pickaxe": { en: "Forged from runite, and the head keeps the faint blue sheen of the bar. It goes through stone the way a knife goes through bread.", de: "Aus Runit geschmiedet, und der Kopf behält den blauen Schimmer des Barrens. Sie geht durch Stein wie ein Messer durch Brot." },
  "runite_platebody": { en: "A runite breastplate, the old light pooled at the collar and the ridge. Soldiers wore it to be seen. It also stopped things.", de: "Ein Runit-Brustpanzer, das alte Licht am Kragen und am Grat gesammelt. Soldaten trugen ihn, um gesehen zu werden. Er hielt auch Schläge." },
  "runite_platelegs": { en: "Runite greaves, the blue sheen running down the shin like a stripe. The enemy knows where your legs are. It does not help them.", de: "Runit-Beinschienen, der blaue Schimmer läuft als Streifen das Schienbein hinab. Der Gegner weiß, wo deine Beine sind. Es hilft ihm nicht." },
  "runite_sabatons": { en: "Runite over the boots, the blue sheen brightest at the toe. Each step leaves a little light on the stone for a moment.", de: "Runit über den Stiefeln, der blaue Schimmer an der Zehe am hellsten. Jeder Schritt lässt für einen Moment etwas Licht auf dem Stein." },
  "runite_scimitar": { en: "A runite curve with the blue sheen riding the edge like foam on a wave. The wave keeps coming.", de: "Eine Runitkurve, der blaue Schimmer an der Schneide wie Gischt auf einer Welle. Die Welle hört nicht auf." },
  "runite_shortbow": { en: "Bloodoak bent short. Each shot rolls into the next, and the dark grain seems to like the rhythm.", de: "Bluteiche, kurz gebogen. Jeder Schuss rollt in den nächsten, und die dunkle Maserung scheint den Takt zu mögen." },
  "runite_sickle": { en: "A runite blade that never seems to dull. Foragers swear the stems part before it touches them.", de: "Eine Runitklinge, die nie stumpf zu werden scheint. Sammler schwören, die Stängel teilen sich, bevor sie sie berührt." },
  "runite_spear": { en: "Runite drawn to a point so fine the blue sheen is all you see of it. It finds the gap it is pointed at.", de: "Runit, zu einer so feinen Spitze gezogen, dass der blaue Schimmer alles ist, was man davon sieht. Er findet die Lücke, auf die er zeigt." },
  "runite_staff": { en: "Runite steeped in mire essence, grave fungus packed into the grain. It smells of the Ashfields' ditches and poisons like them.", de: "Runit, in Sumpfessenz gezogen, Grab-Pilz in die Maserung gestopft. Riecht nach den Gräben der Aschfelder und vergiftet wie sie." },
  "runite_sword": { en: "Runite, straight, the blue sheen along the fuller. A plain sword, except for the faint glow in the hand.", de: "Runit, gerade, der blaue Schimmer in der Hohlkehle. Ein schlichtes Schwert, bis auf das leise Leuchten in der Hand." },
  "runite_towershield": { en: "A tower of runite with the sheen running in bands across it. In a dark corridor, the enemy sees a blue door coming.", de: "Ein Turm aus Runit, der Schimmer in Bändern darüber. In einem dunklen Gang sieht der Gegner eine blaue Tür auf sich zukommen." },
  "runite_wand": { en: "Runite over a void shard. The blue sheen dims where the shard sits, as if the light knew better than to go there.", de: "Runit über einem Leerensplitter. Der blaue Schimmer verblasst, wo der Splitter sitzt, als wüsste das Licht, dass es dort nichts sucht." },
  "saltgrave_cutlass": { en: "The cutlass of Saltgrave the Returned, who came back up with the tide and did not stop walking. It opens what it touches.", de: "Das Entermesser von Salzgrab dem Wiedergekehrten, der mit der Flut heraufkam und nicht aufhörte zu gehen. Es öffnet, was es berührt." },
  "salve_gravensap": { en: "Gravensap worked into oil until it spreads. Rubbed on, it sets like a second skin, and the body carries far more before it falls.", de: "Grabharz, in Öl gearbeitet, bis es sich streichen lässt. Aufgetragen wird es zur zweiten Haut, und der Leib trägt weit mehr, bevor er fällt." },
  "salve_of_mending": { en: "Witchgrass ground into bloodbeet pulp. Rubbed into a wound, it closes clean, and the stain is the only thing that stays.", de: "Hexengras, in Blutrübenbrei zerrieben. In die Wunde gerieben, schließt sie sauber, und nur der Fleck bleibt." },
  "sapphire": { en: "Cut and polished until the blue goes deep. Set in iron, leather or mithril, it makes rings, bands and a circlet for miners.", de: "Geschliffen und poliert, bis das Blau tief wird. In Eisen, Leder oder Mithril gefasst gibt er Ringe, Bänder und einen Reif für Bergleute." },
  "sapphire_amulet": { en: "A sapphire in iron, blue as the sheen on old runite. It cools the mind the way the stone cools the hand.", de: "Ein Saphir in Eisen, blau wie der Schimmer auf altem Runit. Er kühlt den Kopf, wie der Stein die Hand kühlt." },
  "sapphire_ring": { en: "A sapphire in iron, cold on the finger. It finds the thin place in an enemy's ward and goes through it.", de: "Ein Saphir in Eisen, kalt am Finger. Er findet die dünne Stelle im Ward eines Gegners und geht hindurch." },
  "scaled_leather": { en: "Hide with the scales left on, from crabs, kraken, bears and worse. Crafters rivet it, harden it, or wear it as it comes.", de: "Haut mit den Schuppen daran, von Krabben, Kraken, Bären und Schlimmerem. Handwerker vernieten es, härten es oder tragen es, wie es kommt." },
  "scaled_leather_body": { en: "Scaled leather in overlapping rows down the chest. An arrow finds a scale and slides, which is all a hunter asks.", de: "Schuppenleder in überlappenden Reihen über die Brust. Ein Pfeil findet eine Schuppe und rutscht ab, und mehr verlangt ein Jäger nicht." },
  "scaled_leather_boots": { en: "Scaled leather boots, the scales pointing down so the mud slides off. They dry by morning. The hunter usually does not.", de: "Schuppenlederstiefel, die Schuppen nach unten, damit der Schlamm abgleitet. Bis zum Morgen sind sie trocken. Der Jäger meist nicht." },
  "scaled_leather_helm": { en: "Scaled leather laid in overlapping rows, so an arrow slides instead of biting. The scales click faintly when you turn your head.", de: "Schuppenleder in überlappenden Reihen gelegt, damit ein Pfeil abrutscht, statt zu beißen. Die Schuppen klicken leise, wenn du den Kopf drehst." },
  "scaled_leather_legs": { en: "Scaled leather down the legs in rows that overlap when you crouch. An arrow slides where it should bite.", de: "Schuppenleder die Beine hinab, in Reihen, die beim Kauern überlappen. Ein Pfeil rutscht ab, wo er beißen sollte." },
  "scaled_leather_vambraces": { en: "Scaled leather down the forearm, the scales pointing toward the wrist so the string slides off them.", de: "Schuppenleder den Unterarm hinab, die Schuppen zum Handgelenk zeigend, damit die Sehne abgleitet." },
  "scavenger_boots": { en: "A goblin rogue's boots, soled with scraps of everything ever stolen. Made for leaving quickly, and after a kill they leave quicker.", de: "Stiefel eines Goblin-Schurken, besohlt mit Resten von allem, was je gestohlen wurde. Fürs schnelle Weggehen, nach einem Kill noch schneller." },
  "shade_rune": { en: "Two scraps of shade-light bound with grave essence into a rune that is never quite in focus. Duskweave robes and the void shroud are woven around it.", de: "Zwei Reste Klag-Licht, mit Grabessenz zu einer Rune gebunden, die nie ganz scharf wird. Dämmergewebe und der Leeren-Umhang werden darum gewebt." },
  "shadestalker_hood": { en: "A hood from the Mirror Halls, cut from whatever the wailing shades are made of. Cold on the scalp, and it mends a little with every kill.", de: "Eine Kapuze aus den Spiegelhallen, geschnitten aus dem Stoff Klagender Schatten. Kalt auf dem Kopf, und mit jedem Kill flickt sie etwas." },
  "shadowhide_body": { en: "Four shadowhides into a cuirass that drinks the light. The enemy swings at a darker patch of dark and finds you were not in it.", de: "Vier Schattenleder zu einem Kürass, der das Licht schluckt. Der Gegner schlägt in ein dunkleres Stück Dunkel und findet dich nicht darin." },
  "shadowhide_boots": { en: "Shadowhide boots that drink the light at ground level. Your footprints are there. Your feet are a little elsewhere.", de: "Schattenlederstiefel, die am Boden das Licht schlucken. Deine Spuren sind da. Deine Füße ein wenig woanders." },
  "shadowhide_helm": { en: "Shadowhide drinks the light, and a coif of it drinks the light around your face. The enemy aims at a shape that is not there.", de: "Schattenleder schluckt das Licht, und eine Haube daraus schluckt das Licht um dein Gesicht. Der Gegner zielt auf eine Gestalt, die nicht da ist." },
  "shadowhide_legs": { en: "Shadowhide greaves that drink the light below the knee. The enemy aims at where your legs should be. They are a little to the left.", de: "Schattenleder-Beinschienen, die unter dem Knie das Licht schlucken. Der Gegner zielt, wo deine Beine sein sollten. Sie sind etwas weiter links." },
  "shadowhide_vambraces": { en: "Shadowhide around the forearm, drinking the light. A blade aimed at the arm finds a little less arm than expected.", de: "Schattenleder um den Unterarm, das Licht schluckend. Eine Klinge, die auf den Arm zielt, findet etwas weniger Arm als erwartet." },
  "shellfather_aegis": { en: "The shell of Shellfather the Unbroken, struck a thousand times on the Shoals and striking back every time. The habit is in the shell.", de: "Der Panzer von Schalenvater dem Ungebrochenen, tausendmal getroffen, und jedes Mal schlug er zurück. Die Gewohnheit steckt im Panzer." },
  "shock_rune": { en: "Storm essence bound two to one into a shard that bites the fingers. Rare on the skeleton ice mages, common on a runecrafter's bench past the fortieth level.", de: "Sturmessenz, zwei zu eins zu einem Splitter gebunden, der in die Finger beißt. Selten bei Skelett-Eismagiern, gewöhnlich auf der Runenbank ab Level 40." },
  "shroud_of_the_dead": { en: "A burial shroud from the Crypt, worn by the Necromancer Lord's ice mages. Cold, and whatever burns or bleeds near it does so worse.", de: "Ein Leichentuch aus der Krypta, von den Skelett-Eismagiern getragen. Kalt, und was in seiner Nähe brennt oder blutet, tut es schlimmer." },
  "sickle_shiv": { en: "A hand sickle ground to a point, found in the straw where the cows bed down. Someone used it to end things. It still does.", de: "Eine Handsichel, zur Spitze geschliffen, gefunden im Stroh, wo die Kühe liegen. Jemand hat damit Dinge beendet. Das tut sie noch." },
  "siren_shockstaff": { en: "Driftwood and siren bone, still salt-white. The song that drowned sailors is gone. The spark that rode on it is not.", de: "Treibholz und Sirenenknochen, noch salzweiß. Das Lied, das Seeleute ertränkte, ist fort. Der Funke, der darauf ritt, nicht." },
  "skeletal_longbow": { en: "A skeleton archer's bow from the Crypt, the stave a fused spine. It has had a long time to learn where to aim.", de: "Bogen eines Skelett-Bogenschützen aus der Krypta, der Stab eine verwachsene Wirbelsäule. Er hatte lange Zeit, zielen zu lernen." },
  "skybreaker_greatsword": { en: "Forged around a roc elder's wing bone, with the storm still in it. When it lands true, the sky comes down with it.", de: "Um den Flügelknochen eines Roc-Ältesten geschmiedet, der Sturm noch darin. Wenn es richtig trifft, kommt der Himmel mit herunter." },
  "skyfather_recurve": { en: "The bow of Stormcrown the Skyfather, strung with a storm that did not end when he did. Every arrow leaves the string with lightning on it.", de: "Der Bogen von Himmelsvater Sturmkrone, bespannt mit einem Sturm, der nicht endete, als er es tat. Jeder Pfeil verlässt die Sehne mit Blitz daran." },
  "skygrip_gauntlets": { en: "Roc hunter's talon leather over the palm, cured with the sky still in it. The grip holds tightest when the hand is shaking.", de: "Krallenleder eines Roc-Jägers über der Handfläche, der Himmel noch darin. Der Griff hält am festesten, wenn die Hand zittert." },
  "skytalon_recurve": { en: "A roc hunter's talon curved into a bow limb and strung on sinew. There is weather in it, and the arrows carry some.", de: "Die Kralle eines Roc-Jägers zum Wurfarm gebogen und auf Sehne gespannt. Da ist Wetter drin, und die Pfeile nehmen etwas davon mit." },
  "slagcarapace_plate": { en: "The Iron Revenant's breastplate, forged by the smith who died inside it and kept forging. Hit it, and it hits back.", de: "Der Brustpanzer des Eisenrevenants, geschmiedet vom Schmied, der darin starb und weiterschmiedete. Wer ihn trifft, wird zurückgetroffen." },
  "slagforged_sword": { en: "Beaten out of pit slag by kobolds who had no better iron. It is ugly, and it swings hardest when its wielder is nearly done.", de: "Von Kobolden aus Grubenschlacke geschlagen, weil sie kein besseres Eisen hatten. Hässlich, und am härtesten, wenn sein Träger fast fertig ist." },
  "slagheart_cuirass": { en: "The chest of a slag abomination from the Forge Abyss, cooled into something like plate. Warm to wear, and it pays back what it takes.", de: "Brust einer Schlacken-Abomination, zu etwas wie Platte erkaltet. Warm zu tragen, und sie zahlt zurück, was sie einsteckt." },
  "slagweave_cape": { en: "Woven from the fibers a voidhusk crusher leaves in the slag, heavy as chain. It belonged to something that only ever took on larger things.", de: "Gewebt aus Fasern, die ein Leeren-Zerschmetterer in der Schlacke lässt, schwer wie Kette. Es gehörte etwas, das nur Größeres bekämpfte." },
  "smokeweave_cape": { en: "Cloth that came out of the Ashfields' ditches already grey, smelling of smoke that never stops. Whatever festers near it does not get better.", de: "Stoff, der schon grau aus den Gräben der Aschfelder kam, nach Rauch riechend, der nie aufhört. Was in seiner Nähe eitert, wird nicht besser." },
  "sootscale_greaves": { en: "Pitch beetle plates strapped over the shins, still faintly warm. The beetle took on things far bigger than itself. The greaves remember how.", de: "Pechkäferplatten über die Schienbeine geschnallt, noch schwach warm. Der Käfer legte sich mit Größerem an. Die Schienen wissen noch, wie." },
  "sorrow_staff": { en: "Cut from a sorrow wraith in the Whispering Void. The grief in it burns slowly, and it takes a little back from every kill.", de: "Einem Kummer-Wraith in der Flüsternden Leere entrissen. Der Gram darin brennt langsam, und mit jedem Kill holt er sich etwas zurück." },
  "soul_amulet": { en: "A soul opal in bronze. The stone remembers something, and whoever wears it thinks a little more clearly for the company.", de: "Ein Seelenopal in Bronze. Der Stein erinnert sich an etwas, und wer ihn trägt, denkt in dieser Gesellschaft etwas klarer." },
  "soulfire_banquet": { en: "Soulfish, wyvern, ambergrain and godsbreath, cooked by someone who has mastered the craft. For a while, everything in the body wakes up.", de: "Seelenfisch, Wyvern, Bernsteingetreide und Götteratem, gekocht von einem, der das Handwerk beherrscht. Für eine Weile wacht alles im Leib auf." },
  "soulflayer_amulet": { en: "A soul flayer's claw from the Abyssal Throne, set in iron. Every kill leaves a little ward behind, as if something had been peeled off and kept.", de: "Die Klaue eines Seelenschinders vom Abyssalen Thron, in Eisen gefasst. Jeder Kill lässt etwas Ward zurück, als wäre etwas abgeschält worden." },
  "soulgourd": { en: "A pale gourd that hums faintly when it is cut open. Stews, brisket and the steelshot bisque are built on it.", de: "Ein bleicher Kürbis, der leise summt, wenn man ihn aufschneidet. Eintöpfe, Braten und die Stahlschuss-Bisque bauen darauf." },
  "soulgourd_brisket": { en: "Venison braised on a bed of soulgourd, with eel for the fat. Three portions, and each one puts iron in the arm and the ribs.", de: "Hirsch, auf einem Bett aus Seelenkürbis geschmort, der Aal liefert das Fett. Drei Portionen, und jede legt Eisen in Arm und Rippen." },
  "soulopal": { en: "A milky stone that turns up in the strongest creatures of the Reach, as if they had swallowed it. Jewellers set it in amulets, and the void anchor needs two.", de: "Ein milchiger Stein aus den stärksten Kreaturen des Reachs, als hätten sie ihn verschluckt. Amulette und der Leerenstabilisator brauchen ihn." },
  "soulopal_band": { en: "A soul opal in a band of bark, from the Forest Warden's own hand. Each kill leaves a little ward behind, as if the forest were paying.", de: "Ein Seelenopal in einem Reif aus Rinde, von der Hand des Waldvogts selbst. Jeder Kill lässt etwas Ward zurück, als zahlte der Wald." },
  "soulthorn_pendant": { en: "A thorn from the Forest Warden, worn on a cord. It went in easily and would not come out. Whatever it pricks does not heal properly.", de: "Ein Dorn vom Waldvogt, an einer Schnur getragen. Er ging leicht hinein und wollte nicht wieder heraus. Was er ritzt, heilt nicht richtig." },
  "spearthrower_longbow": { en: "Pried out of a siege idol's arm. Strung for arrows now, but every fourth shot still thinks it is a spear.", de: "Aus dem Arm eines Belagerungsgötzen gebrochen. Für Pfeile bespannt, aber jeder vierte Schuss hält sich noch für einen Speer." },
  "spectral_hunter_bow": { en: "Left where the Spectral Stag last stood. Pale wood that does not feel like wood, and it knows a marked quarry when it sees one.", de: "Zurückgelassen, wo der Geisterhirsch zuletzt stand. Bleiches Holz, das sich nicht wie Holz anfühlt, und es kennt markierte Beute." },
  "spellbinder_ring": { en: "A sapphire in mithril, storm essence sealed under the stone. It crackles when a ward is near, and it gets through.", de: "Ein Saphir in Mithril, Sturmessenz unter dem Stein versiegelt. Er knistert, wenn ein Ward nah ist, und er kommt durch." },
  "spellflare_tisane": { en: "A clear broth steeped with nightbloom and thistle over eel and venison. It warms the mind more than the belly and holds the ward a little wider.", de: "Eine klare Brühe, mit Nachtblüte und Distel über Aal und Hirsch gezogen. Wärmt den Kopf mehr als den Bauch und hält den Ward ein Stück weiter." },
  "spellwarden_bisque": { en: "A thick bisque of carp and bloodgrain, made for casters who eat between spells. Clears the head and thickens the ward.", de: "Eine dicke Bisque aus Karpfen und Blutgetreide, gemacht für Zauberer, die zwischen zwei Sprüchen essen. Klärt den Kopf und stärkt den Ward." },
  "stagleather_chaps": { en: "Wild stag hide, cured with the grain running down the leg. The stags of the Wildwood are the size of monuments. The chaps are used to that.", de: "Wildhirschhaut, gegerbt, die Maserung das Bein hinab. Die Hirsche des Wildwalds sind groß wie Denkmäler. Die Beinlinge sind das gewohnt." },
  "stagstride_longbow": { en: "A Wildwood bow shaped to the stag's own gait, long and loping. Each kill shortens the pause before the next step.", de: "Ein Wildwaldbogen, geformt nach dem Lauf des Hirsches, lang und weit ausgreifend. Jeder Kill verkürzt die Pause vor dem nächsten Schritt." },
  "starcap_truffle": { en: "A truffle dug from under the starcaps, dense and worth its weight in gold to any cook past the ninetieth level. Shaved over risotto or the abyssal feast.", de: "Eine Trüffel, unter den Sternkappen ausgegraben, dicht und für jeden Koch ab Level 90 Gold wert. Gehobelt über Risotto oder das Abgrund-Festmahl." },
  "starweave_coronet": { en: "Starweave bound with aether and eight void shards, worn as a circlet. The ward it holds is the only crown a caster needs.", de: "Sternweb, mit Aether und acht Leerensplittern zu einem Reif gebunden. Der Ward darin ist die einzige Krone, die ein Zaubernder braucht." },
  "starweave_handwraps": { en: "Starweave wound around the hands, bound with aether and void. The ward sits closest to the skin here, where the spells leave.", de: "Sternweb um die Hände gewickelt, mit Aether und Leere gebunden. Hier sitzt der Ward am dichtesten an der Haut, wo die Zauber die Hand verlassen." },
  "starweave_sandals": { en: "Starweave sandals bound with aether and void, the soles so thin the stone is felt through them. The ward is not thin.", de: "Sternweb-Sandalen, mit Aether und Leere gebunden, die Sohlen so dünn, dass man den Stein spürt. Der Ward ist nicht dünn." },
  "starweave_skirt": { en: "Starweave fallen in long panels, bound with void and aether. It moves like smoke and holds a ward like a wall.", de: "Sternweb in langen Bahnen, mit Leere und Aether gebunden. Bewegt sich wie Rauch und hält einen Ward wie eine Mauer." },
  "starweave_vestment": { en: "Starweave, three bolts of it, bound with aether and void. The ward it carries is thicker than any plate, and it weighs nothing.", de: "Sternweb, drei Bahnen davon, mit Aether und Leere gebunden. Der Ward, den es trägt, ist dicker als jede Platte, und es wiegt nichts." },
  "steel_arrow": { en: "Steel over wood and feather. It goes where it is sent and comes out of the target bent, which is a fair trade.", de: "Stahl über Holz und Feder. Er geht, wohin man ihn schickt, und kommt verbogen aus dem Ziel, ein fairer Tausch." },
  "steel_arrowheads": { en: "Steel heads forged narrow, forty-five to the bar. They hold an edge through leather that iron only dents.", de: "Stahlspitzen, schmal geschmiedet, fünfundvierzig je Barren. Sie halten eine Schneide durch Leder, das Eisen nur eindellt." },
  "steel_axe": { en: "Folded steel that rings against the trunk. Bites deep in wood and deeper in anything softer.", de: "Gefalteter Stahl, der am Stamm klingt. Beißt tief ins Holz und tiefer in alles, was weicher ist." },
  "steel_battleaxe": { en: "Steel bit, iron langets, ash haft. When it lands squarely there is not much left to argue with.", de: "Stahlblatt, Eisenschienen, Eschenstiel. Wenn sie sauber trifft, bleibt nicht viel zum Widersprechen übrig." },
  "steel_chainbody": { en: "Steel rings, finer than iron and twice as many. It moves like cloth and stops like a wall.", de: "Stahlringe, feiner als Eisen und doppelt so viele. Es bewegt sich wie Stoff und hält wie eine Mauer." },
  "steel_dagger": { en: "Folded steel, ground on both edges. It goes in clean and comes out the same, which is more than the enemy can say.", de: "Gefalteter Stahl, beidseitig geschliffen. Geht sauber rein und kommt sauber raus, was der Gegner nicht von sich sagen kann." },
  "steel_focus": { en: "A steel blank quenched in frost essence. It keeps the hand cool and the thoughts in order.", de: "Ein Stahlrohling, in Frostessenz abgeschreckt. Hält die Hand kühl und die Gedanken in Ordnung." },
  "steel_fullhelm": { en: "Folded steel closed over the face, the visor pierced for breath. Behind it the world is small and the blows are muffled.", de: "Gefalteter Stahl, über dem Gesicht geschlossen, das Visier zum Atmen gelocht. Dahinter ist die Welt klein und die Schläge gedämpft." },
  "steel_gauntlets": { en: "Folded steel over the hand, each finger plated in segments. A closed fist in these is a weapon by itself.", de: "Gefalteter Stahl über der Hand, jeder Finger in Gliedern geplattet. Eine geschlossene Faust darin ist eine Waffe für sich." },
  "steel_greataxe": { en: "Steel on a haft wrapped in rawhide so it does not slip. It takes two hands and most of the breath.", de: "Stahl an einem Stiel, in Rohleder gewickelt, damit er nicht rutscht. Braucht beide Hände und den Großteil der Luft." },
  "steel_greatsword": { en: "Folded steel, a hand and a half of grip, a blade that rings when it clears the scabbard.", de: "Gefalteter Stahl, anderthalb Hände Griff, eine Klinge, die klingt, wenn sie die Scheide verlässt." },
  "steel_kiteshield": { en: "Folded steel in a teardrop, polished to throw back torchlight. It rings when struck and does not give.", de: "Gefalteter Stahl in Tropfenform, poliert, bis er das Fackellicht zurückwirft. Klingt beim Treffer und gibt nicht nach." },
  "steel_longbow": { en: "Ashbark, grey-grained and stiff, cut from stands the ash never quite reached. It holds a draw without complaint.", de: "Aschenrinde, grau gemasert und steif, geschlagen in Beständen, die die Asche nie ganz erreichte. Sie hält den Zug ohne Klage." },
  "steel_mace": { en: "Steel flanges, ground sharp at the ridges. It dents plate and whatever is inside the plate.", de: "Stahlflansche, an den Graten scharf geschliffen. Beult Platte ein und das, was in der Platte steckt." },
  "steel_maul": { en: "A steel block on a haft as thick as an arm. Whatever it lands on is a different shape afterwards.", de: "Ein Stahlblock an einem Stiel, dick wie ein Arm. Was er trifft, hat danach eine andere Form." },
  "steel_medhelm": { en: "A steel cap with cheek plates, open at the face. Lighter than the full helm, and you can still spit.", de: "Eine Stahlkappe mit Wangenblechen, am Gesicht offen. Leichter als der Vollhelm, und man kann noch spucken." },
  "steel_pickaxe": { en: "Folded steel on a seasoned haft. Heavier than iron, and it pays back every ounce in the swing.", de: "Gefalteter Stahl auf einem abgelagerten Stiel. Schwerer als Eisen, und jedes Lot davon zahlt sich im Schlag aus." },
  "steel_platebody": { en: "Folded steel shaped over the chest with a ridge down the middle to turn a point. It rings when struck, and the point goes elsewhere.", de: "Gefalteter Stahl über die Brust geformt, ein Grat in der Mitte, der eine Spitze ablenkt. Es klingt beim Treffer, und die Spitze geht woandershin." },
  "steel_platelegs": { en: "Steel over the legs, the plates overlapping at the knee so nothing finds the joint. They weigh, and they are worth it.", de: "Stahl über den Beinen, die Platten am Knie überlappend, damit nichts das Gelenk findet. Sie wiegen, und sie sind es wert." },
  "steel_sabatons": { en: "Folded steel over the boot in overlapping plates. They are heavy, they are loud, and nothing underfoot gets through.", de: "Gefalteter Stahl über dem Stiefel in überlappenden Platten. Schwer, laut, und nichts unter dem Fuß kommt durch." },
  "steel_scimitar": { en: "Folded steel in a curve. It does not stop at the first cut. It gathers.", de: "Gefalteter Stahl in einer Kurve. Es hört nicht beim ersten Schnitt auf. Es sammelt." },
  "steel_shortbow": { en: "Ashbark, stiff and grey, bent into a short stave that snaps back like it resents the draw.", de: "Aschenrinde, steif und grau, zu einem kurzen Stab gebogen, der zurückschnellt, als nähme er den Zug übel." },
  "steel_sickle": { en: "Steel holds an edge that iron only borrows. Tough enough for thornhemp hedges and thick marsh reed.", de: "Stahl hält eine Schärfe, die Eisen sich nur leiht. Zäh genug für Dornhanfhecken und dickes Sumpfschilf." },
  "steel_spear": { en: "A steel head with a spine down the middle. It goes in on the thrust and comes out on the pull without catching.", de: "Ein Stahlkopf mit Grat in der Mitte. Geht beim Stoß rein und beim Zug raus, ohne hängen zu bleiben." },
  "steel_staff": { en: "Nine force shards sunk into folded steel. Each strike leaves a little of its charge for the next.", de: "Neun Kraftsplitter, in gefalteten Stahl versenkt. Jeder Schlag lässt dem nächsten ein wenig von seiner Ladung da." },
  "steel_sword": { en: "Folded steel, a straight blade, a plain guard. The Reach's soldiers carried these for generations and never asked for better.", de: "Gefalteter Stahl, gerade Klinge, schlichte Parierstange. Die Soldaten des Reachs trugen sie über Generationen und verlangten nie Besseres." },
  "steel_towershield": { en: "Steel, tall as a man's chest, with a notch at the top for looking over. The notch is the only part of you an enemy will see.", de: "Stahl, hoch wie eine Brust, mit einer Kerbe oben zum Drüberschauen. Die Kerbe ist das Einzige, was der Gegner von dir sieht." },
  "steel_wand": { en: "Steel with storm essence sealed under the grip. It twitches in the hand before thunder, like a dowsing rod for lightning.", de: "Stahl mit Sturmessenz unter dem Griff versiegelt. Zuckt vor dem Donner in der Hand wie eine Wünschelrute für Blitze." },
  "steel_warblade": { en: "Three bars of steel in one blade, wider than a sword needs to be. The width is for the wound it leaves.", de: "Drei Barren Stahl in einer Klinge, breiter, als ein Schwert sein müsste. Die Breite ist für die Wunde, die sie hinterlässt." },
  "steelshot_bisque": { en: "Eel and venison in a soulgourd broth, with nightbloom folded in last. An archer's meal: steadier hands, quicker feet.", de: "Aal und Hirsch in Seelenkürbisbrühe, die Nachtblüte zuletzt untergehoben. Ein Schützenmahl: ruhigere Hände, schnellere Füße." },
  "stolen_shortbow": { en: "A Reach bow in goblin hands, the stave notched for every theft. Whoever it is pointed at tends to leave something behind.", de: "Ein Bogen des Reachs in Goblinhand, der Stab für jeden Diebstahl gekerbt. Wen er trifft, der lässt meist etwas liegen." },
  "storm_core": { en: "What is left of the Storm Roc when the lightning goes out of it, a core that still crackles. Set in runite, it becomes the stormcaller amulet.", de: "Was vom Sturm-Roc bleibt, wenn der Blitz aus ihm weicht, ein Kern, der noch knistert. In Runit gefasst wird daraus das Sturmrufer-Amulett." },
  "storm_mantle": { en: "Feathers of the Stormbringer sewn onto sailcloth. There is weather in it, and whatever you lay on an enemy stays laid a little longer.", de: "Federn des Sturmbringers auf Segeltuch genäht. Da ist Wetter drin, und was du einem Gegner anhängst, hängt ein wenig länger." },
  "stormcaller_amulet": { en: "A storm core in runite, from the heart of a roc that called down lightning. The sky is still in it, and the caster feels it at the collar.", de: "Ein Sturmkern in Runit, aus dem Herzen eines Rocs, der Blitze herabrief. Der Himmel ist noch darin, und der Zaubernde spürt ihn am Kragen." },
  "stormcaller_rod": { en: "Aether shards set in runite around a single ruby. It hums before a storm, and it hums before it strikes.", de: "Aethersplitter in Runit um einen einzelnen Rubin gefasst. Sie summt vor dem Gewitter, und sie summt, bevor sie zuschlägt." },
  "stormcaller_totem": { en: "A goblin stormcaller's totem, wrapped in copper wire that still bites. It pulls a little of every wound back into the caster's ward.", de: "Das Totem eines Goblin-Sturmrufers, in Kupferdraht gewickelt, der noch beißt. Es zieht ein wenig von jeder Wunde in den Ward des Zaubernden." },
  "stormcore_pendant": { en: "A sliver of the Stormbringer's core in a wire cage. It holds more sky than a pendant should, and it pulls a little of every wound back into the ward.", de: "Ein Splitter vom Kern des Sturmbringers im Drahtkäfig. Hält mehr Himmel, als ein Anhänger sollte, und zieht von jeder Wunde etwas in den Ward." },
  "stormcrest_staff": { en: "The crest feathers of the Stormbringer, bound to an aerie branch. Lightning follows it, and it hits hardest while your ward runs high.", de: "Die Kammfedern des Sturmbringers, an einen Horstast gebunden. Der Blitz folgt ihm, und er schlägt am härtesten, solange dein Ward hoch steht." },
  "stormhide_helm": { en: "Roc hide from the Highlands, cured with the storm still in it. The hair stands up under it, and every kill knits something shut.", de: "Roc-Haut aus dem Hochland, gegerbt, der Sturm noch darin. Die Haare stellen sich darunter auf, und jeder Kill näht etwas zu." },
  "studded_leather": { en: "Scaled leather riveted over a bar of steel, stud by stud. Heavier than any hide, and it stops what hide cannot.", de: "Schuppenleder, Niete für Niete über einem Stahlbarren vernietet. Schwerer als jede Haut, und es hält, was Haut nicht hält." },
  "studded_leather_body": { en: "A brigandine of studded leather, the iron studs in rows close enough to touch. Between them, nothing gets through either.", de: "Eine Brigantine aus genietetem Leder, die Eisennieten in Reihen, dicht an dicht. Dazwischen kommt auch nichts durch." },
  "studded_leather_boots": { en: "Studded leather sabatons, the iron studs across the toe. They grip stone and they take a kick without noticing.", de: "Genietete Lederstiefel, die Eisennieten über der Zehe. Sie greifen auf Stein und stecken einen Tritt weg, ohne es zu merken." },
  "studded_leather_helm": { en: "Hardened leather set with iron studs in rows. The studs catch a blade before the leather has to.", de: "Gehärtetes Leder, mit Eisennieten in Reihen besetzt. Die Nieten fangen eine Klinge ab, bevor das Leder es muss." },
  "studded_leather_legs": { en: "Studded leather tassets hung from the belt, the iron studs in rows down the thigh. They swing when you walk. Not when it matters.", de: "Genietete Lederbeintaschen am Gürtel, die Eisennieten in Reihen den Schenkel hinab. Sie schwingen beim Gehen. Nicht, wenn es zählt." },
  "studded_leather_vambraces": { en: "Studded leather down the forearm, the studs in a line where a blade would land. It lands on the studs.", de: "Genietetes Leder den Unterarm hinab, die Nieten in einer Reihe, wo eine Klinge landen würde. Sie landet auf den Nieten." },
  "talon_dagger": { en: "A roc fledgling's talon on a leather grip. Not yet grown, already sharp enough to open a vein.", de: "Die Kralle eines Roc-Jungvogels auf Ledergriff. Noch nicht ausgewachsen, schon scharf genug, um eine Ader zu öffnen." },
  "thorncrown": { en: "Mother Bramble's crown, grown rather than made. The thorns point inward as much as outward, and what they prick does not heal well.", de: "Die Krone von Mutter Dorn, gewachsen, nicht gemacht. Die Dornen zeigen nach innen wie nach außen, und was sie ritzen, heilt nicht gut." },
  "thornmail_gauntlets": { en: "Bark of the Elder Treant, the thorns left on the outside. Whatever strikes the hand wearing it bleeds for the trouble.", de: "Rinde des Alten Baumriesen, die Dornen nach außen gelassen. Was die Hand darin trifft, blutet für die Mühe." },
  "thornvine_whip": { en: "A thorn wolf's spine-vine, dried hard and swung like a blade. The thorns stay in, and what they start does not stop early.", de: "Die Dornranke eines Dornwolfs, hart getrocknet und wie eine Klinge geführt. Die Dornen bleiben stecken, und was sie anrichten, hält an." },
  "tidecaller_focus": { en: "A drowned sailor's lantern, the glass gone green, the flame no longer fire. Every kill pours a little back into the ward.", de: "Die Laterne eines Ertrunkenen, das Glas grün geworden, die Flamme kein Feuer mehr. Jeder Kill gießt ein wenig in den Ward zurück." },
  "tideterror_grip": { en: "The grip of Lorelith of the Drowned Choir, salt-crusted and cold. Every wound it deals pours a little back into the ward of the hand that wears it.", de: "Der Griff von Lorelith vom Ertrunkenen Chor, salzverkrustet und kalt. Jede Wunde, die er schlägt, gießt etwas in den Ward der Hand zurück." },
  "tidewalker_boots": { en: "Boots the tide sirens leave on the rocks, the leather gone the color of kelp. They never slip on wet stone, and after a kill they walk on sooner.", de: "Stiefel von den Felsen der Gezeitensirenen, das Leder tangfarben. Sie rutschen nie auf nassem Stein, und nach einem Kill geht es schneller weiter." },
  "tidewoven_leggings": { en: "Leggings of siren hair and sailcloth, salt-stiff and cold. The sea gives nothing back small. These were made for what it does give back.", de: "Beinlinge aus Sirenenhaar und Segeltuch, salzsteif und kalt. Die See gibt nichts Kleines zurück. Gemacht für das, was sie zurückgibt." },
  "tin_ore": { en: "Dull grey ore that is worth little on its own. Melted together with copper it becomes bronze, which is worth a great deal more.", de: "Mattgraues Erz, das allein wenig taugt. Mit Kupfer zusammengeschmolzen wird Bronze daraus, und die taugt eine Menge mehr." },
  // claude:2026-10-25T18:57:00+01:00 — Regenerations-Satz gestrichen (Buff hat keine LP-Regeneration mehr)
  "tincture_gloomspore": { en: "Gloomspore steeped in oil until it glows. The strikes come quicker and land truer.", de: "Düstersporen, in Öl gezogen, bis es leuchtet. Die Schläge kommen schneller und sitzen besser." },
  "titanium_arrow": { en: "Titanium over shaft and feather, light enough to shoot all day. It takes a barb, a poison or a fire as well as bloodiron does.", de: "Titan über Schaft und Feder, leicht genug, um den ganzen Tag zu schießen. Nimmt Widerhaken, Gift oder Feuer genauso an wie Bluteisen." },
  "titanium_arrowheads": { en: "Titanium heads that weigh almost nothing, forty-five to the bar. The arrow carries further and the archer carries more.", de: "Titanspitzen, die fast nichts wiegen, fünfundvierzig je Barren. Der Pfeil trägt weiter, und der Schütze trägt mehr." },
  "titanium_axe": { en: "Pale titanium, so light the swing has to come from the hips. It shrugs off the years the way it shrugs off bark.", de: "Blasses Titan, so leicht, dass der Schwung aus der Hüfte kommen muss. Es trotzt den Jahren, wie es der Rinde trotzt." },
  "titanium_battleaxe": { en: "Titanium so light the head is forged twice as broad so it will bite. It bites.", de: "Titan, so leicht, dass der Kopf doppelt so breit geschmiedet wird, damit er beißt. Er beißt." },
  "titanium_chainbody": { en: "Titanium rings so light the hauberk feels like linen. It is not linen. What goes through linen does not go through this.", de: "Titanringe, so leicht, dass das Kettenhemd sich wie Leinen anfühlt. Es ist keines. Was durch Leinen geht, geht hier nicht durch." },
  "titanium_dagger": { en: "Titanium, pale and almost nothing in the hand. The weight is all in the point, and the point is all that matters.", de: "Titan, blass und fast nichts in der Hand. Das Gewicht sitzt ganz in der Spitze, und auf die Spitze kommt es an." },
  "titanium_focus": { en: "Titanium with void essence bound into it, pale and almost weightless. It makes room in the head where there was none.", de: "Titan mit Leerenessenz darin, blass und fast schwerelos. Es schafft Platz im Kopf, wo keiner war." },
  "titanium_fullhelm": { en: "Titanium closed over the whole head, pale and so light the neck forgets it. The visor is thin as paper and stops a mace.", de: "Titan um den ganzen Kopf, blass und so leicht, dass der Nacken ihn vergisst. Das Visier ist dünn wie Papier und hält einen Kolben auf." },
  "titanium_gauntlets": { en: "Titanium over the hands, pale and almost nothing. You forget them until you catch a blade on the back of one.", de: "Titan über den Händen, blass und fast nichts. Man vergisst sie, bis man eine Klinge mit dem Handrücken fängt." },
  "titanium_greataxe": { en: "Titanium makes the greataxe quick for its size. The size is still considerable.", de: "Titan macht die Großaxt schnell für ihre Größe. Die Größe bleibt beachtlich." },
  "titanium_greatsword": { en: "Titanium, pale, a greatsword that weighs what a sword should. Only the reach reminds the arm.", de: "Titan, blass, ein Großschwert, das wiegt, was ein Schwert wiegen sollte. Nur die Reichweite erinnert den Arm daran." },
  "titanium_kiteshield": { en: "Titanium in a teardrop, pale and almost weightless. The arm keeps checking it is still there. It is.", de: "Titan in Tropfenform, blass und fast schwerelos. Der Arm prüft immer wieder, ob er noch da ist. Ist er." },
  "titanium_longbow": { en: "Wraithwood, grey and almost weightless, from trees that stopped being entirely trees. The arrow is gone before the string is heard.", de: "Geisterholz, grau und fast schwerelos, von Bäumen, die aufgehört haben, ganz Bäume zu sein. Der Pfeil ist weg, bevor man die Sehne hört." },
  "titanium_mace": { en: "Titanium, pale and quick. A mace that light should not get through plate. It does, which annoys the smiths.", de: "Titan, blass und schnell. So ein leichter Kolben sollte nicht durch Platte gehen. Er tut es, was die Schmiede ärgert." },
  "titanium_maul": { en: "Titanium makes a maul the arm can live with. The enemy's armor cannot.", de: "Titan macht einen Hammer, mit dem der Arm leben kann. Die Rüstung des Gegners nicht." },
  "titanium_medhelm": { en: "A titanium cap, open at the face. It weighs less than the padding under it.", de: "Eine Titankappe, am Gesicht offen. Wiegt weniger als die Polsterung darunter." },
  "titanium_ore": { en: "Grey ore that weighs almost nothing in the hand. The Iron Sentinels of the Crypt carry it in their frames, which is one way to get it.", de: "Graues Erz, das in der Hand fast nichts wiegt. Die Eisernen Wächter der Krypta tragen es im Gestell, und das ist ein Weg, daran zu kommen." },
  "titanium_platebody": { en: "A titanium breastplate, pale and nearly weightless. You breathe in it as if wearing nothing. The blows find that less amusing.", de: "Ein Titan-Brustpanzer, blass und fast schwerelos. Man atmet darin, als trüge man nichts. Die Schläge finden das weniger lustig." },
  "titanium_platelegs": { en: "Titanium greaves, pale and so light you check they are still buckled. They are. They always are.", de: "Titan-Beinschienen, blass und so leicht, dass du prüfst, ob sie noch geschnallt sind. Sind sie. Immer." },
  "titanium_sabatons": { en: "Titanium over the boots, pale and nearly weightless. You walk like you are barefoot and arrive like you are not.", de: "Titan über den Stiefeln, blass und fast schwerelos. Man geht wie barfuß und kommt an, als wäre man es nicht." },
  "titanium_scimitar": { en: "Titanium weighs so little the curve does the work. Each stroke rolls into the next without asking.", de: "Titan wiegt so wenig, dass die Kurve die Arbeit macht. Jeder Hieb rollt in den nächsten, ohne zu fragen." },
  "titanium_shortbow": { en: "Wraithwood bent short, grey and almost weightless. The shots come faster as they go, like something hurrying to be elsewhere.", de: "Geisterholz, kurz gebogen, grau und fast schwerelos. Die Schüsse werden schneller, als wollte etwas eilig woanders sein." },
  "titanium_spear": { en: "Titanium so light the spear could be thrown and caught. Nobody does. It is faster to keep thrusting.", de: "Titan, so leicht, dass man den Speer werfen und fangen könnte. Niemand tut es. Weiterstoßen geht schneller." },
  "titanium_staff": { en: "Pale titanium with aether set along its length. Its light does not burn. It blesses, and the blessing holds like a ward.", de: "Blasses Titan, Aether entlang des Schafts gefasst. Sein Licht brennt nicht. Es segnet, und der Segen hält wie ein Ward." },
  "titanium_sword": { en: "Titanium, pale, a sword that forgets it is in your hand until it is needed. Then it remembers all at once.", de: "Titan, blass, ein Schwert, das vergisst, dass es in deiner Hand liegt, bis es gebraucht wird. Dann erinnert es sich auf einmal." },
  "titanium_towershield": { en: "A tower shield light enough to run with. The smiths said it could not be done. Then they did it.", de: "Ein Turmschild, leicht genug, um damit zu rennen. Die Schmiede sagten, das gehe nicht. Dann taten sie es." },
  "titanium_wand": { en: "Titanium with a storm shard at the tip, light enough to forget you hold it until it discharges.", de: "Titan mit einem Sturmsplitter an der Spitze, so leicht, dass man ihn vergisst, bis er sich entlädt." },
  "tombplate_greaves": { en: "A skeleton butcher's greaves from the Crypt, tomb plate under tomb rust. The butcher was small. It went for the big ones anyway.", de: "Beinschienen eines Skelett-Schlächters aus der Krypta, Grabplatte unter Grabrost. Der Schlächter war klein. Er ging trotzdem auf die Großen." },
  "tonic_apex": { en: "Godsbreath and divine essence in oil. For a short while every strike is the one you meant, and they come one after the other.", de: "Götteratem und Göttliche Essenz in Öl. Eine kurze Weile ist jeder Schlag der gemeinte, und sie kommen Schlag auf Schlag." },
  "tonic_arcane_surge": { en: "Gravemoss and grave essence in oil, a caster's version of the bulwark brew. The reserve runs deeper and the spells come out sharper.", de: "Grabmoos und Grabessenz in Öl, die Zaubererfassung des Bollwerk-Suds. Die Zauberreserve reicht tiefer, die Sprüche kommen schärfer." },
  "tonic_bloodrage": { en: "Bloodthistle and mire essence, the same base as the keen-eye brew, drawn hot instead of cold. It goes to the arm rather than the eye.", de: "Blutdistel und Sumpfessenz, derselbe Ansatz wie beim Scharfaugen-Tonikum, nur heiß statt kalt gezogen. Es geht in den Arm, nicht ins Auge." },
  "tonic_bounty": { en: "Gravemoss and grave essence in plain water. Taken before work, the hands come back fuller than the work should allow.", de: "Grabmoos und Grabessenz in schlichtem Wasser. Vor der Arbeit genommen, kommen die Hände voller zurück, als die Arbeit erlaubt." },
  "tonic_bulwark": { en: "Gravemoss and grave essence in oil. The shield arm stops arguing with the shield, and more blows land on wood than on flesh.", de: "Grabmoos und Grabessenz in Öl. Der Schildarm hört auf, mit dem Schild zu streiten, und mehr Hiebe landen auf Holz als auf Fleisch." },
  "tonic_emberleaf": { en: "Emberleaf steeped in water, the Cinderwood's own remedy. A little more life in the body, and the rest grows back on its own.", de: "Glutblatt in Wasser gezogen, das Hausmittel des Glutwalds. Etwas mehr Leben im Leib, und der Rest wächst von selbst nach." },
  "tonic_forager_i": { en: "Marshroot and a sootcap in water, the first tonic a gatherer brews. The work teaches a little more while it lasts.", de: "Sumpfwurzel und eine Rußkappe in Wasser, das erste Tonikum, das ein Sammler braut. Die Arbeit lehrt ein wenig mehr, solange es wirkt." },
  "tonic_forager_ii": { en: "Bloodthistle and pale fungus in water. Stronger than the first brew, and what a day's work teaches sticks a little better.", de: "Blutdistel und Bleich-Pilz in Wasser. Stärker als der erste Sud, und was ein Arbeitstag lehrt, bleibt etwas besser hängen." },
  "tonic_godharvest": { en: "Godsbreath and godspark fungus in water. The strongest of the working brews: whatever the hands do, they learn it quicker.", de: "Götteratem und Götterfunken-Pilz in Wasser. Der stärkste der Arbeitssude: Was die Hände auch tun, sie lernen es schneller." },
  "tonic_harvest": { en: "Gravemoss and grave fungus in water, drunk before a long shift. Every skill practised that day learns faster.", de: "Grabmoos und Grab-Pilz in Wasser, vor einer langen Schicht getrunken. Jede Fertigkeit, die man an dem Tag übt, lernt schneller." },
  "tonic_ironbark": { en: "Nightbloom and hollow essence in oil, named for what it does to the skin. For a short while the body takes blows the way bark takes rain.", de: "Nachtblüte und Hohle Essenz in Öl, benannt nach dem, was es mit der Haut macht. Eine kurze Weile nimmt der Leib Schläge, wie Rinde Regen nimmt." },
  "tonic_keeneye": { en: "Bloodthistle and mire essence in oil. The eye picks up the swing a heartbeat sooner, and a heartbeat is enough to not be there.", de: "Blutdistel und Sumpfessenz in Öl. Das Auge sieht den Hieb einen Herzschlag früher, und ein Herzschlag reicht, um nicht mehr da zu sein." },
  "tonic_oxblood": { en: "Marshroot and ash essence in oil, thick and red-brown. The arm runs ahead of the head for a minute or so.", de: "Sumpfwurzel und Ascheessenz in Öl, dick und rotbraun. Der Arm ist dem Kopf für etwa eine Minute voraus." },
  "tonic_rot_ward": { en: "Two rot glands boiled in water. It smells exactly as you fear, clears the rot from the blood and leaves the body a little tougher for it.", de: "Zwei verfaulte Drüsen, in Wasser gekocht. Riecht genau so, wie du fürchtest, treibt die Fäulnis aus dem Blut und lässt den Leib zäher zurück." },
  "tonic_stoneskin": { en: "The same marshroot base as the oxblood brew, drawn longer. The skin sets like plaster and turns a blow or two it had no business turning.", de: "Derselbe Sumpfwurzel-Ansatz wie beim Ochsenblut, nur länger gezogen. Die Haut wird fest wie Putz und hält Hiebe aus, die sie nichts angehen." },
  "tonic_warpath": { en: "Nightbloom and hollow essence in oil, brewed for the minute before a charge. Faster strikes, harder ones, and it is over before you miss it.", de: "Nachtblüte und Hohle Essenz in Öl, gebraut für die Minute vor dem Sturm. Schnellere Schläge, härtere Treffer, und vorbei, bevor du es vermisst." },
  // claude:2026-10-25T18:57:00+01:00 — Regenerations-Satz gestrichen (Buff hat keine LP-Regeneration mehr)
  "tonic_witchlight": { en: "Witchlight dust in water, glowing faintly in the vial. It shows you the gap in every guard.", de: "Irrlicht-Staub in Wasser, schwach leuchtend. Zeigt dir die Lücke in jeder Deckung." },
  "umberleaf_seed": { en: "A brown seed found where the ash essence is gathered. The leaf it grows is crushed for umber pigment.", de: "Ein brauner Same, gefunden, wo die Ascheessenz gesammelt wird. Das Blatt, das daraus wächst, wird zu Umbra-Pigment zerstoßen." },
  "venison_roast": { en: "Wildwood venison roasted slow. Lean, dark and gamey, and the smoke does it good.", de: "Wildwald-Hirsch, langsam gebraten. Mager, dunkel und kräftig, und der Rauch tut ihm gut." },
  "verdantcap_seed": { en: "A green spore cap found among the grave fungus. The mushroom it grows is crushed for verdant pigment.", de: "Eine grüne Sporenkappe, zwischen den Grabpilzen gefunden. Der Pilz, der daraus wächst, wird zu Grün-Pigment zerstoßen." },
  "vial_of_water": { en: "A stoppered vial of clean water, which is rarer in the Reach than it sounds. Most draughts and a few stews begin with one.", de: "Ein verkorktes Fläschchen sauberes Wasser, im Reach seltener, als es klingt. Die meisten Tränke und ein paar Eintöpfe beginnen damit." },
  "violetbloom_seed": { en: "A purple seed found among the nightbloom. The flower it grows is crushed for violet pigment.", de: "Ein violetter Same, zwischen den Nachtblüten gefunden. Die Blüte, die daraus wächst, wird zu Violett-Pigment zerstoßen." },
  "void_essence": { en: "The last state of the thinning veil, drawn from what crawls out of the Crypt, the Highlands and the Idol Hall. It goes into void shards and the darkest tools.", de: "Der letzte Zustand des Schleiers, gewonnen aus dem, was aus Krypta, Hochland und Götzenhalle kriecht. Runenkundige binden sie zu Leerensplittern." },
  "void_focus": { en: "Six void shards and a sapphire set in a runite blank. The sapphire is there so the void has something to look at other than you.", de: "Sechs Leerensplitter und ein Saphir in einem Runitrohling. Der Saphir ist da, damit die Leere etwas anderes anschaut als dich." },
  "void_rod": { en: "Ironbark bound with a drop of void essence. The line goes slack and taut in ways that have nothing to do with the current.", de: "Eisenrinde, gebunden mit einem Tropfen Leerenessenz. Die Schnur spannt und lockert sich auf eine Art, die nichts mit der Strömung zu tun hat." },
  "void_rune": { en: "Two measures of void essence for a single shard, and the shard is worth it. Ghostleather, voidweave and the void focus all ask for them by the handful.", de: "Zwei Maß Leerenessenz für einen einzigen Splitter, und er ist es wert. Geisterleder, Leerengewebe und der Leeren-Fokus verlangen sie handvollweise." },
  "void_sickle": { en: "Runite quenched in void essence until the edge went dark. Whatever it cuts is in no hurry to grow back.", de: "Runit, in Leerenessenz abgeschreckt, bis die Schneide dunkel wurde. Was sie schneidet, wächst so bald nicht nach." },
  "void_titan_mantle": { en: "The mantle of the Void Titan, cut from the part of it that was here. Heavier than cloth and lighter than it should be, and the wounds under it close on their own.", de: "Der Mantel des Leeren-Titanen, aus dem Teil von ihm geschnitten, der hier war. Leichter, als er sein sollte, und die Wunden darunter schließen sich von selbst." },
  "voidbloom": { en: "A flower from the Void Heath, dark petals on a stem that is never quite warm. Two of them and a wraithcap make the revenant elixir.", de: "Eine Blume von der Leerenheide, dunkel, an einem Stängel, der nie warm wird. Zwei davon und eine Wichtkappe geben das Wiedergänger-Elixier." },
  "voidcaller_staff": { en: "Two rubies and eight void shards bound to one haft. It calls to what sits behind the veil, and sometimes something answers.", de: "Zwei Rubine und acht Leerensplitter an einem Schaft. Er ruft, was hinter dem Schleier sitzt, und manchmal antwortet etwas." },
  "voidhide_body": { en: "Shadowhide bound with void and aether, the last leather on the ladder. A cuirass that is barely there, and the blows that look for it are not there either.", de: "Schattenleder, mit Leere und Aether gebunden, das letzte Leder der Leiter. Ein Kürass, der kaum da ist, und Schläge finden ihn nicht." },
  "voidhide_boots": { en: "Shadowhide bound with void and aether into boots that are barely there. The ground does not notice them. Neither does the enemy.", de: "Schattenleder, mit Leere und Aether zu Stiefeln gebunden, die kaum da sind. Der Boden bemerkt sie nicht. Der Gegner auch nicht." },
  "voidhide_helm": { en: "Shadowhide bound with void shards and a breath of aether, the top of the tanner's craft. A coif that is barely there, over a head that barely is.", de: "Schattenleder, mit Leere und Aether gebunden, das Höchste der Gerberkunst. Eine Haube, die kaum da ist, über einem Kopf, der es auch kaum ist." },
  "voidhide_legs": { en: "Shadowhide bound with void and aether into greaves that are barely there. A step in them leaves no print and makes no sound.", de: "Schattenleder, mit Leere und Aether zu Beinschienen gebunden, die kaum da sind. Ein Schritt darin hinterlässt keine Spur und keinen Laut." },
  "voidhide_vambraces": { en: "Shadowhide bound with void and aether, wrapped around an arm that is barely there. The string finds nothing to catch on.", de: "Schattenleder, mit Leere und Aether gebunden, um einen Arm gewickelt, der kaum da ist. Die Sehne findet nichts, woran sie hängen bleibt." },
  "voidray_banquet": { en: "Voidray and wyvern laid over ambergrain, with godsbreath for the scent. A fighter's banquet: strength, endurance and thicker armour.", de: "Leerenrochen und Wyvern über Bernsteingetreide, der Götteratem gibt den Duft. Ein Kämpferbankett: Kraft, Ausdauer, dickere Rüstung." },
  "voidreed_seed": { en: "A dark reed seed found among the godsbreath. The reed it grows is the only one the strongest runes will take.", de: "Ein dunkler Schilfsamen, zwischen dem Götteratem gefunden. Das Schilf, das daraus wächst, ist das einzige, das die stärksten Runen annehmen." },
  "voidstalker_cloak": { en: "A void stalker's hide from the Whispering Void, which was not there until it was. The first blow from under it is the one that lands.", de: "Die Haut eines Leerenjägers aus der Flüsternden Leere, der nicht da war, bis er es war. Der erste Schlag darunter ist der, der sitzt." },
  "voidstone": { en: "Cut, and it still swallows the light. Set in bloodiron or titanium, it makes the rings and chains of those who hunt by night.", de: "Geschliffen, und er schluckt das Licht noch immer. In Bluteisen oder Titan gefasst gibt er die Ringe und Ketten derer, die bei Nacht jagen." },
  "voidstone_amulet": { en: "A voidstone in bloodiron, the hollow in the red. It weighs more than it should, and armor matters less to whatever wears it.", de: "Ein Leerenstein in Bluteisen, das Loch im Rot. Wiegt mehr, als es sollte, und Rüstung zählt weniger gegen den, der es trägt." },
  "voidstone_ring": { en: "A voidstone in bloodiron, the hollow in the red. It weighs more than a ring should, and armor weighs less against it.", de: "Ein Leerenstein in Bluteisen, das Loch im Rot. Wiegt mehr, als ein Ring sollte, und Rüstung wiegt weniger dagegen." },
  "voidtouched_gauntlets": { en: "Gauntlets from the Idol Hall, worn by the servants who were left behind. The void got into the fingers and never left. The wounds under them close on their own.", de: "Stulpen aus der Götzenhalle, getragen von den Dienern, die zurückgelassen wurden. Die Leere drang in die Finger und ging nie wieder. Die Wunden darunter schließen sich von selbst." },
  "voidwing_greatbow": { en: "A wing bone of the Void Titan, strung across the gap where it was not entirely there. Arrows loosed from it come out burning, and the first one does not miss.", de: "Ein Flügelknochen des Leeren-Titanen, über die Lücke gespannt, in der er nicht ganz da war. Pfeile daraus brennen, und der erste geht nicht fehl." },
  "voidwood_log": { en: "Timber from trees that grew where the veil is thinnest. It swallows light, and a pavise cut from it swallows blows.", de: "Holz von Bäumen, die wuchsen, wo der Schleier am dünnsten ist. Es schluckt Licht, und eine Pavese daraus schluckt Hiebe." },
  "voidwood_pavise": { en: "A pavise of voidwood, tall and dark, from trees that grew where the veil is thin. Arrows that hit it seem to lose interest.", de: "Eine Pavese aus Leerenholz, hoch und dunkel, von Bäumen, die wuchsen, wo der Schleier dünn ist. Pfeile, die sie treffen, verlieren das Interesse." },
  "wailing_wand": { en: "A sliver of wailing shade from the Mirror Halls, bound in wire so it cannot drift off. It still hums the note it died on.", de: "Ein Span Klagender Schatten aus den Spiegelhallen, in Draht gebunden, damit er nicht davontreibt. Er summt noch den Ton, auf dem er starb." },
  "warband_hauberk": { en: "A Warband crossbower's hauberk, Reach mail with goblin patches sewn over the holes. Hit the one wearing it, and the hit comes back.", de: "Der Panzer eines Armbrusters der Kriegsbande, Reach-Kettenhemd mit Goblinflicken über den Löchern. Wer den Träger trifft, bekommt es zurück." },
  "warband_key": { en: "An old goblin key, cut for a gate that no longer has a lock. The warband's camp stands open to anyone who has earned the way.", de: "Ein alter Goblinschlüssel für ein Tor, das kein Schloss mehr hat. Das Lager der Kriegsbande steht jedem offen, der sich den Weg verdient hat." },
  "warband_seal": { en: "The warchief's seal, taken from his body at the end of the warband. Set in bronze, it becomes a signet ring the goblins would not argue with.", de: "Das Siegel des Kriegshäuptlings, am Ende der Kriegsbande von ihm genommen. In Bronze gefasst wird ein Siegelring daraus, dem kein Goblin widerspricht." },
  "warband_signet": { en: "The Warband Seal set in bronze. The goblins gave it to their officers. An army whose seal anyone can wear is not an army.", de: "Das Kriegsbanden-Siegel in Bronze gefasst. Die Goblins gaben es ihren Offizieren. Ein Heer, dessen Siegel jeder tragen kann, ist kein Heer." },
  "warbanner_cape": { en: "A Warband banner, torn down and worn as a cape. The warlock did not care what it stood for. Strike the one wearing it, and the strike comes back.", de: "Ein Banner der Kriegsbande, als Umhang getragen. Dem Hexenmeister war gleich, wofür es stand. Wer den Träger trifft, bekommt es zurück." },
  "warden_greatcloak": { en: "The Forest Warden's cloak, bark and leaf and something that is still growing. Strike its wearer, and the forest answers.", de: "Der Mantel des Waldvogts, Rinde und Laub und etwas, das noch wächst. Wer seinen Träger schlägt, bekommt Antwort vom Wald." },
  "warhide_body": { en: "Four warhides into one cuirass, from beasts that fought for every year of their lives. It has turned blades before. It expects more.", de: "Vier Kriegsleder zu einem Kürass, von Tieren, die um jedes Jahr kämpften. Es hat Klingen abgehalten. Es rechnet mit mehr." },
  "warhide_boots": { en: "Warhide treads from beasts that fought for every year of their lives. They have walked away from worse than this.", de: "Kriegslederstiefel von Tieren, die um jedes Jahr ihres Lebens kämpften. Sie sind aus Schlimmerem herausgegangen als dem hier." },
  "warhide_helm": { en: "Warhide from something that fought for every year of its life, shaped into a helm. It turned blades before it was ever cut.", de: "Kriegsleder von etwas, das um jedes Jahr seines Lebens kämpfte, zu einem Helm geformt. Es hat Klingen abgehalten, bevor es zugeschnitten war." },
  "warhide_legs": { en: "Warhide greaves from beasts that fought for every year of their lives. The hide was armor before it was ever cut.", de: "Kriegsleder-Beinschienen von Tieren, die um jedes Jahr ihres Lebens kämpften. Die Haut war Rüstung, bevor sie je zugeschnitten wurde." },
  "warhide_vambraces": { en: "Warhide around the forearm, from something that fought for every year of its life. It turned blades before it was leather.", de: "Kriegsleder um den Unterarm, von etwas, das um jedes Jahr seines Lebens kämpfte. Es hielt Klingen ab, bevor es Leder war." },
  "warlock_felstaff": { en: "Taken from the Warband's warlocks. The fire it throws is borrowed from the Creditor, and every spark of it is still owed.", de: "Den Hexenmeistern der Kriegsbande abgenommen. Das Feuer, das er wirft, ist beim Gläubiger geliehen, und jeder Funke steht noch offen." },
  "wattle_shield": { en: "Woven hazel from a broken fence, bound with wire. The cows leaned on it for years and it never gave. It does not give now.", de: "Geflochtene Hasel aus einem kaputten Zaun, mit Draht gebunden. Jahrelang lehnten die Kühe daran, und er gab nie nach. Er tut es auch jetzt nicht." },
  "wildhive_honey": { en: "Dark honey robbed from wild combs, with the odd bee still in it. Baked into grimwheat, it makes a cake worth the stings.", de: "Dunkler Honig, aus wilden Waben geraubt, die eine oder andere Biene noch darin. In Grimmkorn gebacken gibt er einen Kuchen, der die Stiche lohnt." },
  "wildwood_key": { en: "A key of antler and iron that once opened the hunting grounds. The Wildwood takes no key any more, only a hunter who has earned it.", de: "Ein Schlüssel aus Geweih und Eisen, der einst die Jagdgründe öffnete. Der Wildwald nimmt keinen Schlüssel mehr, nur einen Jäger, der ihn verdient." },
  "wildwood_treads": { en: "Treads left where the Spectral Stag passed, soled with something that is not quite hide. In them, the next fight comes sooner after the last.", de: "Schuhe, zurückgelassen, wo der Geisterhirsch ging, besohlt mit etwas, das nicht ganz Haut ist. Der nächste Kampf kommt darin schneller." },
  "willowbark_log": { en: "Willow from the riverbank, bendy and tough. It is no good for a bow, but a shield cut from it takes a blow and springs back.", de: "Weide vom Flussufer, biegsam und zäh. Für einen Bogen taugt sie nichts, doch ein Schild daraus nimmt einen Hieb und federt zurück." },
  "willowbark_shield": { en: "Willowbark on a frame of the same wood, light enough that the arm forgets it. The first shield from your own hands that is worth carrying.", de: "Weidenbark auf einem Rahmen aus demselben Holz, so leicht, dass der Arm ihn vergisst. Der erste Schild aus eigener Hand, der das Tragen lohnt." },
  "witchgrass": { en: "Coarse grass from the Blightmarsh, sharp-edged and bitter. Ground into bloodbeet, it makes the salve of mending.", de: "Grobes Gras aus dem Seuchensumpf, scharfkantig und bitter. In Blutrübe zerrieben gibt es die Salbe der Heilung." },
  "witchroot_wand": { en: "A root from the Bramble Witch's own thicket. The cold in it is the forest's, patient and slow, and it bites whatever slows.", de: "Eine Wurzel aus dem Dickicht der Rankenhexe selbst. Die Kälte darin ist die des Waldes, geduldig und langsam, und sie beißt, was langsam wird." },
  "wither_leek": { en: "A leek that wilts as it grows and never quite dies. Three of the cook's best dishes are built around it, one for each way of fighting.", de: "Ein Lauch, der beim Wachsen welkt und nie ganz stirbt. Drei der besten Gerichte des Kochs bauen darauf, eines für jede Art zu kämpfen." },
  "witherleek_arcane_broth": { en: "Wraithscale and venison boiled thin with witherleek and nightbloom, for those who fight with their heads. Sharpens the mind and widens the ward.", de: "Geisterschupper und Hirsch, dünn gekocht mit Welklauch und Nachtblüte, für alle, die mit dem Kopf kämpfen. Schärft den Geist, weitet den Ward." },
  "witherleek_bouillabaisse": { en: "Wraithscale and venison simmered with witherleek, the way the coast would cook it if the coast had deer. Builds strength and thickens the hide.", de: "Geisterschupper und Hirsch, mit Welklauch gesimmert, wie die Küste es kochen würde, hätte die Küste Hirsche. Bringt Kraft und härtet die Haut." },
  "witherleek_seed": { en: "A grey seed found among the nightbloom. The leek it grows looks half dead from the day it sprouts and tastes better for it.", de: "Ein grauer Same zwischen den Nachtblüten. Der Lauch daraus sieht vom ersten Tag an halb tot aus und schmeckt umso besser." },
  "witherleek_sharpshooters_pie": { en: "Wraithscale and venison baked under a witherleek crust. A sharpshooter's pie: the eye steadies and the feet stay light.", de: "Geisterschupper und Hirsch, unter einer Welklauchkruste gebacken. Eine Scharfschützen-Pastete: Das Auge wird ruhig, die Füße bleiben leicht." },
  "wolf_steak": { en: "Wolf haunch seared hard on both sides. Tough, bloody and better than it has any right to be.", de: "Wolfskeule, von beiden Seiten scharf angebraten. Zäh, blutig und besser, als sie sein dürfte." },
  "wolffang_spear": { en: "A gray wolf's fang bound to a Wildwood shaft. It tears, and whatever hunts beside you hunts harder for it.", de: "Der Reißzahn eines Grauwolfs an einen Wildwaldschaft gebunden. Er reißt, und was neben dir jagt, jagt dadurch härter." },
  "wolfpelt_hood": { en: "A gray wolf's scalp and ears worn as a hood, the teeth left in. The Wildwood takes you for one of its own, briefly, and every kill feeds the pelt.", de: "Kopfhaut und Ohren eines Grauwolfs als Kapuze, die Zähne noch drin. Der Wildwald hält dich für einen der Seinen, und jeder Kill nährt das Fell." },
  "wooden_shield": { en: "Planks and a strap, the kind Mux sells and the goblin shamans carry. It holds until it does not.", de: "Bretter und ein Riemen, wie Mux sie verkauft und die Goblin-Schamanen sie tragen. Er hält, bis er es nicht mehr tut." },
  "worn_workgloves": { en: "Work gloves from an empty farmyard, worn through at the palm. They grip hardest when things are going badly.", de: "Arbeitshandschuhe vom leeren Hof, an der Handfläche durch. Sie greifen am härtesten, wenn es schlimm steht." },
  "wraithcap": { en: "A pale mushroom that leans away from lantern light. One of them and two voidblooms make the revenant elixir.", de: "Ein blasser Pilz, der sich vor Laternenlicht wegneigt. Einer davon und zwei Leerenblüten geben das Wiedergänger-Elixier." },
  "wraithhide_body": { en: "Dragonhide steeped in void shards until the color went out of it. A cuirass that is greyer than the shadow it casts.", de: "Drachenleder, in Leerensplittern gezogen, bis die Farbe daraus wich. Ein Kürass, grauer als der Schatten, den er wirft." },
  "wraithhide_boots": { en: "Dragonhide gone grey in void shards, made into boots that leave a fainter print than the foot inside them.", de: "Drachenleder, in Leerensplittern grau geworden, zu Stiefeln gemacht, die eine schwächere Spur lassen als der Fuß darin." },
  "wraithhide_helm": { en: "Dragonhide steeped in void shards until it went grey and quiet. A coif that does not quite cast a shadow.", de: "Drachenleder, in Leerensplittern gezogen, bis es grau und still wurde. Eine Haube, die nicht ganz einen Schatten wirft." },
  "wraithhide_legs": { en: "Dragonhide gone grey in a bath of void shards. Greaves that are quieter than the legs inside them.", de: "Drachenleder, in einem Bad aus Leerensplittern grau geworden. Beinschienen, leiser als die Beine darin." },
  "wraithhide_vambraces": { en: "Dragonhide gone grey in void shards, wrapped around the forearm. The arm casts less shadow than it should.", de: "Drachenleder, in Leerensplittern grau geworden, um den Unterarm gewickelt. Der Arm wirft weniger Schatten, als er sollte." },
  "wraithwood_log": { en: "Pale wood that is cold to the touch and lighter than it should be. Bows carved from it draw almost without a sound.", de: "Bleiches Holz, kalt in der Hand und leichter, als es sein sollte. Bögen daraus spannen fast ohne Laut." },
  "wreathbound_staff": { en: "A wreath bearer's staff from the Idol Hall, the godiron wreaths still fused to the shaft. Made for foes larger than its bearer.", de: "Stab eines Kranzträgers der Götzenhalle, die Kränze aus Götzeneisen noch am Schaft. Gemacht für Gegner, die größer sind als sein Träger." },
  "wyvern_steak": { en: "Wyvern haunch charred over a high flame. Black outside, red within, and it carries a fighter up a long climb.", de: "Wyvern-Braten, über hoher Flamme flambiert. Außen schwarz, innen rot, und er trägt einen Kämpfer einen langen Aufstieg weit." },
  "wyvernscale_aegis": { en: "Wyvern scales from the high nests, laid over leather, light and ringing. Made for the ridge, and the first cut from behind it lands deepest.", de: "Wyvernschuppen aus den hohen Nestern über Leder, leicht und klingend. Gemacht für den Grat, und der erste Schnitt dahinter sitzt am tiefsten." },
  "wyvernscale_greaves": { en: "Wyvern scales over leather, from the high nests where the veil is thin. Each step in them comes easier than the last.", de: "Wyvernschuppen über Leder, aus den hohen Nestern, wo der Schleier dünn ist. Jeder Schritt darin fällt leichter als der vorige." },
};
